window.__D("text/likkutei-sichot/c103",{"p":[[1300161060,"אויך די ניצוצות שבזדונות נתעלה אין קדושה31.\n[ועד״ז אין דעם בעל תשובה עצמו: אע״פ אז בגלוי איז ער געווען אפגע־ריסן פון אלקות (דורך זיינע חטאים), איז אבער אויך בשעת החטא פארבליבן זיין עצמית׳דיקער פארבונד מיט אלקות, וואס קומט צום אויסדרוק בגלוי אין זיין אומקערן זיך צו דעם אויבערשטן נאך דעם ווי ער איז געווען אפגעריסן].\nומהאי טעמא, איז אויך דער עילוי הנ״ל אין דעם יש הנברא, פון גשמיות עוה״ז (וואס דער אלטער רבי איז מבאר אין אגרת איהו וחיוהי חד) ווערט דער־הערט (בעיקר) ביי אַ בעל תשובה32.\nז. ועפ״ז וועט ווערן פארשטאַנדיק די שייכות פון דער אגרת איהו וחיוהי חד מיט דער רשימה „נפש השפלה״ צו זמן ההסתלקות פון אלטן רבי״ן:\nדער עילוי וואס ווערט ארויסגע־בראכט אין עבודת התשובה (על זדונות) איז (בעיקר) ניטאָ ביי אַ צדיק מצד עצמו33; אבער דורך דעם וואס ער ברענגט אַ צווייטן צו תשובה, באקומט ער אויך דעם עילוי34 (וויבאלד אז ער האט געבראכט דעם צווייטן35 צו טאָן\nתשובה).\nנאר דער עיקר הגילוי פון מעלת התשובה איז דוקא סמוך להסתלקותו36 ווען עס קומען זיך צוזאמען „כל מעשיו ותורתו ועבודתו אשר עבד כל ימי חייו״37. ובפרט, אז וויבאלד ער שטייט דאן אין דער תנועה פון תשובה — והרוח תשוב אל האלקים אשר נתנה — ביתר שאת ויתר עז, וערט ביי אַ צדיק, (ובפרט ביי אַ אזא) וואס האט עוסק גע־ווען אין מאכן בעלי תשובה, נתגלה אין זיין תנועת התשובה, אויך דער עילוי וואס אין דער עבודת התשובה שעל זדונות.\nועד״ז בענינינו: ס׳איז ידוע38 וואס דער אלטער רבי האט געזאגט דעם מיטל׳ן רבי״ן, אז זיין, דעם אלטן רבינ׳ס אויפטו (לגבי המגיד) באשטייט אין דעם וואס ער איז געלעגן אין מאכן בעלי תשובה (און ווי כ״ק מו״ח אדמו״ר איז מאריך וועגן דעם אין זיין שיחה<sup data-n=\"39\">39</sup>.\nאון דעריבער, דוקא סמוך להסתל־קותו, ווען ביי אים איז צוגעקומען דער גילוי פון כל מעשיו כו׳ ובאופן פון תשובה, איז תורתו גילוי המעלה פון גשמיות, און ווי עס דארף זיין „גמ״ח גשמיים״ — ווייל דוקא מיט דעם נעמט מען „מהותו ועצמותו של המאציל״.",[["31","31","ראה לקו״ש שנסמן בהערה 26. ובארוכה לקמן ע׳ 412 ואילך, וש״נ."],["32","32","להעיר מד״ה ולקחתם לכם תרס״א שהביטול דאין עוד שבנבראים שלמטה דוקא (שכל מציאותם הוא בחי׳ העצמות דא״ס) הוא בחי׳ שם ב״ן — והרי שם ב״ן הו״ע עבודת התשובה, כמבואר בד״ה תקעו (תרס״א) שם."],["33","33","כי אף שגם בצדיקים ישנה עבודת התשובה דהרוח תשוב אל האלקים גו׳ (ראה לקו״ת ש״ש סו, ג. ר״פ האזינו. ובכ״מ) — אי״ז כהעילוי דעבודת התשובה שעל זדונות (ראה שעה״ת לאדמו״ר האמצעי ח״ב חינוך פמ״ח. לקו״ש חי״ח ע׳ 124־5)."],["34","34","ראה גם לקו״ש ח״י ע׳ 164, 166."],["35","35","ע״ד (ולא ממש) תורת הבעש״ט (הוספות לכתר שם טוב ספ״ג) בפי׳ „שנים אוחזין בטלית״."],["36","36","עייג״כ תורת חיים ס״פ תולדות (כא, ד. וראה לקו״ת שמ״ע צב, ב) — בנוגע למשה רבינו. ולהעיר מהמבואר שם (וראה שם לפנ״ז ספ״ט. פ״כ) דענין התשובה שמטהר גם לטומאה גמורה דעוונות גמורים שאין להם תיקון ע״פ חכמה דתורה (שהרע עצמו נהפך לטוב) נעשה ע״י התשובה דצ״ג דוקא — לאתבא צדיקייא בתיובתא."],["37","37","אגה״ק סי׳ ז״ך וביאורו. וראה שם סי׳ כח. סידור דש, סע״ב ואילך."],["38","38","תורת שלום ע׳ 86."],["39","39","הובא בשיחת י״ט כסלו תרצ״ב — לקו״ד ח״ד תשנה, סע״א ואילך."]]],[1300161061,"ח. כ״ד טבת איז אלעמאל חל אין דער וואך פון שבת40 מברכים החודש שבט אדער גלייך במוצאי ש״ק זה — ווי בקביעות שנה זו. וואס אין דעם חודש, ביום העשירי בו, איז דער יום ההילולא פון כ״ק מו״ח אדמו״ר.\nזעט מען, אז אויך אין די דברי תורה וואס ער האט ארויסגעגעבן ליום הסתל־קותו — דער מאמר ד״ה באתי לגני — איז מודגש דער תוכן הנ״ל:\nער הויבט אן דעם מאמר דערמיט וואס די וועלט איז „גני״ של הקב״ה41 (ווייל „עיקר שכינה בתחתונים היתה״<sup data-n=\"41\">41</sup> — וואס „גן״ איז אן ארט (ניט נאר פון „דירה״ פאר ענינים המוכרחים, נאר ס׳איז אן ארט) פון תענוג;\nאון די סיבה לזה איז, ווייל „נתאוה הקב״ה להיות לו ית׳ דירה בתחתונים״: דער „נתאווה״ און תענוג פון עצמות, איז דוקא אין תחתונים, אין דער עבודה אין עולם הזה התחתון שאין תחתון למטה ממנו און דארט גופא — איז המעשה הוא העיקר; אז מ׳זאל זיך אראפלאָזן אין עולם, און דארט אין שטות דלעו״ז, אויפטאָן (דורך דער עבודה פון שטות דקדושה, למעלה מטעם ודעת) אז פון שקר העולם זאלן אויפגעשטעלט ווערן קרשים למשכן (פון „שקר״ זאל מען מאכן „קרש״<sup data-n=\"42\">42</sup>, אַ משכן ודירה לו ית׳.\n(משיחות ש״פ שמות תשל״ג, תשל״ו)",[["40","40","ד„יאכל בשבת״ הוא מזה „שטרח בע״ש״ (ע״ז ג, א), דהכוונה בזה היא (גם) מתחיל מ„יום ראשון בשבת״ (ראה רמב״ן יתרו כ, ח)."],["41","41","שהש״ר רפ״ה, וש״נ."],["42","42","כמבואר בארוכה בההמשך דבאתי לגני ה׳תש״י (פ״ו ואילך)."]]],[1300161062,"<h3>וארא *</h3>\nא. שוין גערעדט פיל מאל אז כאטש רש\"י איז (לכל לראש) מפרש פשוטו של מקרא, אנטהאלט זיין פירוש אויך „ענינים מופלאים\"¹ אין שאר חלקי התורה און אויך „יינה של תורה\"²; נאר בכדי אַרויסצונעמען די ענינים (בשאר חלקי התורה) דאַרף מען פריער אַפלערנען פרש\"י ע\"ד הפשט.\nנאכדעם ווי רש\"י איז מפרש דעם פירוש הפשוט פון די פסוקים אין אנפאנג פון דער סדרה — „וארא אל אברהם גו' וגם הקימותי גו'\", איז רש\"י ממשיך³: „ורבותינו דרשוהו⁴ (דער תוכן פון די פסוקים) לענין של מעלה שאמר משה למה הרעותה⁵ אמר לו הקב\"ה חבל על דאבדין ולא משתכחין יש לי להתאונן על מיתת האבות הרבה פעמים נגליתי עליהם בא-ל ש-ד-י ולא אמרו לי מה שמך ואתה אמרת⁶ מה שמו מה אומר אליהם, וגם הקימותי וגו' וכשבקש אברהם לקבור את שרה לא מצא קרקע עד שקנה בדמים מרובים וכן ביצחק ערערו עליו על הבארות אשר חפר וכן ביעקב כו' ולא הרהרו אחר מדותי ואתה אמרת למה הרעותה\" (און איז מסיים „אין המדרש מתיישב אחר המקרא כו'\"):\nאין ס\"פ שמות⁷ אויפן פסוק „עתה תראה וגו'\" (וואס איז דער ענטפער פון הקב\"ה — בכתוב — אויף „למה הרעותה\") זאגט רש\"י „הרהרת על מדותי לא כאברהם שאמרתי לו⁸ כי ביצחק יקרא לך זרע ואח\"כ אמרתי לו⁹ העלהו לעולה ולא הרהר אחר מדותי כו'\"¹⁰.\nדארף מען פארשטיין: א) פארוואס אין פרשת וארא אינעם פירוש פון „ורבותינו דרשוהו\" הנ\"ל ברענגט רש\"י (פון רבותינו) א ראי' אז אלע אבות „לא הרהרו אחר מדותי\" און אין ס\"פ שמות ברענגט ער א ראי' נאר פון אברהם?\nב) אויך בנוגע אברהם גופא איז רש\"י בפרשתנו מפרש דעם ענין פון „לא הרהרו אחר מדותי\" מיט אן אנדער מאורע (כשבקש אברהם לקבור את שרה כו') — ווי אין ס\"פ שמות („שאמרתי לו כי ביצחק יקרא לך זרע\")¹¹.\nג) ועיקר: בס\"פ שמות בריינגט רש\"י דעם פי' לא הרהר סתם ד.ה. אלס זיין פירוש — פשוטו של מקרא, משא\"כ בפרשתנו — מיט דער התחלה",[["","","*) וכ\"ד טבת — ראה סיום השיחה (סי\"ב)."],["1","1","של\"ה במס' שבועות שלו (קפא, א)."],["2","2","היום יום ע' כד."],["3","3","ו, ט."],["4","4","ראה סנהדרין קיא, א. שמו\"ר פ\"י, ד. תנחומא פרשתנו בתחלתו."],["5","5","שמות ה, כב."],["6","6","שמות ג, יג."],["7","7","ו, א."],["8","8","וירא כא, יב."],["9","9","שם כב, ב."],["10","10","ראה פרש\"י וירא כב, יב: „אפרש לפניך את שיחתי כו'\"."],["11","11","בפשטות החילוק: להפי' ד„רבותינו דרשוהו\" שמפרש הכתוב „וגם הקימותי גו'\" שהמדובר בנוגע לירושת הארץ, מביא שהאבות לא הרהרו בזה, משא\"כ בס\"פ שמות. אבל עדיין חסר ביאור מדוע משנה בפ' שמות. ובפרט שדוגמא זו מאברהם לא הובאה במרז\"ל."]]],[1300161063,"„ורבותינו דרשוהו\" — א דרש, ויתרה מזה, אזא דרש וועלכער איז ניט „מתיישב אחר המקרא\" — היפך הכלל ברש\"י אז ווען ער ברענגט אן אגדה איז עס „המיישבת דברי המקרא\"¹¹*.\nב. וי\"ל אז דער לעצטער דיוק פארענטפערט כהנ\"ל: אין ס\"פ שמות איז רש\"י מפרש פשוטו של מקרא על אתר¹², וכפשוטו איז דער פסוק „ויאמר ה' אל משה עתה תראה גו'\" אן ענטפער (כנ\"ל) אויף טענת משה אין די פסוקים לפנ\"ז „למה הרעותה לעם הזה גו' ומאז באתי אל פרעה לדבר בשמך הרע לעם הזה\":\nניט נאר האט די שליחות פון אויבערשטן ניט גע'פועל'ט די הצלה פון די אידן („הצל לא הצלת את עמך\"), נאר אדרבה „הרע לעם הזה\", און דערפאר „עתה תראה, העשוי לפרעה תראה ולא העשוי למלכי שבעה אומות\", וויבאלד אז ער האט מהרהר געווען „אחר מדותי\",\nניט ווי די הנהגה (דארף זיין און) איז געווען בנידון דומה ביי אברהם, וואס „לא הרהר אחר מדותי\", הגם אז פריער „אמרתי לו כי ביצחק יקרא לך זרע ואח\"כ אמרתי לו העלהו לעולה\", וואס די הבטחה האט גורם געווען (ווי אין אונזער פאל) א צער נוסף¹³ — (ע\"ד ווי „מאז באתי לדבר בשמך הרע גו'\")¹⁴,\nווי מ'זעט במוחש, אז דער צער פון ניט האבן קיין קינדער איז ניט בדומה צו די יסורים וואס מען האט ווען דער אויבערשטער האט שוין געבענטשט מיט א בן יחיד ולעת זקנתו און ער ווערט דערנאך צוגענומען, ובפרט נאך אז דער טאטע אליין דארף עס טאן¹⁵.\nועפ\"ז איז אויך מובן, אז עס האט ניט קיין ארט אז רש\"י זאל ברענגען די ראי' אז אברהם „לא הרהר אחר מדותי\" פון דעם וואס „כשבקש לקבור את שרה לא מצא קרקע (וכן ביצחק ערערו עליו כו' וכן ביעקב ויקן את חלקת השדה כו')¹⁶\", ווארום דארטן איז ניט געווען אין אן אופן אז די הבטחה גופא („לתת להם את ארץ\") האט גורם געווען ער זאל קויפן די קרקע בדמים מרובים;\nדער הרהור האט נאר געקענט זיין, אז האבענדיק די הבטחה אויף נתינת הארץ, האט עס אברהם'ן ניט געדארפט קאסטן קיין (סאך) געלט¹⁷ (ועד\"ז ביי יצחק ויעקב) — און במילא איז אזא הרהור ניט קיין דוגמא מכוונת צו דעם וואס משה האט מהרהר געווען, אז דעם אויבערשטנ'ס שליחות גופא האט „גורם\" געווען דעם מצב פון „הרע לעם הזה\".\nאבער לויט דעם וואס „רבותינו דרשוהו\" אז דער גאנצער תוכן הכתובים",[["","","11*) בראשית ג, ח. ועוד."],["12","12","ולא כתב רש\"י ע\"ז „ורבותינו דרשוהו\" וכיו\"ב, אף שהמשך הפירוש „לפיכך עתה תראה העשוי לפרעה כו'\" אי' בגמרא ותנחומא שם בהמשך להדרש חבל על דאבדין כו' שהאבות לא הרהרו — שהביא בפ' וארא. משא\"כ בשמו\"ר ס\"פ שמות הוא ענין בפ\"ע."],["13","13","משא\"כ בנוגע לרעב בארץ (לך יב, יוד ובפרש\"י שם)."],["14","14","ולכן דוקא אחר נסיון העקדה אמר הקב\"ה (וירא כב, יב) „עתה ידעתי — מעתה יש לי מה להשיב לשטן ולאומות התמהים מה היא חבתי אצלך כו' עכשיו שרואים\" (פרש\"י שם) — אף שגם לפנ\"ז עמד בנסיון דמס\"נ באור כשדים (פרש\"י נח יא, כח)."],["15","15","אף „כי ביצחק יקרא לך זרע\" נאמר לאחר לידת יצחק — הרי זה שייך להצער והיסורים המובא בפנים, כי הצער ויסורים כשאין בנים הוא גם מהעדר המשך משפחתו, ולאחר שמבטיח לו שמיצחק יראה זרע „ואח\"כ אמר לו העלהו לעולה\" הרי זה ביטול התכלית דהולדת בן."],["16","16","וישלח לג, יט."],["17","17","ראה פרש\"י ח\"ש כג, ט."]]],[1300161064,"(אויך „וארא אל אברהם אל יצחק ואל יעקב\"¹⁸) קומט בהמשך „לענין של מעלה\" און איז א טייל פון דעם אויבערשטנ'ס מענה¹⁹ בנוגע די שאלות און דיבורים והרהורים פון משה בכלל²⁰ (ניט מצד א צער נוסף דוקא), וואס האבן זיך אנגעהייבן פון „ואתה אמרת מה שמו מה אומר אליהם\"²¹ — איז מובן פארוואס רש\"י בריינגט דרשת רז\"ל און פון אלע דריי אבות אז זיי אלע „לא הרהרו (בכלל²²) אחר מדותי\".\nג. עוד י\"ל: דאס וואס משה רבינו האט געזאגט „למה הרעותה לעם הזה גו'\" איז דאך ניט א ענין פרטי, וואס איז בנוגע צו אים אליין, נאר בשייכות „לעם הזה\", צו כלל ישראל — ובמילא קען רש\"י (אין דרך הפשט) ניט ברענגען א דוגמא פון אברהם וואס האט ניט מהרהר געווען בנוגע דער מערת המכפלה און עד\"ז פון יצחק ביי די בארות און פון יעקב „ויקן את חלקת השדה\", ווארום דאס אלעס זיינען ענינים וואס זיינען געווען נוגע זיי אליין אלס א פרט, און דעריבער קען מען מחלק זיין אז דערפאר האבן זיי נישט",[["18","18","בסנהדרין קאי על הכתוב „ומאז באתי אל פרעה גו'\" ולא הובא מפורש הכתוב „וארא אל אברהם גו'\". אבל בשמו\"ר (פ\"ו, ד) קאי על הכתוב „וארא אל אברהם גו'\". ובתנחומא מסיים „לכך כתב וארא כו'\"."],["19","19","משא\"כ לפרש\"י בפשוטו של מקרא בתחלת הפרשה, רק (תחלת) הכתוב „וידבר אלקים אל משה, דבר אתו משפט על שהקשה לדבר ולומר למה הרעותה לעם הזה\", משא\"כ ההמשך „וארא אל אברהם וגו'\" אינו המשך המענה למשה ע\"ז ש„הקשה לדבר ולומר למה הרעותה כו'\" (ובפשטות פשש\"מ דס\"פ שמות „עתה תראה\" הוא באותה השיטה בפשש\"מ בריש פרשתנו). ולכן אינו נוגע כאן שכל האבות אברהם יצחק ויעקב לא הרהרו (כנ\"ל בפנים), משא\"כ לפי „רבותינו דרשוהו\" (ראה רא\"ם ריש פרשתנו ד\"ה על שהקשה. גו\"א. דברי דוד (להט\"ז) ו, ט. ובכמה מפרשים)."],["20","20","ברא\"ם כאן (ו, ט) מפרש „ולא אל למה זה שלחתני הסמוך לו כפי מה שפירש לפי פשוטו של מקרא\". וצ\"ע דהרי בגמרא ותנחומא בתחלת הענין מובא (גם) הכתוב שלאח\"ז „ומאז באתי אל פרעה לדבר בשמך\" (ובשמו\"ר מסיים „ולבסוף אמרת ומאז באתי אל פרעה\". ועד\"ז בתנחומא). ובסופו (בגמרא) מביא סיום הכתוב „(ועכשיו אתה אומר לי) והצל לא הצלת את עמך\" והכתוב שלאח\"ז „עתה תראה\" (וברש\"י שמביא „למה הרעותה\" — כי מביא התחלת הענין. ראה חדא\"ג סנהדרין שם)."],["21","21","ועפ\"ז י\"ל לכאורה שזהו הטעם שהביא רש\"י בכלל „רבותינו דרשוהו לענין של מעלה\" אף שממשיך „ואין המדרש מתיישב אחר המקרא\", והרי רש\"י כותב כמ\"פ „ואני לא באתי אלא לפשוטו של מקרא ולאגדה המיישבת דברי המקרא כו'\" (ראה לעיל הערה 11*) — כי לפי' הא' קשה למה לא הוכיחו הקב\"ה ע\"ז שהקשה מה שמו מה אומר אליהם, ולכן מביא רש\"י שלפי „רבותינו\" הוכיחו הקב\"ה ע\"ז אלא שהוכיחו לאחר שאמר משה „למה הרעותה\". וי\"ל דלפי פשוטו השאלה „מה שמו\" אינה שאלה וקושיא — הרהר, אלא שאלה, כמפורש בכתוב „ואמרו לי מה שמו מה אומר אליהם\" (וכן מצינו גם במדרש שמו\"ר פ\"ג ה. פ\"ד א), משא\"כ לפי „רבותינו דרשוהו\" בא בעקמומית (כדעת היוק\"ר פי\"א, ה). וכ\"כ ביפ\"ת לשמו\"ר כאן (פ\"ו, ד). ולהעיר שגם לפי „רבותינו\" הנה בשמו\"ר „ועתה תחלת שליחותי אמרת לי מה שמי\" (שאינו לשון הכתוב ומשמיט התחלת הכתוב „ואמרו לי\" וסיומו „מה אומר אליהם\"). ועד\"ז בסנהדרין ותנחומא שם (ושם „מה שמך\"). משא\"כ בפרש\"י „מה שמו מה אומר אליהם\". וראה חדא\"ג שם. בנוגע לשאר הדיוקים שבפרש\"י זה — נת' בארוכה בההתועדות. ואכ\"מ."],["22","22","אף שמפרש\"י משמע שמחלקו לב' פסוקים „הרבה פעמים נגליתי .. ולא אמרו לי מה שמך ואתה אמרת\" הוא פי' הכתוב „וארא גו'\", „וכשבקש אברהם כו' ולא הרהרו אחר מדותי ואתה אמרת למה הרעותה\" הוא פי' הכתוב „וגם הקימותי וגו'\", הרי מזה שמתחיל „שאמר משה למה הרעותה אמר לו הקב\"ה חבל על דאבדין כו' יש לי להתאונן כו'\" (וכן בסיומו), משמע דלא הרהרו שייך גם להשאלה דמה שמו. ובסנהדרין (ועד\"ז בתנחומא ושמו\"ר) שם מסיים בסופו „ולא הרהר (כ\"א מהאבות) אחר מדותי ולא אמרו לי מה שמך ואתה אמרת לי מה שמך כו' ועכשיו והצל לא הצלת גו'\". וראה פרש\"י שם ד\"ה בתחלה."]]],[1300161065,"מהרהר געווען ווייל זיי האבן געטראכט אז ביי זיי איז די הבטחה ניט מקויים געווארן, דערפאר וואס „גרם החטא\" (ווי רש\"י האט שוין פריער מפרש געווען ביי יעקב'ן²³),\nמשא\"כ טענת משה וואס איז געווען בנוגע רעת כלל ישראל, קען דאך ניט זיין אז חטא משה זאל גורם זיין „הרעותה לעם הזה\"²⁴.\nאון דעריבער ברענגט רש\"י (ע\"פ פשוטו) אין ס\"פ שמות „לא כאברהם שאמרתי לו כי ביצחק יקרא לך זרע ואח\"כ אמרתי לו העלהו לעולה\", ווייל אויך דא איז עס געווען נוגע (ניט בלויז צו אברהם'ן אליין, נאר) להמשך כל הדורות אחריו, ובמילא איז אויך דא ניט שייך דער חשש שמא גרם החטא — ואעפ\"כ איז „לא הרהר אחר מדותי\", משא\"כ ביי יצחק ויעקב וואס ביי זיי געפינט מען ניט אזא פאסירונג והנהגה.\nדאס אלץ איז מצד פשוטו של מקרא, אבער לויט „רבותינו דרשוהו\" ע\"פ מדרש (אגדה) שבתורה וועלכע איז פארבונדן מיט נשמתא דאורייתא²⁵ (ד„רוב סודות התורה גנוזין בה\"²⁶) — איז דאך „האבות הן הן המרכבה\"²⁷ אז אויך למטה אין עוה\"ז זיינען זיי אין דער דרגא פון מרכבה, ווי למעלה²⁸ —\nאיז לפי\"ז ביי זיי בכלל ניט שייך צו זאגן דעם ענין פון „נתלכלכתי בחטא\"²⁹, און דעריבער קען מען בריינגען אז „לא הרהרו אחר מדותי\" אויך פון ענינים וואס, לכאורה, זיינען זיי פרטיים, וועלכע זיינען שייך צו זיי אלס א פרט — מערת המכפלה ביי אברהם, ביי יצחק ענין הבארות, ביי יעקב „ויקן את חלקת השדה\" — ווייבאלד אז זיי זיינען געווען „מרכבה רק לרצון העליון כל ימיהם\"³⁰.\nד. פון „יינה של תורה\" אין דעם פרש\"י: י\"ל אז דאס איז מרומז אין דער שייכות צווישן די ביידע הסברות בפרש\"י הנ\"ל:\nשוין גערעדט אמאל בארוכה³¹ בנוגע די „מעשה אבות\" פון אברהם יצחק ויעקב, אז אין דעם זיינען פאראן צוויי אופנים: א) ווי „מעשה אבות\" האט זיך געטאן ביי די אבות מצד גופם — און אין דעם איז שייך אז אברהם זאל דאגה'ן „שמא קבלתי שכר על צדקותי\", ער זאל בעטן אן „אות על ירושת הארץ\"³² ועד\"ז בא יעקב³³\n[ווי מיר געפינען עס אינעם סיפור פון מעזריטשער מגיד³⁴ — אז ער האט געזען ווי משה רבינו לערנט מיט",[["23","23","וישלח לב, יא."],["24","24","אף ש\"י\"ל דחטא ישראל גרם (ראה דברי דוד (ס\"פ שמות. פרשתנו ו, ב ואילך) דמפרש שבזה הר' שאלת משה (למה זה שלחתני) ותשובת הקב\"ה בכל המשך הפרשה), הרי מדגיש רש\"י (שמות ב, יד) שזהו רק מדרשו, ובפרט שנאמר לו „לך שוב מצרים כי מתו כל האנשים גו'\" — עליהם מדובר בשמות (ב, יד) — דפשש\"מ הוא, שכיון שהם מתו — אין מקום וחשש כלל ללהז\"ר וכו'."],["25","25","זח\"ג קנב, א."],["26","26","אגה\"ק סכ\"ג. הל' ת\"ת לאדה\"ז פ\"ב ס\"ג. ובאגה\"ק שם: פנימיות התורה שהיא אגדה."],["27","27","ב\"ר פמ\"ז, ו. פפ\"ב, ו. ובפרש\"י (לך יז, כב) „ולמדנו (מאברהם) שהצדיקים מרכבתו של מקום\"."],["28","28","שכל אבריהם כולם היו קדושים ומובדלים מעניני עוה\"ז כו' כל ימיהם (תניא פכ\"ג)."],["29","29","להעיר מאגה\"ק שם: „אגדה שבתורה .. ומכפרת עונותיו של אדם\"."],["30","30","תניא שם."],["31","31","לקו\"ש ח\"ה ע' 298 ואילך."],["32","32","לך (טו, א. שם טו, ו) בפרש\"י."],["33","33","וישלח (לב, ט) בפרש\"י."],["34","34","התמים (ח\"ב ע' עא) פג, ב. קובץ מכתבים לתהלים ע' 197. אג\"ק אדמו\"ר מהוריי\"צ ח\"ג ע' תנד־ה. ולהעיר שסיפור זה סיפר כ\"ק אדה\"ז לכ\"ק אדמו\"ר הצ\"צ „בשבוע שקודם הסתלקותו\" — ראה בסוף השיחה."]]],[1300161066,"תינוקות של בית רבן דעם פסוק³⁵ „ויפול אברהם על פניו ויצחק ויאמר בלבו הלבן מאה שנה יולד ואם שרה הבת תשעים שנה תלד\" און איז זיי מסביר, אז „אין מקרא יוצא מידי פשוטו\"³⁶].\nב) מעשה אבות ווי דאס האט זיך אויפגעטאן מצד נשמתם, וואס אין דעם איז כלל ניט שייך קיין „הרהרו אחרי מדותי\" וכו'.\nאון מ'האט מבאר געווען, אז די פירושים אין רש\"י ע\"ד הפשט (גוף התורה) ריידן וועגן „מעשה אבות\" ווי זיי זיינען מצד הגוף; און די פירושים ע\"ד המדרש — אגדה שבתורה — ווי די „מעשה אבות\" זיינען מצד הנשמה³⁷.\nועד\"ז בעניננו: אין רש\"י ס\"פ שמות, וואס איז ע\"ד הפשט, רעדט זיך וועגן „מעשה אבות\" ווי זיי זיינען מצד הגוף; דעריבער קען מען ניט ברענגען א ראי' צו משה'ס שאלה בנוגע „לעם הזה\" — פון דעם וואס לא הרהרו בנוגע עניניהם הפרטים, ווייבאלד עס קען זיין אז אברהם טראכט שמא קבלתי שכר כו', ועד\"ז בא יעקב.\nמשא\"כ לויט „רבותינו דרשוהו\" — אגדה שבתורה (וואס רוב סודות התורה גנוזין בה) — איז דער ענין פון „מעשה אבות\" מצד הנשמה, איז א ראי' אויך פון דעם וואס די אבות לא הרהרו בנוגע זייערע ענינים פרטיים.\nעד\"ז קען מען מסביר זיין אויך בשייכות צו משה רבינו: דאס וואס משה האט גע'טענה'ט (אין ס\"פ שמות) „למה הרעותה לעם הזה גו' ומאז באתי אל פרעה לדבר בשמך הרע לעם הזה גו'\" לויט פשוטו של מקרא, איז דאס געווען מצד אופן הא', איז שייך צו זאגן אז דאס איז אן ענין פון „הרהרת על מדותי\" (און „קובל אני על ששלחתני\"³⁸), א טענה כלפי דעם אויבערשטן כביכול, אז זיין שליחות האט גורם געווען דעם מצב פון „הרע\" פאר אידן [און דעריבער איז דער עונש — „לפיכך עתה תראה, העשוי לפרעה תראה ולא כו'\"].\nמשא\"כ ע\"פ „רבותינו דרשוהו\" רעדט זיך דער ענין מצד אופן הב', קען מען ניט זאגן אז די טענה צו משה איז געווען אויף „הרהר על מדותי\" כפשוטו (און אז ער האט באקומען אן עונש דער־פאר²⁹), נאר די טענה איז באשטאנען דערין וואס „הרבה פעמים נגליתי עליהם בא-ל ש-ד-י ולא אמרו לי מה שמך ואתה אמרת מה שמו\", היינו וואס ער האט געוואלט וויסן שמך הגדול והקדוש כו' סוד שם „המפורש\"³⁹ — צו־קומען צו א העכערע ידיעת אלקות³⁹* — שם הוי', מדת אמתית שלי, שם העצם⁴⁰. און אפילו דאס וואס ער האט געזאגט „למה הרעותה לעם הזה\" איז ניט קיין ענין פון „הרהרת על מדותי\" כפשוטו, נאר אויך אין דעם האט ער געוואלט און געבעטן צו פארשטיין אויך בשכלו⁴¹ אלע פרטים און דרכים פון",[["35","35","לך יז, יז. ופי' ההפ\"מ הוא ע\"פ תיב\"ע שם (דגם אברהם „תמה\" — וכ\"ה בהראב\"ע, שהוא ע\"ד הפשט — משא\"כ פרש\"י הוא (כהדגשתו) ע\"פ ת\"א דאברהם „חדי\")."],["36","36","שבת סג, א."],["37","37","ראה לקו\"ש שם כמה דוגמאות בזה."],["38","38","פרש\"י שמות ה, כב."],["39","39","פדרא\"ס ספ\"מ. וראה דרז\"ל עה\"כ (שמות ג, יד הובאו בתו\"ש שם), (שינוי הנוסחאות ונ\"כ ה)רמב\"ם הל' יסוה\"ת פ\"ו ה\"ב. שו\"ע יו\"ד סרע\"ז, ס\"ט. פרדס ש' השמות. ועוד. 39*) וכמו שביקש „הודיעני נא את דרכיך\" „הראני נא את כבודך\" (תשא לג, יג. שם יח)."],["40","40","כהמשך הכתובים בפרשתנו."],["41","41","ראה בחיי ס\"פ שמות. פני\"י ר\"פ וארא. ועוד."]]],[1300161067,"אויבערשטנ'ס שליחות (און עפ\"ז איז מדוייק וואס רש\"י זאגט ניט ביי „רבותינו דרשוהו\" דעם לשון „הרהרת על מדותי\" בנוגע למשה⁴², ווי ער זאגט אין זיין פירוש [ס\"פ שמות] ע\"ד הפשט).\nה. מ'קען נאך אלץ פרעגן: ווי איז שייך זאגן „הרהרת על מדותי\" כפשוטו, אפילו מצד אופן הא', וויבאלד אז דא רעדט זיך וועגן משה, וואס גלייך ביים געבארן ווערן ווערט אויף אים געזאגט „ותרא אותו כי טוב הוא\"⁴³ — „נתמלא הבית כולו אורה\"⁴⁴; ובפרט אז מ'זאל נאך דערביי מדגיש זיין אז די אבות האבן ניט מהרהר געווען און משה, וואס ער איז געווען „נבחר מכל מין האדם\"⁴⁵ (אויך פון די אבות⁴⁵*), האט יע מהרהר געווען?\nאויך דארף מען פארשטיין: וויבאלד אז אפילו „בגנות בהמה טמאה לא דיבר הכתוב\"⁴⁶, איז דאך פשיטא בנוגע א אידן ועאכו\"כ בנוגע משה רבינו, היינט פארוואס דערציילט תורה אז משה „הרהר על מדותי\"? [וואס פאר א הוראה איז דא אין דעם פאר אן אידן בעבודתו לקונו? לכאורה איז שווער צו זאגן אז דערפון דארף א איד אפלערנען אויף וויפל מען מוז זיין אויסגעהיט פון מהרהר זיין אחר מדותיו של הקב\"ה, און אז מ'דארף זיך פירן לויט די הנהגה פון די אבות וואס „לא הרהרו\" — ווארום וויבאלד אז משה רבינו איז צו דעם ניט צוגעקומען, איז ווי מאנט מען עס ביי יעדן אידן ובכל זמן]⁴⁷?\nו. וועט מען דאס פארשטיין ע\"י הביאור וואס רש\"י שטעלט זיך אויפן ווארט „וארא\" און איז מפרש: „אל האבות\", איז ידוע די קושיא (ווי מפרשי רש\"י פרעגן): דער פסוק אליין טייטשט דאס אויס גלייך „(וארא) אל אברהם אל יצחק ואל יעקב\", איז וואס גיט דא רש\"י צו?\nאיז די הסברה אין דעם⁴⁸: רש\"י איז דערמיט אויסן צו מסביר זיין, אז דער ענין ועילוי פון „וארא אל אברהם גו'\" — ראי' אין אלקות — בודאות מוחשית (ווי די וודאות שע\"י ראי' גשמית⁴⁹), וואס דערפאר איז ביי זיי ניט געווען שייך „הרהר אחר מדותי\" — האבן זיי געהאט אלס אבות פון די בנ\"י: ד.ה. אז „וארא\" איז געגעבן געווארן צו זיי אין אן אופן אז דאס זאל אראפקומען בירושה (פון די אבות) צו די בנים נאך זיי, ווארום „האב זוכה לבן בנוי וכו' בחכמה\"⁵⁰.\nאון ווי ס'איז מבואר אין תו\"א (פון דער פרשה) אינעם ענין אז „אין קורין",[["42","42","וכן בסנהדרין ושמו\"ר ותנחומא שם. אבל ראה פרש\"י ד\"ה ועל דבר וד\"ה בתחילה סנהדרין שם."],["43","43","שמות ב, ב (וראה אוה\"ת שם). ראה סה\"מ תש\"י ע' 182. וש\"נ."],["44","44","פרש\"י שם. מסוטה יב, א. וזה הי' גם מצד הגוף כמו לדעת „אחרים\" — ש„נולד כשהוא מהול\", וכמבואר בכ\"מ."],["45","45","פיה\"מ להרמב\"ם סנהדרין פ' חלק ביסוד הז'. ולהעיר גם משו\"ע יו\"ד סרמ\"ב. וראה לקו\"ש ח\"ז ע' 254. 45*) וכמרז\"ל „כל השביעין חביבין .. באבות שביעי חביב אברהם .. משה\" — ויק\"ר פכ\"ט, יא. וראה ד\"ה החודש ה'ש\"ת פ\"ט."],["46","46","ב\"ב קכג, א."],["47","47","ראה לקו\"ש ח\"ג ע' 855 ואילך."],["48","48","ראה רא\"ם ועוד. לקו\"ש שם ע' 860."],["49","49","שאינו דומה שמיעה לראי', שלכן „אין עד נעשה דיין כו' כיון דחזיוהו כו' לא מצו חזו ליה זכותא\" (ר\"ה כה, סע\"ב ואילך), שאינו שייך בזה שום „הרהור\", משא\"כ כששומעים מעדים. וראה לקו\"ש ח\"י ע' 121 ואילך. וש\"נ."],["50","50","עדיות פ\"ב מ\"ט."]]],[1300161068,"אבות אלא לשלשה\"⁵¹, אז „בחי' האבות היא ירושה לבניהם אחריהם בכל דור .. בחי' האבות צ\"ל בכל אדם\".\nאון דאס איז דער טעם אויף דער טענה וואס דער אויבערשטער האט געהאט צו משה רבינו: „חבל על דאבדין ולא משתכחין\". וויבאלד אז „וארא אל אברהם גו'\" איז געווען אלס צו „אבות\", איז ניטא קיין ארט פארענטפערן אז אברהם גו' זיינען אנדערש — וויבאלד אז דא רעדט זיך אלס „אבות\" איז „בכל אדם\" אלס „בן\", דארף זיין און זיך אנהערן די בחי' „וארא\", האבענדיק דאס בירושה.\nז. לכאורה קען מען נאך אלץ מחלק זיין און זאגן: הגם אז דער אב גיט איבער זיינע ענינים בירושה צום בן, פונדעסטוועגן איז מובן, אז נאכדעם ווי די ענינים קומען אראפ צום יורש קומען זיי ניט צו דער מעלה וואס זיי האבן געהאט זייענדיק ביים אב⁵².\nאון וויבאלד אזוי, קען מען דאך פארענטפערן, אז די דרגת „וארא\" וואס דער בן האט בירושה קומט ניט צו דער (העכערער) דרגא פון „וארא\" ווי זי איז געווען ביי די אבות.\nאיז דער ביאור אין דעם אויך מרומז אין רש\"י: „וארא — אל האבות\" — דער גאנצער גילוי פון וארא איז געווען צו די „אבות\" — דהיינו, אז דער גילוי איז ניט מצד (און לויט) זייער מדרגה מיוחדת אין עבודת ה' (אברהם אוהבי — אין קו האהבה (פחד) יצחק — בקו הגבורה וכו'), נאר אינגאנצן פארבונדן מיט'ן ענין וואס זיי זיינען אבות (צו בנים — וואס הבן יורש הכל). ובמילא איז מובן אז אין דעם „וארא\" איז ניטא קיין חילוק צווישן אבות און בנים:\nדער יתרון און מעלה וואס איז דא אין דעם אב לגבי דעם בן איז שייך אין ענינים וואס דער אב האט זיי געהאט מצד מעלת ועבודת עצמו; אלס עובד ה' וכו'; וואס הגם אז אויך אזעלכע ענינים קומען אראפ בירושה צו קינדער כנ\"ל במשנה האב מוריש כו', קענען זיי אבער זיין ביים יורש ניט אויף דער זעלבער הויכער דרגא ווי ביים מוריש.\nמשא\"כ בנדו\"ד, וואס דער עילוי פון „וארא\" (הקב\"ה מצד עצמו) איז צו אבות — וואס דעם תואר און מציאות מאכט אויף דער בן — איז מובן, אז דער עילוי כמו שהוא ביים אב, קומט בירושה צו די קינדער.\nאון ע\"פ כהנ\"ל איז נאכמער ניט פארשטאנדיק: וויבאלד אז יעדער איד און כל שכן משה רבינו האט דעם ענין פון וארא בירושה מהאבות, היינט ווי קומט עס וואס דאס האט ניט אפגעהאלטן משה רבינו פון „הרהר אחר מדותי\"?\nח. וי\"ל דער ביאור בזה: רז\"ל זאגן⁵³: לא נגאלו ישראל ממצרים אלא בשכר האמונה⁵³*, ד.ה. אז ביי זיי איז נתגלה געווארן די נקודת היהדות, דער פארבונד פון אידן מיט'ן אויבערשטן,",[["51","51","ברכות טז, ב."],["52","52","וכלשון רז\"ל יורש כרעא דאבוה הוא (עירובין ע, ב). ובל' הרגיל בכ\"מ — „ברא כרעא דאבוה\" (יונת אלם רפ\"ב. וראה תוד\"ה מקמי — יבמות ג, א. רש\"י כתובות צב, א ד\"ה כבעל). ובלקו\"ת ברכה (צו, ב) ד„היינו נהי' דאו\"א\". וצריך לימוד מיוחד שהיורש עומד במקום המוריש — ראה ב\"ב קנט, א. צפע\"נ מילואים יג, א. מהד\"ת יט, א. שו\"ת צפע\"נ (נ. י.) ח\"א סקי\"ח. וראה לקו\"ש ח\"ח ע' 348. ולהעיר מההקדמה לשערי אורה."],["53","53","מכילתא בשלח יד, לא. 53*) ובילקוט (שם רמז רמ): שלא נגאלו אבותינו ממצרים אלא בזכות אמונה."]]],[1300161069,"וואס דאס דריקט זיך אויס אין דער אמונה פון אידן אין דעם אויבערשטן — דאס האט זיי געמאכט ראוי אז זיי זאלן אויסגעלייזט ווערן פון מצרים.\nכאטש אז אויך פריער, זייענדיק נאך אין קושי הגלות פון מצרים, זיינען אידן געווען „מאמינים\"⁵⁴ איז דאס אבער פארבונדן מיט דעם וואס זיי זיינען⁵⁵ „בני מאמינים\"⁵⁴ — זיי האבן עס געהאט בירושה אין וועלכן מצב די בנים זאלן ניט זיין בגילוי; אבער מצד ענינם ועבודתם פון די אידן, מצד תכונת הבנים עצמם, איז ביי זיי נאך ניט געווען דער „ורעה אמונה\", שלימות הגילוי פון אמונה.\nאון בכדי אז די אידן זאלן אויסגעלייזט ווערן פון מצרים מצד זייער אייגענעם זכות⁵⁶, דאס זאל זיין זייער שכר, האט די ירושה'דיקע אמונה און התקשרות פון אידן מיט'ן אויבערשטן געדארפט ביי זיי ווערן זייערס און אייגענער ענין⁵⁷.\nט. און דאס האט זיך אויפגעטאן דורך משה רבינו. ווארום אין דעם באשטייט דער חילוק צווישן דער המשכה שע\"י האבות און ע\"י משה: מצד בחי' האבות, כנ\"ל, איז די נקודת היהדות והאמונה ביי יעדן אידן אין אן אופן של ירושה, ער האט עס בטבע ומצד ההולדה, זייענדיק א בן אברהם יצחק ויעקב⁵⁸.\nאבער משה רבינו ע\"ה, וואס נוסף אויף דעם וואס ער איז פון די „שבעה רועים הממשיכים חיות ואלקות לכללות נשמות ישראל\", איז ער „כללות כולם ונקרא רעיא מהימנא\"⁵⁹ — ער איז זן ומפרנס ומשפיע אז די אמונה וואס איז דא ביי אידן זאל זיין „ורעה אמונה\", ב„בחי' פנימיות\" — „שתהא אמונה שלימה וחזקה ונגעה עד פנימיות הנפש\"⁶⁰, וואס דעמאלט וועט די אמונה דורכנעמען זיין גאנצן מהות אין כל עניניו ביז אין מעשה בפועל.\nיו\"ד. ע\"פ הנ\"ל וועט מען פארשטיין דעם תוכן העניין פון שאלת משה רבינו „למה הרעותה גו'\" (וואס די תורה דער־ציילט וועגן דעם, הגם אז „אברהם כו' לא הרהר\") און תשובת הקב\"ה „וארא אל האבות\":\nוויבאלד אז עס האט שוין געהאלטן נאענט צו דער גאולה און משה איז געגאנגען בשליחות הקב\"ה אויסצולייזן די אידן, האט געדארפט דער פארבונד פון אידן מיט'ן אויבערשטן שע\"י אמונה זיין ביי זיי ניט בלויז מצד האבות, „מאמינים\" מצד „בני מאמינים\", נאר אויך אז די אמונה זאל זיי דורכנעמען מצד ענינם ותוכנם.\nאון דאס האט זיך אויפגעטאן דורך שאלת והרהור משה⁶⁰* „למה הרעותה",[["54","54","שמות ד, לא. שבת צז, א. וראה פרש\"י עה\"ת שמות ד, ב."],["55","55","ראה אוה\"ת שבהערה 60."],["56","56","להעיר שגם במכילתא הובא הכתוב „ויאמן העם\" שנאמר בהיותם במצרים. וי\"ל שלכן ממשיך שם ומביא עוד כתוב „וכה\"א אמונים נוצר ה'\" (תהלים לא, כד) — ראה ברכות ומכות בסופן (ועוד) — מאי ואומר."],["57","57","להעיר מלקו\"ש חי\"א שיחה א' לפ' שמות."],["58","58","ראה תניא פי\"ח־יט. ועוד."],["59","59","תניא פמ\"ב."],["60","60","תו\"א בהוספות ד\"ה כי תשא. וראה אוה\"ת הגהות לתו\"א הנ\"ל (תשא ע' א'תתעט ואילך). שם ע' א'תתלה ואילך. וראה לקו\"ת ואתחנן ד\"ה וידעת הא' וביאוריו. ועוד. 60*) להעיר ממרז\"ל (שמו\"ר פמ\"ג, ו): אמר (משה) רבה\"ע עשו לך סיוע כו' אמר הקב\"ה אף"]]],[1300161070,"גו' ומאז באתי אל פרעה גו' הרע גו'\", וואס אויף דעם איז געקומען דברי הקב\"ה „וארא גו'\", דהיינו, אז בחי' „וארא\" — דער תכלית התאמתות (בדרך ראי') און די התקשרות פון אידן מיט אלקות שע\"י האמונה — איז געווארן אויך מצד דער מציאות פון אידן, וואס מצ\"ע איז דא שייך דער ענין פון „הרהר אחר מדותי\", האט זיך אין איר אויפגע־טאן דער עילוי פון „וארא\", די שלימות האמונה בה', ובמילא אויך די שלילה גמורה פון „הרהר אחר מדותי\".\nאון דעריבער זאגט רש\"י בס\"פ שמות „הרהרת על מדותי\" — „לא כאברהם\" וואס „לא הרהר אחר מדותי\": דערמיט איז ער מדגיש אז די בחי' פון „לא הרהר\" וואס איז דא ביי משה און ביי אלע אידן מצד אברהם (האבות), איז ניט מספיק (וויבאלד אז (מצ\"ע) בגלוי הרהרת וכו'\"), ווארום דאס איז אן ענין וואס קומט בירושה, אבער מצד טבעו ומציאותו פונעם בן גופא קען זיין אז ער איז מהרהר, און דער אויפטו פון משה איז געווען, אז אויך אט דער „הרהרת\" זאל קיין ארט ניט האבן — דורך דיבור הקב\"ה — גילוי פון „וארא\", כנ\"ל⁶¹.\nיא. לויט דעם איז נאכמער מדוייק דער אינטיילן פון די פירושים אין רש\"י — ע\"ד הפשט (בס\"פ שמות) און ע\"פ „רבותינו דרשוהו\" (בפרשתנו): דאס וואס ס'איז מבואר לעיל, אז די פירושים ע\"ד הפשט בפרש\"י זיינען ווי די ענינים זיינען מצד הגוף, איז ניט דער פשט אז מצד גופו של משה איז שייך אן ענין פון „הרהרת על מדותי\" כפשוטו ח\"ו, ווארום וויבאלד אז „טוב הוא\", כנ\"ל, גיט עס ניט קיין ארט אויף „הרהרת על מדותי\": נאר דער פירוש בזה איז, אז דער ענין ווערט געטאן אין אן אופן וואס ער קען (אין פשטות וחיצוניות) אויסגעטייטשט ווערן ווי „הרהר\" (חטא) כפשוטו⁶².\nאון דעריבער, ע\"ד הפשט, גוף התורה, וואס איז שייך צו יעדן אידן באיזה מצב שהוא, ווערט דאס אויסגע־טייטשט אלס „הרהרת על מדותי\" כפשוטו — היות אז מ'דארף אויפטאן דעם גילוי פון „וארא\" (ענין האמונה) בא אלע אידן, אויך ביי די וואס ביי זיי איז דער גוף (לעת עתה נאך) מסתיר אויף דער נשמה, אזוי אז ס'איז ניט מאיר בגלוי די אמונה מצד הנשמה, און דער גוף מצ\"ע איז שייך צו פרעגן „למה הרעותה גו'\", און ל„הרהר אחר מדותי\" כפשוטו —\nאון אויך ביי זיי ווערט אויפגעטאן ע\"י משה⁶³, וואס ער איז כולל כל ישראל⁶⁴, דער גילוי פון „וארא\", די גילוי התאמתות והתקשרות שע\"י אמונה, שלילה פון דעם הרהור והיפך ההרהור.\nמשא\"כ ע\"פ „רבותינו דרשוהו\", „נשמתא דאורייתא\", זעט מען ווי ביי אידן לייכט די נשמה, וואס מצד זה איז",[["","","אתה טועה כו' — ועי\"ז שכלל עצמו עם בנ\"י הציל אותם מעונש. וי\"ל שעד\"ז הוא כאן."],["61","61","להעיר (ע\"ד הגלגלה) מצפע\"נ עה\"ת בראשית (ע' מח ואילך) החילוק דאברהם ומשה, „דאברהם אבינו לא יגע בתורה כו' עצם החכמה, שכל הפועל, וכל התורה גלוי' לו\", „כל התורה נתגלה לו בלא דוחק וכו' רק בגדר קנין שלא בגדר עצם ולא שיעבוד הגוף\" (שם ע' נא). משא\"כ משה רבינו יגע בתורה כו'."],["62","62","כמו שנתבאר בנוגע להאבות — לקו\"ש ח\"ה ע' 64."],["63","63","להעיר מירושלמי הוריות פ\"ג ה\"ה: כל כך למה בשביל להחזיר את הטיפשים (ראה פי' פני משה שם)."],["64","64","שער רוה\"ק להאריז\"ל קח, ד (הוצאת ת\"א תשכ\"ג). שער הגלגולים הקדמה יז. ועוד."]]],[1300161071,"ניט שייך „הרהרת על מדותי\" כפשוטו, נאר בלויז ווילן פארשטיין „מה שמו\" און פארשטיין „למה הרעותה\", אויך בשכל; און ע\"י משה האט זיך אויפגע־טאן „ורעה אמונה\" אז אויך שכל זאל זיך אנהערן די אמונה און התאמתות אין אלקות בבחי' „וארא\", ווי ס'איז העכער פאר חכמה וטעם⁶⁵.\nיב. עפהנ\"ל וועט מען פארשטיין די שייכות פון כ\"ד טבת — יום ההילולא פון אלטן רבי'ן — צו פרשת וארא (וכדברי השל\"ה הידועים⁶⁶), וואס בשנה זו (ווי בכו\"כ שנים)⁶⁷ איז עס חל אין דער וואך פון פ' וארא⁶⁸:\nדער חידוש פון תורת החסידות חב\"ד, וואס איז נתגלה געווארן דורך דעם אלטן רבי'ן [וואס ביום ההילולא זיינען עולה „כל מעשיו ותורתו ועבודתו אשר עבד כל ימי חייו\"⁶⁹ און עס 'איז דאן „מתגלה ומאיר בבחי' גילוי מלמעלה למטה\"⁷⁰] איז תורת החסידות ווי זי איז נתגלה געווארן דורכן בעש\"ט און מעזריטשער מגיד⁷¹, י\"ל אז (אין ענין בזה איז, אז) עס איז אין דעם, וואס יתפרנסון⁷² מיני' — פון פנימיות התורה און די אמונה אין אלקות ווערט נתגלה דורך תורת החסידות חב\"ד באופן אז עס זאל דורכנעמען דעם גאנצן מענטשן, אנהויבענדיק פון מוחין שבראש, חב\"ד — ביז אז דאס זאל ביי אים זיין ניט בלויז א גילוי פון נקודת האמונה המסותרת, נאר אן ענין וקומה שלימה וואס קומט מצד עבודתו וכוחות שלו, אע\"פ וואס לפני זה, מצד עצם זיינען זיי דערצו ניט שייך⁷³.\nאון דאס האט דער אלטער רבי אויפגעטאן דורך דעם וואס ער האט אראפגעטראגן תורת החסידות אויך אין חב\"ד שבנפש, ביז אין „חוצה\", וואס איז, לעיני בשר, א מציאות בפני עצמו, און מצד עצמו איז ער מסתיר דעם גילוי האמונה בה'.\nוע\"ד ווי דער גילוי האמונה וואס האט זיך אויפגעטאן ע\"י שאלת משה „למה הרעותה\", איז דאך דאס געווען ע\"י דיבור הקב\"ה „וארא אל האבות\", אז אט די ראי' (התאמתות) ואמונה אין אלקות וואס אידן האבן בירושה זאל דאס ווערן ביי זיי אויך מצד תכונתם וענינם הם, כנ\"ל בארוכה⁷⁴,",[["65","65","ראה גם לקו\"ש ח\"ו ע' 39 ואילך."],["66","66","חלק תושב\"כ ר\"פ וישב."],["67","67","וגם בשנת ההסתלקות תקע\"ג היתה הקביעות דכ\"ד טבת יום א' פ' וארא. וההסתלקות היתה במוצש\"ק אחר שהתפלל תפלת ערבית והבדלה (הקדמת בני המחבר לשו\"ע אדה\"ז). הרי אחר תפלת ערבית והבדלה הוא כבר נבדל משבוע שעבר ונכנס בשבוע שאחר השבת."],["68","68","ראה גם לקו\"ש ח\"ו שם."],["69","69","ביאור לאגה\"ק סי' זך."],["70","70","שם סי' כח. וראה סידור שער הל\"ג בעומר (ד\"ש, ב־ג)."],["71","71","להעיר משיחת ליל ש\"ק פ' תשא תפר\"ח, שענין גילוי הבעש\"ט וההמ\"ם היו הכנה לגילוי עצם פנימיות התורה שנתגלה ע\"י רבינו הזקן — בדוגמת עבודת האבות שהי' הכנה לגילוי העצמות דמ\"ת (ע\"י משה). — נעתק בלקו\"ד ח\"ד ע' 1139 הערה 22. וראה שם לפנ\"ז הערה 15."],["72","72","לשון התקו\"ז (ת\"ז בסופו). וכפי' המק\"מ (הקדמה לזהר): יתפרנסון .. כשיפורש להם אמיתות מאמריו כו'. ובכסא מלך (לתקו\"ז שם): בדרא בתראה דוקא קרוב לימות המשיח כו' (אף אשר) זה כמה מאות שנים שנתגלה כו' (כי הלימוד צ\"ל דוקא באופן של) יתפרנסון כו' יפורשו מאמריו העמוקים בהקדמות שגילה הארי\"ז זלה\"ה כו' שיבינו כו' כי הלומד גירסא בעלמא הגם שיש לו שכר טוב כו' עכ\"ז הסגולה דבגיני' וקראתם דרור היא כשיתפרנסון וילמדו פירושי המאמרים כו'. — ראה גם כן הקדמת הרח\"ו לשער ההקדמות."],["73","73","להעיר מלעיל ע' 39 ואילך. וש\"נ."],["74","74","ראה לקו\"ש ח\"ד ע' 1136 שאדה\"ז הי' קורא להבעש\"ט „זיידע\", והביאור בזה."]]],[1300161072,"און פונקט ווי דאס איז געווען בגאולת מצרים, אז אין שכר פון דער אמונה זיינען זיי נגאל געווארן,\nאזוי איז אויך בגאולה האמיתית והשלימה — דורך „יפוצו מעינותיך חוצה\", דורך די אמונה⁷⁵ באופן אז יתפרנסון מיני', ווי זי ווערט נתגלה דורך תורת חסידות חב\"ד⁷⁶, און נעמט דורך ביז דער „חוצה\" ממש, וועט זיין „אתי מר\"⁷⁷ — דא מלכא משיחא, אז אלע אידן און יעדער איד וועלן זוכה זיין צו דער גאולה האמיתית והשלימה, במהרה בימינו ממש.\n(משיחת ש\"פ וארא תשל\"א)",[["75","75","ראה מכילתא שם בסופו: וכן אתה מוצא שאין הגליות מתכנסות אלא בשכר אמונה כו'."],["76","76","ובעיקר אחר פ\"ב (הגאולה די\"ט\"כ) — תו\"ש ס\"ע 112 ואילך. לקו\"ד ח\"א כב, א ואילך. וראה לקו\"ש ח\"י ע' 102 ואילך."],["77","77","מכתב הבעש\"ט (נדפס בסוף ספר בן פורת יוסף. ובכ\"מ)."]]],[1300161073,"<h3>וארא ב</h3>\nא. אויפן פסוק¹ „הוא אהרן ומשה אשר אמר ה׳ להם הוציאו את בנ״י”, וואו עס שטייט פריער אהרן און דערנאך משה, זאגט רש״י „יש מקומות שמקדים אהרן למשה, ויש מקומות שמקדים משה לאהרן לומר לך ששקולין כאחד”².\nדער ענין ווערט באוארנט אויך אין תוספתא³ און אין מדרש⁴, אבער דארטן איז דער לשון „בכל מקום הקדים משה לאהרן, במקום אחד הוא אומר אהרן ומשה מלמד ששקולין זה כזה”.\nדער טעם וואס רש״י מוז זאגן „יש מקומות שמקדים אהרן למשה ויש מקומות שמקדים משה לאהרן” — ניט ווי אין תוספתא ומדרש „בכל מקום הקדים משה לאהרן במקום אחד הוא אומר⁵ כו׳” — איז מובן בפשטות, ווייל ע״פ דרך הפשט לייגט זיך ניט צו זאגן, אז פון דעם וואס דער פסוק איז משנה „במקום אחד” אנדערש ווי דער סדר איז „בכל מקום”⁷, זאל מען אפלערנען א\nחידוש עיקרי בכל המקומות („שקולין כאחד”)⁸,\n[דערמיט ווערט אויך פארענטפערט וואס רש״י ברענגט ניט דעם ענין פון „שקולין כאחד” אין די אנדערע ערטער וואס ווערן אויסגערעכנט אין תוספתא און מדרש הנ״ל, וואו מיר געפינען⁹ אז „במקום אחד” איז דער פסוק מהפך דעם סדר פון צווי זאכן, און דערפון לערנט מען ארויס אז זיי זיינען שקולים],\nנאר מ׳דארף זאגן אז דער שינוי במקום אחד איז צוליב א טעם, וואס איז דא נאר בא דעם מקום אחד; וע״ד ווי רש״י איז מפרש¹⁰ דעם",[["1","1","פרשתנו ו, כו."],["2","2","כ״ה בדפוסים שלפנינו. ובדפוס ראשון ושני „ששקולין שניהם כאחד”. ובכ״כ כת״י רש״י „ששניהם שקולין כאחד”."],["3","3","סוף כריתות."],["4","4","ב״ר ספ״א. ויק״ר פל״ו, א. ועד״ז במדרש שמואל פ״ה. יל״ש בראשית רמז ד. וראה גם מכילתא בתחלתו. תנחומא (באבער) בראשית יד. ועוד."],["5","5","כ״ה בתוספתא. ובב״ר מכילתא מד״ש ויל״ש (תנחומא) שם „ששניהן שקולין”. בויק״ר „ששניהם שוין זה כזה”."],["6","6","אבל במכילתא (ועד״ז בתנחומא שם) אף שמביא הראי׳ רק מכתוב זה „הוא משה ואהרן” אינו מקדים „במקום אחד הוא אומר”, כבתוספתא ומדרשים הנ״ל."],["7","7","ובפרט שהסדר כמו שהוא „בכל מקום” מובן גם בשכל — וכמו בנדו״ד דמשה הוא גדול מאהרן. וראה לקמן בפנים."],["8","8","ומה שפרש״י בפ׳ פינחס (כו, א): ולהלן הוא אומר ותהיינה מחלה תרצה מגיד שכולן שקולות זו כזו (היינו שהלימוד ששקולות זו כזו הוא משינוי הסדר במקום אחד) — ראה לקו״ש ח״ח ע׳ 203 (ושם הערה 20) שהלימוד הוא (לא משינוי הסדר לחוד, כ״א) מיתור הכתוב. ועד״ז בנוגע לפרש״י ס״פ מסעי „מגיד ששקולות זו כזו”, אינו משינוי הסדר לחוד (ראה שם ע׳ 204־5)."],["9","9","שברובם מאלו שנאמרו שם מובן גם בשכל הסדר כפי שנמנו „בכל מקום”, כי הראשון הוא למעלה או קדום להשני (שמים וארץ, אברהם יצחק ויעקב, משה ואהרן, אב ואם)."],["10","10","ועד״ז בפ׳ בחוקותי כו, מב [שג״ז אחד המקומות שהובא בתוספתא ומדרשים הנ״ל: בכ״מ הקדים אברהם לאבות במקום אחד הוא אומר וזכרתי את בריתי יעקב כו׳] פרש״י: למה נמנו אחורנית כלומר כדאי הוא יעקב הקטן לכך ואם אינו כדאי הרי יצחק כו׳. ולכאורה י״ל עד״ז בהשינוי „ביום עשות ה׳ אלקים ארץ ושמים” (שבתוספתא ומדרשים הנ״ל), דמובן בפשש״מ שהשינוי בסדרם הוא משום שהכתוב משנה לומר „(ביום) עשות” (לא כבכ״מ לפנ״ז שנאמר „בראשית ברא”, „ואלה תולדות השמים *) אבל ראה לקמן סוף הערה 10."]]],[1300161074,"פסוק¹¹ „איש אמו ואביו תיראו” [איינע פון די ערטער וואס ווערן גערעכנט אין מדרש הנ״ל — „בכ״מ הוא מקדים כיבוד אב לאם ובמקום אחד הוא אומר איש אמו ואביו תיראו מגיד ששניהם שקולין זה כזה”] — „כאן הקדים אם לאב לפי שגלוי לפניו שהבן ירא את אביו יותר מאמו, ובכבוד הקדים אב לאם לפי שגלוי לפניו שהבן מכבד את אמו יותר מאביו מפני שמשדלתו בדברים”.\nאון דעריבער זאגט רש״י בנדו״ד „יש מקומות כו׳ ויש מקומות כו׳” — לשון רבים — ווייל דוקא פון דעם וואס דער שינוי הסדר איז אין כמה מקומות¹² קען מען אפלערנען אז „שקולין כאחד”¹³.\nב. מען דארף אבער פארשטיין: ס׳איז מובן, אז דאס וואס אין רש״י איז דער לשון „יש מקומות”, אז ס׳איז דא מער ווי איין ארט וואו דער פסוק איז מקדים אהרן פאר משה, און אין תוספ־\nתא ומדרש שטייט אז דאס איז נאר „במקום אחד” — איז עס ניט קיין פלוג־תא אין מציאות (צי דאס געפינט מען אין תורה איין מאל אדער מערערע מאל — אין דעם איז דאך ניט שייך קיין מחלוקת), נאר דער חילוק ביניהם איז — צי אין די אנדערע ערטער וואו דער פסוק איז מקדים אהרן פאר משה (חוץ דעם פסוק „הוא אהרן ומשה”), איז עס כדי אפלערנען אז זיי זיינען „שקולין כאחד” אדער דארט מוז שטייען בסדר זה דוקא.\nדי אנדערע מקומות אין תורה וואו דער פסוק דערמאנט פריער אהרן פאר משה, זיינען: א) אין דער פרשה, מיט עטלעכע פסוקים פריער¹⁴ — „ויקח עמרם את יוכבד דודתו לו לאשה ותלד לו את אהרן ואת משה”; ב) אין פ׳ במד־בר¹⁵ — „ואלה תולדות אהרן ומשה”; ג) אין פ׳ פינחס¹⁶ „ותלד לעמרם את אהרן ואת משה”\n— איז פארשטאנדיק בפשטות דער טעם פארוואס די תוספתא און מדרש נעמען אן אז פון די פסוקים קען מען ניט מדייק זיין אז „שקולין זה כזה”, היות אז אין זיי רעדט זיך וועגן לידת אהרן ומשה (אדער זייערע תולדות), דערי־בער מוז דער פסוק מקדים זיין אהרן פאר משה — לויטן סדר לידתם¹⁷.",[["","","והארץ בהבראם”) שפירושו כמו שפרש״י לפנ״ז (שם א, כה): „תקנם בצביונם בתקונם ובקומתם” (וע״ד פי׳ ר״י ורבי תנחומא בב״ר שם, וש״נ), וענין זה שייך יותר ב„ארץ” מבשמים. [אבל להעיר שבשמים וארץ מצינו בב״ר שם (וש״נ) דעת ר״א ב״ר שמעון „פעמים שהוא מקדים כו׳ אלא מלמד ששניהם שקולין זה כזה”. וראה מפרשים שם]. ועד״ז צ״ל בשאר דוגמאות שבתוספתא ומדרש שם, שמובן מעצמו בפשש״מ."],["11","11","קדושים יט, ג."],["12","12","להעיר מדעת ר״א בר״ש (הנ״ל הערה 10)."],["13","13","ואולי י״ל שבתוספתא ומדרש „מלמד ששקולין זה כזה” הוא מהלשון „הוא אהרן ומשה”, שמשמע שהם מציאות והוי׳ אחת, ע״ד דעת ר״ע (ב״ב קכ, א) בבנות צלפחד (אבל ראה רשב״ם ב״ב שם ד״ה שקולות)*. ועפ״ז יומתק הלשון „במקום אחד הוא אומר אהרן ומשה”, ולא במקום אחד הוא מקדים. אבל צ״ע אם אפשר לפרש כן בשאר המקומות. *) וראה לקו״ש שם הערה 22."],["14","14","ו, כ."],["15","15","ג, א."],["16","16","כו, נט."],["17","17","כבראב״ע פרשתנו ו, כז בסופו. וצ״ע במה שהראב״ע מקדים את הכתוב „ואלה תולדות אהרן ומשה” (דפ׳ במדבר) לפני הפסוק „ותלד לו את אהרן ואת משה” (שבפרשתנו לעיל). ואולי צ״ל* „ותלד לעמרם” והיינו הכתוב דפ׳ פינחס. ובפרט *) ולהעיר מטור הארוך כאן שהביא בלשון הראב״ע „ומותלד את אהרן ואת משה”."]]],[1300161075,"עס איז אבער ניט מובן: וואס איז די סברא פון רש״י וואס רעכנט אויך די מקומות אלס א הוכחה „ששקולין כאחד”, ובפרט אז דוקא רש״י איז לימודו בדרך הפשט?\nג. לכאורה י״ל אז כוונת רש״י איז ניט די פסוקים — „ותלד לו את אהרן ואת משה” (בפרשתנו) און „ותלד לעמרם את אהרן ואת משה” (בפ׳ פינחס) — ער מיינט נאר דעם פסוק „ואלה תולדות אהרן ומשה” וואס דארטן רעדט זיך ניט וועגן דער לידה פון משה ואהרן עצמם, נאר וועגן זיי־ערע תולדות — און וואס נאכמער: די תולדות פון משה ווערן דארט אינ־גאנצן ניט דערמאנט (וואס דערפאר זאגט רש״י¹⁸ אז „מלמד שכל המלמד את בן חבירו תורה מעלה עליו הכתוב כאילו ילדו” און דעריבער ווערן „בני אהרן” אנגערופן „תולדות משה לפי שלמדן תורה”)\nובמילא האט דארט געדארפט זיין דער סדר הרגיל בכל מקום (משה ואהרן) ואדרבה: דארט דארף שטיין משה פריער נאך ביתר שאת ווי בכל מקום, ווייל ער איז געווען דער וואס „למדם תורה” (און אויך צו אהרן), וואס וועגן דעם רעדט זיך דארט אין פסוק¹⁹.\nאון היות אז דארטן אויך הקדים אהרן למשה — („יש מקומות”, לשון רבים — צוזאמען מיטן פסוק „הוא אהרן ומשה”) איז דאס — ללמדך ששקולין כאחד.\nאבער עס איז שווער צו זאגן אז דאס איז כוונתו של רש״י, ווייל אויב ער וואלט געמיינט נאר דעם פסוק בספר במדבר, אויסשליסנדיק דעם פסוק בפר־שתנו — וואלט ער דאס געזאגט במפר־רש; פונעם לשון „יש מקומות” סתם איז משמע אז דאס זיינען מקומות וואס מ׳ווייס שוין פון זיי²⁰ (אדער עכ״פ אזעלכע וואס שטייען אין דעם המשך פון די פרשיות).\nד. עס איז אויך קשה אין דעם פרש״י לויט התחלתו. וז״ל: „הוא אהרן ומשה, אלו שהוזכרו למעלה שילדה יוכבד לעמרם”, דאס מיינט, אז דער פסוק קומט בהמשך צום ענין פון לידת אהרן ומשה וואס שטייט למעלה („שילדה יוכבד”) — איז דאך מובן בפשטות אז דער פסוק מוז מקדים זיין אהרן פאר משה²¹ — היינט ווי אזוי קען מען פון דעם סדר בהפסוק ארויסלערנען אז „שקולין כאחד”?\nואפילו את״ל אז פונעם המשך פון דעם פסוק, „(הוא אהרן ומשה) אשר אמר ה׳ להם הוציאו את בנ״י מארץ מצרים”, איז מוכח אז דא איז ניט נוגע",[["","","שהראב״ע שם מקדים „על כן לא תמצא בכל התורה מתחלת זה הפסוק שלא יקדים משה לאהרן”. א״כ אין מקום להקשות מפרשתנו הנאמר לפני פסוק זה. ועפ״ז יובן מה שהקדים גם בסוף הדיבור „והעד תולדות גם ותלד” — אף שלכאורה קדימת אהרן למשה מיושבת יותר כשהמדובר הוא בלידתם עצמם — „ותלד”, מכשהמדובר הוא ע״ד תולדותם — ראה לקמן בפנים."],["18","18","ראה בפרש״י זה לקו״ש חכ״ג ע׳ 8 ואילך. חט״ו ע׳ 181 ס״ח. חי״ג ע׳ 9 הערה 1."],["19","19","וכהמשך בהכתוב „ביום דבר ה׳ את משה”, ופרש״י „נעשו אלו התולדות שלו שלמדן מה שלמד מפי הגבורה”. ורק בפסוק שלאח״ז נאמר „ואלה שמות בני אהרן”. וראה סנה׳ יט, ב."],["20","20","וכה„יש מקומות שמקדים משה לאהרן”, שידועים הם להבן חמש וגם לפני כתוב זה."],["21","21","כמ״ש במפרשים עה״פ — רשב״ם, חזקוני, תוספת (הדר זקנים), ועד״ז בראב״ע עה״פ (כי הוא גדול בשנים), רבינו בחיי, אברבנאל עה״פ. אלא שבראב״ע ואברבנאל מוסיפים: ועוד כי הוא התנבא לישראל קודם שבא משה [ולהעיר שב׳ ענינים הנ״ל כבר הובאו בפרש״י לפנ״ז (שמות ד, יו״ד)]."]]],[1300161076,"(סדר) לידתם, נאר — זייער תפקיד אין אויספירן דעם ציווי ה׳ בקשר צו יציאת בנ״י ממצרים — איז ניט מובן:\n— ער האט געדארפט מפרש זיין דאס ע״ד ווי זיין פירוש אויף „איש אמו ואביו תיראו”, אז דער טעם וואס דער פסוק איז משנה דעם סדר הקדימה איז ווייל עס פאדערט זיך א הדגשה מיוחדת בנוגע איינעם פון די פרטים — ועד״ז בנדו״ד: דאס וואס דער פסוק זאגט דא „הוא אהרן ומשה” (אהרן פריער), איז ווייל מיט מקדים זיין אהרן פריער איז די תורה אויסן צו מדגיש זיין און בא־וארענען²²: היות אז דאס רעדט זיך וועגן זייער שליחות ארויסצונעמען אידן פון מצרים, וואס פון פשטות הכתובים איז משמע אז אין דעם איז משה געווען דער גאנצער עיקר, וועמען דער אוי־בערשטער האט אויסגעקליבן און אים אנפארטרויט די שליחות — דעריבער איז דער פסוק דא משנה ומקדים „הוא אהרן (פריער) ומשה”, צו מדגיש זיין אז אהרן איז ניט געווען אינגאנצן טפל צו משה אין דער שליחות²³.\nה. וועט מען דאס פארשטיין דורך מסביר זיין נאך כמה דיוקים אין פרש״י:\nרש״י שטעלט זיך אויף „הוא אהרן ומשה” און איז מפרש „אלו שהוזכרו למעלה שילדה יוכבד לעמרם” (און לויט׳ן נוסח פון כמה דפוסים²⁴ איז ער ממשיך) „הוא אהרן ומשה אשר אמר ה׳²⁵ יש מקומות שמקדים כו׳”. ולכאורה:\nא) וואס פאר א שייכות בתוכן האט דער ענין אז „יש מקומות שמקדים כו׳ לומר לך ששקולין כאחד” צו התחלת הדיבור „אלו שהוזכרו למעלה שילדה יוכבד לעמרם”?\nב) אויב אז כוונתו איז צו באוא־רענען דעם שינוי ההקדמה (בסדר שמו־תיהם) פון איין מקום לגבי א צווייטן וואלט דאך (אמבעסטן) מתאים געווען צו ברענגען דעם שינוי וואס מ׳געפינט — גלייך אין סיום פון פסוק שלאחרי זה אין זעלבן ענין און מיט די זעלבע ווער־טער — „הוא משה ואהרן”²⁶?\nאויך דארף מען פארשטיין:\nג) וואס טוט אויף רש״י מיט דעם וואס ער איז מוסיף אין בתחלת פירושו „(אלו שהוזכרו למעלה) שילדה יוכבד לעמרם” — צי דען וואלט מען געקענט מיינען אז דאס זיינען ניט די וואס „הוזכרו למעלה”?\nד) פארוואס זאגט רש״י „ששקולין כאחד” — ניט ווי דער לשון וואס שטייט",[["22","22","וכמו שפי׳ בביאורי מהראי״ה, ועד״ז בכלי יקר כאן בפי׳ הא׳. פנים יפות כאן. ושם מפרשים עד״ז גם ב„הוא משה ואהרן” שבפסוק שלאח״ז."],["23","23","בכלי יקר שם מפרש שמזה מוכח „שקולים המה בכל דבר”. אבל בביאורי מהראי״ה שם, „חלק הכתוב כבוד לאהרן כו׳” ומציין „ועל דרך זה פי׳ בפ״ק דקדושין (ל, סע״ב ואילך) גבי איש אמו ואביו תיראו”, והוא כהפי׳ ברש״י ר״פ קדושים. ומה שבס״פ מסעי כתב רש״י טעם לשינוי הסדר ואעפ״כ מסיים „מגיד ששקולות כו׳” — ראה לקו״ש ח״ח שם ע׳ 205 (הובא לעיל הערה 8)."],["24","24","וכן הוא בדפוס ראשון. בדפוס שני וכמה כת״י רש״י במקום „הוא אהרן ומשה” אי׳ „הוא משה ואהרן” ומתחיל ד״ה בפ״ע."],["25","25","בכמה כת״י ליתא התיבות „הוא אהרן ומשה” והמשך פרש״י „יש מקומות כו׳” בא תיכף לאחרי התיבות „שילדה יוכבד לעמרם”."],["26","26","וכבכמה מפרשי התורה (הנ״ל הערה 22. ועוד). ולהעיר מלשון השל״ה שם, ב: ויהי׳ מתורץ ג״כ מ״ש בזה הפרשה הוא אהרן ומשה הוא משה ואהרן ופרש״י ללמד ששניהם שקולין. וראה לקמן הערה 63."]]],[1300161077,"אין תוספתא און מדרש²⁷: ששקולין זה כזה²⁸?\nה) ועיקר: ווי אזוי קען מען בכלל זאגן בנוגע צו משה ואהרן אז „שקולין כאחד”, בשעת אז אפילו א בן חמש למקרא ווייס אז ס׳איז ניטא קיין גלייכן צו משה רבינו²⁹, ובפרט אז ער ווייס שוין פון פרש״י פריער³⁰ אז „כשנולד נתמלא הבית כולו אורה”, און ער איז געווען מושיעם של ישראל³¹, וכו׳³² — און רש״י באוארנט דאס אלס ניט³³.\nוא״ו. אין פסוק שלאחרי זה שטעלט זיך רש״י אויף די ווערטער „הם המדב־רים וגו׳” און איז מפרש „הם שנצטוו הם שקיימו”. בפשטות איז רש״י אויסן דער־מיט באוארענען (ווי מפרשים³⁴ זיינען מסביר) די שאלה: צוליב וואס דארף דער פסוק זאגן „הם המדברים”? ס׳איז\nדאך א זאך מ׳ווייס שוין! דעריבער איז רש״י מפרש „הם שנצטוו הם שקיימו”. אבער — מאי קמ״ל? איז דען א חידוש אז משה ואהרן האבן מקיים געווען דעם ציווי ה׳³⁵?\nדערנאך שטעלט זיך רש״י אויף „הוא משה ואהרן” און איז מפרש: „הם בשליחותם ובצדקתם מתחלה ועד סוף” — איז ניט מובן:\nא) וואס איז דא נוגע די מעלה וואס זיי זיינען געבליבן גאנץ „בשליחותם ובצדקתם מתחלה ועד סוף”?\nב) וואס זיינען די ביידע פרטים „בשליחותם ובצדקתם”: מיינט רש״י זייער כללות׳דיקע שליחות און צדקות³⁶, און ווי עס שטייט אין גמרא³⁷, האט ער געדארפט זאגן (כלשון הגמרא) בלויז „הן בצדקתם מתחלה ועד סוף”; וואס איז ער מוסיף „בשליחותם”? און אויב ער מיינט אלס המשך ופירוש צום תוכן פון התחלת הכתוב, „הם שנצטוו הם שקיימו”, איז דאך דא (בעיקר) נוגע דאס וואס זיי זיינען געווען גאנץ „בשלי־חותם מתחלה ועד סוף” (און ניט זייער צדקות בכלל)?\nג) וואס איז רש״י מקדים בתחלת פירושו דעם וואר׳ט „הם”, און הויבט ניט",[["27","27","בויק״ר יש גירסאות „שקולין כאחד” (ראה ויק״ר הוצאת מרגליות). בגמ׳ (פסחים נז, ב. כריתות בסופה) — הלשון „שקולין כאחד” (כאחת) לענין כבשים ועזים."],["28","28","וכן הוא לשון רש״י בפ׳ פנחס ופ׳ מסעי בענין בנות צלפחד (כנ״ל הערה 8)."],["29","29","וראה ראב״ע עה״פ. של״ה שם. ובכ״מ."],["30","30","שמות ב, ב."],["31","31","פרש״י שם א, כב."],["32","32","ובכל הפרשה דשמות ג, א ואילך. שאליו נגלה ה׳, והוא הי׳ שליח ה׳ וכו׳."],["33","33","ומ״ש במשכיל לדוד כאן באותה שעה קאמר כו׳ א״נ במעשים קאמר — אין זה בפרש״י אפילו לא ברמז, כ״א כותב סתם „לומר לך ששקולין כאחד”. ועד״ז בנוגע לשאר הפירושים שבפרש״י (ברא״ם ס״פ מסעי. צידה לדרך כאן. ועוד), שאין להם שום רמז בלשון רש״י."],["34","34","ראה דבק טוב כאן. וראה רא״ם, גו״א ובאר יצחק כאן. *) וראה גם ראב״ע, אברבנאל, אלשיך עה״פ. ועוד."],["35","35","ודוחק לומר שהוצרך להשמיענו כיון שמשה שאל (שמות ג, יא) „מי אנכי כי אלך אל פרעה”, וגם לא רצה לקבל השליחות (שם ד, יו״ד. יג): טען (שם ה, כב) „למה הרעותה לעם הזה למה זה שלחתני” — „קובל אני על ששלחתני” — כי כל הנ״ל לא מצינו בנוגע לאהרן, וכאן כוללם יחד „הם המדברים”, „הם שנצטוו הם שקיימו”. ועוד ועיקר: גם בנוגע למשה פשיטא שלאחרי שקבל השליחות „קיימו”, וענין הזריזות בקיום הציווי (לשלול — ההתרשלות דשמות ד, כד כפרש״י שם) — הרי אינו מודגש בלשון רש״י „הם שקיימו”."],["36","36","כדמשמע ברא״ם ובאר יצחק."],["37","37","מגילה יא, א. וראה חדא״ג מהרש״א שם."]]],[1300161078,"און גלייך (בהמשך צום לשון הכתוב „הוא משה ואהרן”) — „בשליחותם ובצדקתם מתחלה ועד סוף”?\nז. דער ביאור בכל זה:\nדי קשיא וואס קומט דא באוא־רענען איז: לכאורה זיינען די צווי פסוקים בכלל איבעריק. עס שטייט דאך שוין פריער³⁸ „וידבר ה׳ אל משה ואל אהרן ויצוום גו׳”; ס׳איז נאר — ווי רש״י איז מפרש³⁹ — וואס אין מיטן פון דעם ענין האט דער פסוק מפסיק געווען צו דערציילן „האיך נולדו משה ואהרן ובמי נתיחסו”. און ווען דער פסוק פארענדיקט דעם ענין פון זייער יחוס, הויבט ער אן נאכאמאל „וידבר ה׳ גו׳”⁴⁰, אזוי אז דאס איז (בלשון רש״י) „הוא הדיבור עצמו האמור למעלה”. דאס איז אבער נאר מסביר פארוואס דער פסוק דארף נאכאמאל זאגן „וידבר גו׳”. עס איז אבער ניט פארשטאנדיק די אריכות אין די צווי פסוקים — „הוא אהרן ומשה אשר אמר ה׳ להם גו׳”, ווי־באלד זייער תוכן איז שוין באוואוסט פון פריער?\nאון דאס באוארנט רש״י מיט זיין פירוש „אלו שהוזכרו למעלה שילדה יוכבד לעמרם” — און דאס פארענט־פערט אויך פארוואס דער פסוק דארף מפסיק זיין אין מיטן א דיבור וענין צו דערציילן דעם יחוס פון משה ואהרן, וכדלקמן.\nח. די הסברה אין דעם: מ׳האט שוין פריער געלערנט וועגן דער מוטער פון משה ואהרן, יוכבד⁴¹, אז זי האט ניט אויסגעפירט גזירת פרעה „אם בן הוא\nוהמתן אותו”⁴², נאר „ותיראנה המיל־דות את האלקים ולא עשו כאשר דבר אליהן מלך מצרים”; און ניט בלויז האבן זיי ניט מקיים געווען דעם „והמתן אותו”, נאר „ותחיין את היל־דים” — „מספקות להם מים ומזון כו׳”⁴³. זי האט זיך משתדל געווען צו טאן אלץ וואס זי קען אויף צו מבטל זיין די גזירה פון פרעה און נאך געטאן דעם היפך פון דעם; ועד״ז געפינט מען בנוגע צו זייער פאטער, עמרם, אז ניט קוקנדיק אויף גזירת פרעה איז „החזירה ועשה בה ליקוחין שניים”⁴⁴.\nאון דאס איז דא די תורה מטעים ומדגיש: דער טעם וסיבה פון דעם וואס „וידבר ה׳ אל משה ואל אהרן ויצוום אל בנ״י ואל פרעה מלך מצרים להוציא את בנ״י מארץ מצרים”, וואס דער אוי־בערשטער האט זיי אויסגעקליבן צו ארויספירן די אידן פון מצרים — איז דאס ווייל „הוא אהרן ומשה — שילדה יוכבד לעמרם”, צוליב דעם זכות⁴⁵ און מעלה פון זייער אב ואם⁴⁶ אין אויפ־האלטן און אויפלעבן (ותחיין) די אידן אין מצרים, זיינען זיי געווארן די וואס „אמר ה׳ להם הוציאו את בנ״י מארץ מצרים”.\nט. עפ״ז ווערט אבער שווער: דאס וואס עמרם „החזירה ועשה בה ליקוחין שניים” איז געווען נאר צוליב לידת",[["38","38","ו, יג."],["39","39","שם."],["40","40","ו, כט."],["41","41","שמות א, טו ואילך ובפרש״י."],["42","42","שם א, טז."],["43","43","שם א, יז וברש״י."],["44","44","פרש״י שם ב, א."],["45","45","להעיר שמצינו כבר לפנ״ז בתורה, פעולה ותגמול (וכיו״ב) לבנים בזכות האבות — ראה לדוגמא תולדות כו, ד־ה. שם, כד. פרש״י נח ט, כג."],["46","46","ועפ״ז יומתק לשון רש״י שם (ו, יג) „ללמדנו היאך נולדו משה ואהרן ובמי נתיחסו” — ולא כתב בקיצור „ללמדנו יחוס משה ואהרן”. ובפרט שהכתוב אינו מפרש „היאך נולדו”."]]],[1300161079,"משה — אהרן איז דאך געבארן גע־וארן פאר די ליקוחין שניים; ועד״ז אויך דאס וואס יוכבד האט זיך גע־דארפט אינשטעלן כו׳ איז עס געווען נאך לידת אהרן, נאר בא (לידתו של) משה⁴⁷, „ותצפנהו גו׳”⁴⁸ א.א.וו.; און עד״ז איז משה געווען דער עיקר אינעם צוגרייטן און אויפטאן דעם ענין הגאולה — האט דאך דער פסוק געדארפט מקדים זיין משה פאר אהרן?\nאון ניט נאר אין דעם פסוק („הוא אהרן ומשה”), נאר אויך אין פריער, וואו עס רעדט זיך וועגן זייער יחוס⁴⁹ — ווי־באלד אז די גאנצע כוונה דערבי, כנ״ל, איז (ניט סתם צו דערציילן סדר תול־\nדות כו׳⁵⁰, נאר) צו באאר זיין דעם טעם הזכות פון משה ואהרן צו זיין די שלוחים אויף דורכפירן די גאולה — האט אויך דארט געדארפט שטיין „ותלד לו את משה ואת אהרן”⁵¹ (היות אז אויך אין דעם מכוון פון סיפור לידתם איז משה דער עיקר)⁵²?\nדעריבער איז רש״י גלייך ממשיך „יש מקומות שמקדים אהרן למשה וכו׳” — וואס מיט „יש מקומות” מיינט טאקע רש״י דעם פסוק וואס דא פריער⁵³ בסמיכות „ותלד לו את אהרן ואת משה”",[["47","47","ובפרט ע״פ הדגשת רש״י (כבהערה שלפנ״ז) „היאך נולדו”."],["48","48","שם ב, ב ואילך."],["49","49","ולהעיר שמצינו במ״א (בראשית ה, לב) „ויולד נח את שם את חם ואת יפת”: א) שהכתוב מספר ע״ד לידתם, ב) נזכרים בפעם הראשונה — ואעפ״כ לא נמנו כסדר תולדותם* כ״א מקדים „שם” החשוב שבכולם כפרש״י שם**, ועאכו״כ בנדו״ד*** אשר: א) הוזכרו כאן לא בשביל סיפור תולדות עמרם ויוכבד כשלעצמם, כ״א — באיזה זכות נאמר למשה ואהרן „ויצום גו׳ להוציא גו׳”, ב) כבר הוזכרו (וידועים) לפנ״ז בתורה."],["50","50","ולכן גם הוסיף הכתוב (ו, כ) „דודתו”, כפרש״י „אחת אבוהי בת לוי אחות קהת” — שמדגיש יחוסה. ועפ״ז תובן גם הדגשת רש״י בפסוק כג ופסוק כה שם, כי כל עיקר הכתובים הוא (מעלת ה)יחוס — ראה לקו״ש חט״ו ע׳ 44 ואילך."],["51","51","וכמו שמקדים רש״י (שם ו, יג): היאך נולדו משה ואהרן."],["52","52","ואין לומר שהכתוב מקדים אהרן להדגיש שגם לאהרן חלק בהשליחות (וע״ד פרש״י ר״פ קדושים, כנ״ל סוף סעיף ד ובהמקומות שבהערה 22) — כי אף שנזכרו כאן רק בשביל ליחסם בנוגע להשליחות, מ״מ, מכיון שהלשון הוא „ותלד לו את אהרן גו׳”, לא היינו למדין מזה שהכתוב בא לחזק חלק אהרן בהשליחות. ובפרט שבפסוקים אחדים לאח״ז (ו, ז) נאמר שאהרן הוא גדול בשנים ממשה (וראה לעיל פ׳ שמות ד, יו״ד). משא״כ בנוגע למשה, כיון שמקדמים תיכף לפנ״ז (וכמ״פ) „אל משה ואל אהרן” בנוגע ציווי ה׳ והשליחות, ונזכרו כאן בשביל ליחסם, הי׳ מובן שהוא לפי שבענין זה משה הוא העיקר, וכמו לקמן (שם) שהכתוב בא לומר מנין שנותם, ואשר אהרן גדול ממשה „ואהרן הוא בן שלש ושמונים שנה” — מקדים „ומשה בן שמונים שנה”."],["53","53","וכה„יש מקומות שמקדים משה לאהרן”, שהם מפורשים לפנ״ז — שמות ד, כט. ה, א. שם כ *. וראה ו, יג. *) וכן בנוגע בנות צלפחד, שגם בפעם הא׳ (פינחס כו, לג) שנאמר „וצלפחד גו׳ לא היו לו בנים כי אם בנות”, לא נמנו כסדר תולדותם, כפרש״י ס״פ מסעי. אבל ראה לקו״ש ח״ח שם. **) אבל ראה לקו״ש חט״ו ע׳ 115 ואילך ובהערות שם. ***) אף שיש לחלק בפשטות, דב„שם” מעלתו היא שלא בערך כיון „שהוא צדיק ונולד כשהוא מהול ושאברהם יצא ממנו כו׳”, כפרש״י שם; משא״כ במשה הרי (עכ״פ בנוגע להענין המדובר „להוציא את בנ״י ממצרים), בזה נוגע משה שהוא העיקר בהשליחות. *) לכאורה י״ל שבזה נכלל גם הפסוק (שם ה, ד) „ויאמר אליהם מלך מצרים למה משה ואהרן”. אבל י״ל שפרעה הקדימו כיון שהוא הי׳ ידוע וחשוב יותר בבית פרעה, שנתגדל בביתו."]]],[1300161080,"(צוזאמען מיטן פסוק „הוא אהרן ומשה”) — „לומר לך ששקולין כאחד”.\nאון דער דיוק אין דעם איז — „שקולין כאחד”: ס׳איז ניט דער פשט אז משה ואהרן זיינען גלייך איינער צום צווייטן, אז זיי האבן ביידע די זעלבע דרגא פון גדלות וכיו״ב — נאר אז אין דער שליחות ארויסצונעמען אידן פון מצרים זיינען זיי ביידע ווי איינער: (די גלייכקייט איז אין דעם וואס זיי זיי־נען א טייל פון איינער און דער זעל־בער שליחות⁵⁴) —\n„יש מקומות שמקדים אהרן למשה ויש מקומות שמקדים משה לאהרן”, ווייל ביי זיי ביידן איז איין שליחות⁵⁵.\nיו״ד. פון דעם וואס דער פסוק איז דא מוסיף „הם המדברים אל פרעה מלך מצרים להוציא גו׳” אלס אן ענין בפ״ע, איז מוכח, אז אויך דער פרט פון זייער ריידן צו פרעה מלך מצרים איז נוגע זייער מעלת היחוס אז זיי זיינען „אלו שהוזכרו למעלה שילדה יוכבד לעמרם” — איז ניט פארשטאנדיק וואס איז די שייכות פון זייער יחוס צו זייער זיין די „מדברים אל פרעה מלך מצרים”?\nדעריבער איז רש״י מפרש „הם שנצטוו הם שקיימו”, און זייער מילוי\nהשליחות מיט זייער דיבור אל פרעה האט זיך אויפגעטאן דערפאר וואס זיי זיינען די — „הם” — „שילדה יוכבד לעמרם”:\nכשם ווי בא יוכבד איז איר ניט פאלגן און קעגנשטעלן זיך גזירת פרעה געווען פארבונדן מיט שוועריקייטן, ביז מס״נ, ווייל פרעה האט גערופן די מילדות און בא זיי געמאנט „מדוע עשיתן הדבר הזה ותחיין את הילדים” — און דעריבער איז דער פסוק מדגיש אז דאס וואס „לא עשו כאשר דבר אליהן מלך מצרים ותחיין את הילדים” איז געווען דערפאר וואס „ותיראן המילדות את האלקים” — און מהאי טעמא האבן זיי געהאט א ספעציעלן שכר⁵⁶: „וייטב אלקים למילדות גו׳ ויהי כי יראו המילדות את האלקים ויעש להם בתים”.\nועד״ז ביי עמרם אין דעם וואס „עשה בה ליקוחין שניים”, אז דאס איז געווען פארבונדן מיט שוועריקייטן און נסים — כפרש״י —\nעד״ז איז געווען די הנהגה פון אהרן ומשה אין זייער דיבור מיט פרעה מלך מצרים — אז כאטש דאס איז געווען פארבונדן מיט שוועריקייטן, ווי די תורה דערציילט פריער אז פרעה האט זיי געזאגט⁵⁷ „למה משה ואהרן תפריעו את העם גו׳ לכו לסבלותיכם” וכו׳,\nאון דעריבער איז דער פסוק מוסיף „הם המדברים אל פרעה מלך מצרים להוציא גו׳”, אז אויך אין זייער ריידן צו פרעה, און זייער אופן פון טאן זייער שליחות, האט זיך ארויסגעזאגט אז דאס זיינען „אלו שהוזכרו למעלה שילדה יוכבד לעמרם”. ד.ה. אז דאס וואס „אמר",[["54","54","להעיר מאוה״ח כאן ו, כח: ומעתה הושוו אהרן ומשה במצוה זו. ולהעיר מפי׳ מהרז״ו הארוך בב״ר שם *."],["55","55","ורש״י אינו צריך לפרש, כי פירושו הוא בפרשה זו דיצ״ם. משא״כ בתוספתא ומדרשים הנ״ל שמדובר ע״ד משה ואהרן וגדלותם בכלל — וראה שהש״ר פ״ד, ה, ובמפרשים. *) אבל מה שפי׳ כן במדרש „נקראו שקולין אף שאינם שוים” — יש להעיר שבויק״ר שם איתא „שוין זה כזה”."],["56","56","שם א, כ־כא."],["57","57","שם ה, ב ואילך."]]],[1300161081,"ה׳ להם הוציאו את בנ״י”, איז געווען ווייל זיי האבן איבערגענומען⁵⁸ און גע־האלטן ביי דער מעלה פון עמרם און יוכבד, צו וועלן אויספירן בכל כוחם⁵⁹ דעם רצון וציווי ה׳⁶⁰ — ווי מ׳האט דאס געזען אין דעם וואס „הם שנצטוו הם שקיימו”⁶¹.\nיא. ווען דער פסוק איז דערנאך מוסיף „הוא משה ואהרן” — שטעלן זיך די שאלות:\nא) וואס איז די כוונה אין דעם וואס די תורה חזר׳ט איבער דא נאכאמאל דעם לשון⁶²?\nב) פארוואס איז דער פסוק דא משנה ומקדים משה פאר אהרן [וואורום מיט די „יש מקומות” וואס רש״י ברענגט שמקדים משה לאהרן מיינט ער ניט (בדוקא) דעם פסוק⁶³, כנ״ל (אז פון דעם ווייס מען אז שקולין כאחד), נאר די כמה פסוקים פריער אין וועלכע מ׳איז מקדים משה פאר אהרן⁶⁴].\nג) דער פסוק הויבט אן בלשון רבים „הם המדברים” און איז מסיים (ניט „הם משה ואהרן”, נאר) „הוא משה ואהרן”, בלשון יחיד⁶⁵.\nדערויף איז רש״י מפרש „הם בשלי־חותם ובצדקתם מתחלה ועד סוף”: דער ענין פון „הוא משה ואהרן” דא איז ניט ווי „הוא אהרן ומשה” אין פריערדיקן פסוק, וואס דארט איז די הדגשה אז „שקולין כאחד”, נאר דא איז די כוונה אז „הם בשליחותם” (רבים — צווי), יע־דער איינער איז בפ״ע;\nד.ה. זייער זיין „שקולין כאחד” — אין דער שליחות זיינען זיי ווי „אחד” כנ״ל — איז נאר ווי דער ענין איז מצד „אמר ה׳ להם”, מצד דעם ציווי פון דעם אוי־בערשטן, אבער דער מילוי השליחות בפועל איז געווען ניט באופן אחד, נאר אין צווי, בא יעדן איינעם פון זיי באופן שונה:\nמשה האט זיך „געדונגען” מיטן אויבערשטן, האט געזאגט „שלח נא ביד תשלח”⁶⁶ (מצד צדקת משה „שלא הי׳ רוצה ליטול גדולה על אהרן”⁶⁷) וכו׳, משא״כ ביי אהרן׳ען איז דאס געווען אין אן אופן פון „וראך ושמח בלבו”, און „לא כשאתה סבור שיהא מקפיד עליך שאתה עולה לגדולה”⁶⁸; ולאידך, אין דער שליחות בפועל איז משה געווען דער ראש ועיקר און אהרן איז ביי אים גע־ווען „לפה ולמליץ”⁶⁹ — סיי בנוגע דעם דיבור צו אידן און אזוי אויך בנוגע דעם דיבור צו פרעה. משה איז געווען „אלקים לפרעה” — „שופט ורודה",[["58","58","להעיר מעדיות (פ״ב מ״ט) „האב זוכה לבן כו׳”. ובר״ע״ב שם: שקרוב טבע הבן להיות דומה לטבע האב. והרי זה מובן גם בפשש״מ. ולכאורה זוהי הכוונה בפשטות ד„ובמי נתיחסו”. וראה לקו״ש ח״ח ע׳ 162 ואילך."],["59","59","ולהעיר, דגם בנוגע לישראל איתא במדרש (שמו״ר פ״ז, ג) א״ל הקב״ה בני סרבנים הן רגזנין הן טרחנין הן ע״מ כן תהיו מקבלין עליכם שיהיו מקללין אתכם שיהיו מסקלין אתכם באבנים. ובאוה״ת פרשתנו ע׳ קצא: והוו שפירשי׳ בחומש (שם) ציוה עליהם להנהיגם בנחת ולסבול אותם."],["60","60","וראה פרש״י פרשתנו שם, יג „צום עליו לחלוק לו כבוד בדבריהם”."],["61","61","להעיר מפרש״י (ג, יב) „ואינך ניזוק”."],["62","62","ראה מפרשי רש״י (הנ״ל הערה 34)."],["63","63","ראה מפרשי הנ״ל (הערה 26). ולהעיר שכן משמע גם מהגירסא בדפוס שני (אל חג״ירא רל״ו — הוגה ע״י ר״ש אלקביץ, זקנו של בעל „לכה דודי”) וכת״י רש״י (שנעתק לעיל הערה 24) שמעתיק „הוא אהרן ומשה” לפני הפי׳ „יש מקומות שמקדים כו׳”."],["64","64","נסמן לעיל הערה 53."],["65","65","ראה זח״ב כו, ב. אוה״ח עה״פ."],["66","66","שם ד, יג."],["67","67","פרש״י שם ד, יו״ד."],["68","68","שם ד, יד ובפרש״י."],["69","69","פרש״י פרשתנו ו, יג."]]],[1300161082,"לרדותו במכות ויסורין”, און „אהרן אחיך יהי׳ נביאך”⁷⁰ — „ימליצנו ויטעי־מנו באזני פרעה”⁷¹.\nאון דאס איז רש״י מוסיף בפירושו ומדגיש „הם בשליחותם ובצדקתם”, אז דער לשון „הוא” דא, וואו דער פסוק איז מקדים משה פאר אהרן, באציט זיך אויף משה בפ״ע און אהרן בפ״ע (כאילו ווי עס וואלט געשטאנען „הוא משה והוא אהרן”), און דאס איז מסביר אז „הם בשליחותם ובצדקתם”: בנוגע דעם מילוי השליחות בפועל זיינען זיי „הם”, רבים, צווי באזונדערע אופנים „בשליחותם (וועלכע זיינען פארבונדן מיט זייערע באזונדערע מעלות אויך) ובצדקתם”.\nיב. פון יינה של תורה אין פירוש רש״י:\nס׳איז מבואר אין חסידות⁷² אז משה ואהרן זיינען בדוגמת השמות הוי׳ און אלקים, און „הוא אהרן ומשה”, „הוא משה ואהרן” (און ניט „הם אהרן ומשה גו׳”) וואס דערמיט ווערט געמיינט אז זיי זיינען איין זאך, איז דער ענין פון „הוי׳ הוא האלקים” יחוד הוי׳ ואלקים.\nאון דאס זיינען די צווי ענינים פון „הוא אהרן ומשה” און „הוא משה ואהרן”: אין דעם יחוד הוי׳ ואלקים זיינען דא צווי אופנים און מדריגות, וועלכע זיינען מרומז אין די צווי מאל⁷³ „ה׳ הוא האלקים” און — י״ל בדרך אפשר — וועלכע שטייען אין די צווי פסוקים: „אתה⁷⁴ הראית לדעת כי ה׳ הוא\nהאלקים אין עוד מלבדו”, און „וידעת⁷⁵ היום והשבות אל לבבך כי ה׳ הוא האלקים בשמים ממעל ועל הארץ מתחת אין עוד”.\nוי״ל אז „הוא אהרן ומשה” איז מרמז אויף דער בחי׳ פון „ה׳ הוא האלקים” ווי ס׳איז מצד „אתה הראית”, און „הוא משה ואהרן” — בחי׳ „ה׳ הוא האלקים” מצד „וידעת היום”⁷⁶.\nיג. דער ביאור בזה⁷⁷: דער יחוד ה׳ הוא האלקים פון „אתה הראית” איז בדרך גילוי מלמעלה למטה, ווי דער אלטער רבי האט געטייטשט⁷⁸: „אתה — דו עצמות א״ס ב״ה, הראית — האסט זיך באוויזן, לדעת — אז מען זאל דיך וויסן”. און דעריבער שטייט ניט אין דעם פסוק „בשמים ממעל ועל הארץ מתחת”, ווייל מצד דעם גילוי מלמעלה, זעט זיך אין יעדער זאך זיין שורש, זיין „למעלה”, (אין שמות), און „שמים” און „ארץ” זעען זיך ניט אן אלס מציאות בפ״ע;\nמשא״כ „ה׳ הוא האלקים” מצד „וידעת היום גו׳ והשבות” איז בדרך מלמטה למעלה. די ידיעה והכרה אז ה׳ הוא האלקים זאל ביי דעם אדם זיין ע״י עבודתו. און דעריבער איז דא „בשמים ממעל ועל הארץ מתחת” — שמים און ארץ זיינען באזונדער און אפגעטיילט. מצד דעם יחוד מלמטה למעלה הערט",[["70","70","ז, א ובפרש״י."],["71","71","פרש״י שם, ב. וראה בארוכה לקמן ע׳ 69 ואילך."],["72","72","אוה״ת פרשתנו ע׳ קמה. ע׳ רכו ואילך. ע״פ זח״ב שם. וראה ספר הערכים־חב״ד כרך ב׳ ע׳ אהרן — ביחס למשה סעיף יא, וש״נ."],["73","73","מלכים א יח, לט."],["74","74","ואתחנן ד, לה."],["75","75","שם, לט."],["76","76","כן משמע קצת באוה״ת שם ע׳ רכו, שממשיך „גם בלקוי״ת בד״ה וידעת היום כו׳”, ע״ש."],["77","77","בהבא לקמן ראה ד״ה וידבר אלקים (הב׳) תש״ד פי״ד. לקו״ש ח״ד ע׳ 1334 ואילך. ועפ״י המבואר לקמן (בסוף הסעיף) יש לתווך ביאור הנ״ל עם המבואר בלקוי״ת ואתחנן שם — דהם ב׳ הבחי׳ דממלא וסובב (ועם המבואר באוה״ת שם). ואכ״מ."],["78","78","הובא בד״ה וידבר שם."]]],[1300161083,"זיך אן די התחלקות אין נבראים, און מ׳דארף אין זיי פועל זיין דעם ענין היחוד והאחדות בגילוי.\nאבער לאידך, דוקא אין דעם יחוד פון ה׳ הוא האלקים בדרך מלמטה למעלה, מצד דעם וידעת, דריקט זיך אויס אחדותו ית׳ מער ווי אין ה׳ הוא האלקים מצד דעם גילוי מלמעלה (אתה הראית), אז כאטש די וועלט זעט זיך ווי א מציאות פאר זיך, אעפ״כ איז דער עולם מיוחד עמו ית׳ בתכלית היחוד, וואס דאס נעמט זיך מצד העצמות דוקא, וואס ער איז כל יכול ונושא הפכים.\nיד. און דאס זיינען די צווי אופנים פון „הוא אהרן ומשה” און „הוא משה ואהרן”, וואס רש״י איז מפרש ומגלה:\n„הוא אהרן ומשה” איז „אלו שהוזכרו למעלה שילדה כו׳”: דאס איז די מדריגת היחוד פון „ה׳ הוא האלקים” ווי זי ווערט נמשך בדרך גילוי (והולדה) מלמעלה, וואורום דא רעדט זיך (כפירוש הפשוט אין פסוק) „אשר אמר ה׳ להם”, ווי דאס איז מצד האמירה מלמעלה;\nאון מצד דעם גילוי מלמעלה, איז — „שקולין כאחד”, ס׳איז מלכתחילה ניטא קיין ארט אויף התחלקות ופירוד, ס׳איז איין מדריגה, אחדות.\nאין צווייטן פסוק וואו עס שטייט „הוא משה ואהרן” וואס פון דעם שטייט נאך פריערדיקן פסוק און איז דא מקדים משה פאר אהרן, איז מוכח אז דאס איז נאך א העכערע מדרי־גה — איז רש״י מפרש ומגלה אז דאס\nקומט מצד דער עבודה ופעולת המטה: „הם בשליחותם ובצדקתם”, בהמשך צו התחלת הכתוב „הם המדברים אל פרעה”, „הם שקיימו”, וואס מצד עבודת האדם איז דא אן ענין פון התחלקות ופירוד אין נבראים.\nאון דוקא מצד דעם אופן, אז דער יחוד קומט מצד עבודת האדם, דע־מאלט איז דעם ניטא קיינע שינויים „מתחלה ועד סוף”, ווייל דאס איז פאר־בונדן מיט דעם יחוד ווי דאס איז מצד עצמותו ית׳ כנ״ל⁷⁹, וואס איז העכער פון גדר השינוי וההתחלקות וכו׳.\nוואס בגלוי וועט דער אופן זיין לעת״ל⁸⁰, ווען „מלאה הארץ דעה את ה׳”⁸¹, וואס דעמאלט וועט מען זוכה זיין אז „משה ואהרן יהא עמנו”⁸², בביאת משיח צדקנו.\n(משיחת מוצאי ש״ק וארא תשל״ט)",[["79","79","ראה לקו״ש שם ע׳ 1335, שתיבת „היום” שמורה על העדר השינוי נאמרה בפסוק וידעת דוקא, כי בהיחוד דמלמטלמ״ע דוקא מתגלה מהותו ועצמותו ית׳ שלמעלה מכל ענין השינויים."],["80","80","ראה לקו״ת שם ד, ד. ו, א."],["81","81","ישעי׳ יא, ט. רמב״ם בפיה״מ הקדמה לפ׳ חלק (קודם לביאור היסודות), בספרו הל׳ תשובה ספ״ט, שם סוף הל׳ מלכים."],["82","82","תוד״ה אחד — פסחים קיד, סע״ב. ולהעיר מיומא ה, ב. ועפ״ז הנ״ל בפנים י״ל שזהו ב׳ מדריגות היחוד הנ״ל."]]],[1300161084,"<h3>וארא ג</h3>\nא. בהמשך צו דער טענה פון משה רבינו צום אויבערשטן „הן אני ערל שפתים ואיך ישמע אלי פרעה\"1, שטייט אין פסוק2: „ויאמר ה' אל משה ראה נתתיך אלקים לפרעה ואהרן אחיך יהי' נביאך. אתה תדבר את כל אשר אצוך ואהרן אחיך ידבר אל פרעה גו'\". איז רש\"י מעתיק די התחלה, די ווערטער3 „אתה תדבר\" און איז מפרש: „פעם אחת כל שליחות ושליחות כפי4 ששמעת מפי; ואהרן אחיך ימליצנו ויטעימנו באזני פרעה\".\nד.ה. רש\"י לערנט אז „אתה תדבר גו' ואהרן אחיך ידבר אל פרעה גו'\" מיינט ניט אז משה זאל ריידן (בלויז) צו אהרן און נאר אהרן זאל ריידן מיט פרעה\n— ע\"ד ווי מ'האט פריער געלערנט אין פ' שמות, אז נאכדעם וואס משה האט גע'טענה'ט צום אויבערשטן „כבד פה וכבד לשון אנכי\"5, „שלח נא ביד תשלח\"6, האט אים דער אויבערשטער געזאגט „ודברת אליו (צו אהרן) .. ודבר הוא לך אל העם גו'\"7 —\nנאר אז (אויך) משה זאל ריידן צו פרעה; און דער חילוק צווישן משה'ס דיבור און אהרן'ס איז נאר אין דעם, וואס משה האט געדארפט ריידן בלויז „פעם אחת\", און אהרן האט עס געדארפט „ממליץ\" זיין און „מטעים\" זיין „באזני פרעה\", ביז צו ווירקן אויף אים אז — „ושלח את בני ישראל מארצו\".\n[דערפאר איז רש\"י מוסיף דעם וואָרט „(ויטעימנו) באזני (פרעה)\" — הגם אז אין פסוק שטייט סתם „אל פרעה\" — וואס דאס מיינט ווי רש\"י טייטשט אין אנהויב פ' ויגש: „דבר באזני אדוני — יכנסו דברי באזנך\"].\nדער הכרח צו לערנען אז „אתה תדבר\" (פון משה) מיינט צו פרעה און ניט צו אהרן (אנדערש ווי דער סדר אין פ' שמות כנ\"ל, און ווי כמה פשטנים8 לערנען אין אזוי אויך דא)9: א) עס שטייט דאך שוין אין פריערדיקן פסוק אז „ואהרן אחיך יהי' נביאך\" — איז וואס דארף עס דער פסוק דא איבערחזרן נאכאמאל („אתה תדבר גו' ואהרן אחיך ידבר גו'\")? ב) עס שטייט בפירוש אין פסוק (פריער<sup data-n=\"10\">10</sup> „הם המדברים אל",[["1","1","פרשתנו ו, ל."],["2","2","ז, א־ב."],["3","3","אף שרש\"י מפרש כאן כל הכתוב (ולא רק התיבות „אתה תדבר\") — „את כל אשר אצוך\" — „פעם אחת כל שליחות ושליחות כפי ששמעת מפי\" (ראה ש\"ח כאן); „ואהרן אחיך ידבר אל פרעה\" — „ואהרן אחיך ימליצנו ויטעימנו באזני פרעה\" (וראה יריעות שלמה (מהרש\"ל) כאן); „ושלח את בני ישראל מארצו\" — שדיבור אהרן הוא באופן כזה שיפעול על פרעה, שלכן מדייק רש\"י „באזני פרעה\", כדלקמן בפנים — מ\"מ מעתיק רש\"י רק תיבות אלו, כדרכו בכ\"מ להעתיק רק התחלת הכתוב (או העניין) אף שכוונתו לכל הכתוב (או העניין). ראה לקו\"ש חי\"ז ע' 242."],["4","4","בדפוס ראשון ושני דרש\"י ובכמה כת\"י דרש\"י: לפי. וכן נעתק בטור הארוך פרשתנו ו, יב (ודפוסים אחדים דהרמב\"ן שם, יג). וראה לקמן הערה 35."],["5","5","ד, י."],["6","6","שם, יג."],["7","7","שם, טו־טז."],["8","8","תיב\"ע וראב\"ע כאן. רמב\"ן (לעיל ו, יג). ועוד."],["9","9","וראה ג\"כ מפרשי רש\"י (ראֿם, גר\"א, דבק טוב, משכיל לדוד ועוד)."],["10","10","ו, כז. וכן מוכח מעוד כמה פסוקים — ראה גר\"א ומשכיל לדוד."]]],[1300161085,"פרעה גו'\" — אז אויך משה האט גערעדט צו פרעה;\nדעריבער לערנט רש\"י, אז דער פסוק „אתה תדבר גו'\" קומט זאגן, אז אויך משה זאל ריידן צו פרעה, אבער ער זאל עס טאן נאר „פעם אחת .. ואהרן אחיך ימליצנו ויטעימנו וכו'\".\nב. מ'דארף אבער פארשטיין:\nא) פריער, אין פ' שמות11 ווערט דער־ציילט אז נאכדעם וואס משה ואהרן האבן צונויפגעקליבן די זקני ישראל וכו', „באו משה ואהרן ויאמרו אל פרעה גו' ויאמרו אלקי העברים גו'\". און פון דעם וואס (אויך) דארט שטייט א לשון רבים איז מוכח, אז אויך דעמאלט האבן ביידע גערעדט צו פרעה12 (ובפרט אז דער פסוק איז משנה פון פריער: בנוגע צו „כל זקני בני ישראל\" שטייט13 „וידבר אהרן גו' אשר דבר ה' אל משה\", און ביי פרעה שטייט „ויאמרו\")\n— און בפשטות איז מסתבר, אז היות משה איז געווען א „כבד פה וכבד לשון\" — וואס מהאי טעמא האט דער אויבער־שטער מסכים געווען אז אהרן „יהי' לך לפה\"14 — האט ער ניט גערעדט\nבאריכות ובפרטיות ובכמה פעמים, נאר ער האט געזאגט דעם עיקר והמוכרח און האט זיך סומך געווען אויף אהרן'ען אז ער וועט „מטעים\" זיין זיינע רייד — ד.ה. ווי אנגעזאגט בפרשתנו\nוויבאלד אזוי, שטעלט זיך די שאלה: אויב ס'איז נויטיק צו באווארענען דעם סדר פון „אתה תדבר גו' ואהרן אחיך ידבר גו'\", אז משה רעדט „פעם אחת .. ואהרן כו' ימליצנו ויטעימנו כו'\" — האט עס דער פסוק געדארפט זאגן דארט וואו זיי האבן צום ערשטן מאל גערעדט צו פרעה (אין פ' שמות)15; און אויב ס'איז א דבר המובן מעצמו (אז ווען ביידע האבן גערעדט, האט משה גערעדט בקיצור, זייענדיק א „כבד פה גו'\", און אהרן האט מטעים געווען זיינע רייד) — פארוואס דארף עס דער פסוק מפרט זיין דא? עס וואלט געווען גענוג צו זאגן בקיצור אז משה זאל מצרף זיין צו זיך אהרן'ען (ע\"ד ווי (דער פסוק און) רש\"י16 זאגט פריער אויף „וידבר ה' אל משה ואל אהרן\" — „לפי שאמר משה ואני ערל שפתים צירף לו הקב\"ה את אהרן כו'\")?",[["11","11","ה, א. ג."],["12","12","ברמב\"ן (ו, יב) כתב: „מתחילה לא צוה אותו שידבר הוא אל פרעה רק אמר ובאת אתה וזקני ישראל אל מלך מצרים ואמרתם אליו והי' אפשר שידברו הזקנים והוא יחרישו\", ומשמע שמפרש כן גם הכתוב „ויאמרו\" שבפ' שמות (שרק האחד דיבר) — אבל מפשטות הלשון „ויאמרו\" (וכן הלשון „המדברים\" שבפרשתנו) משמע, שגם משה דיבר אל פרעה (וראה גם רמב\"ן שמות ד, טו). ולהעיר ג\"כ, שברמב\"ן ו, יג כ' (בטעם הכפלת טענת משה): „והקב\"ה צוה את שניהם לדבר אל העם ואל פרעה וחשב משה כי שניהם יתנבאו כו' ושניהם יבואו כו' ואל פרעה ודי שידבר האחד כו'\" — והרי רש\"י פליג ע\"ז וס\"ל ש„הוא הדיבור עצמו האמור למעלה כו'\"."],["13","13","ד, ל."],["14","14","שם, טז. — ואף שזהו בנוגע הדיבור „אל העם\", הרי (נוסף על המבואר לקמן, שבפשטות זה תשובה גם ע\"ד השליחות לפרעה, הרי) מכיון שבפועל הי' „כבד פה גו'\" מובן שדיבר בקיצור כו', כבפנים."],["15","15","ואף שבשליחות זו לא הי' ציווי מיוחד למשה לדבר לפרעה, כ\"א „ובאת אתה וזקני ישראל אל מלך מצרים ואמרתם גו'\" (שמות ג, יח) [אלא ש„הזקנים נשמטו אחד אחד כו'\" (פרש\"י שם ה, א) ונשארו רק משה ואהרן], משא\"כ כאן שנצטווה „דבר אל פרעה גו'\" — מ\"מ, מכיון שגם בפ' שמות מפורש „ויאמרו\", שגם משה דיבר לפרעה (עם היותו „כבד פה גו'\"), הו\"ל להכתוב לפרש סדר הדיבור, כבפנים."],["16","16","ו, יג. וראה פרש\"י שם, כט־ל: „הוא הדיבור עצמו האמור למעלה .. היא אמירה שאמר למעלה כו'\"."]]],[1300161086,"ב) א גרעסערע תמי'17: וואס איז בכלל געווען די טענה פון משה רבינו דא „הן אני ערל שפתים\" — ער האט דאך שוין פריער געטענה'ט „כבד פה וכבד לשון אנכי\" און דערויף האט דער אויבערשטער אים געענטפערט „הוא יהי' לך לפה\" — היינט פארוואס איז ער איצט ווידער אמאל געקומען מיט (לכאורה) דער זעלבער טענה „הן אני ערל שפתים\"?\nולאידך, אויב עס איז דא צוגעקומען א חידוש אין דער צווייטער טענה, וואס דעריבער איז ניט מספיק די עצה אז אהרן „יהי' לך לפה\" — איז ווי ווערט זי פארענטפערט דערמיט „אהרן אחיך יהי' נביאך\", וואס איז לכאורה דער זעלבער ענטפער ווי אין פ' שמות?\nג. מפרשים18 ענטפערן (אויף דער צווייטער שאלה) אז פריער רעדט זיך נאר וועגן דעם דיבור „אל העם\" (ווי דער פסוק איז דארט מדגיש „ודבר הוא לך אל העם\"), און דא איז נתחדש געווארן די שליחות הדיבור אויך צו פרעה; און דערפאר האט משה דא ווידער געטענה'ט „אני ערל שפתים\", און דער אויבערשטער האט געענטפערט אז אויך ביי דער שליחות צו פרעה — „ואהרן אחיך יהי' נביאך\".\nאבער עס איז שווער אזוי צו זאגן — ווייל:\nא) באלד אין המשך פון די ערשטע רייד וואו דער אויבערשטער האט אנגע־זאגט אז משה זאל ווערן דער שליח ה', ווערן שוין דערמאנט ביידע שליחות'ן: „לך ואספת את זקני ישראל\nגו'\"19, און אויך „ואשלחך אל פרעה גו'\"20 — איז דערפון מובן, אז די תשובה פון אויבערשטן „הוא יהי' לך לפה\" באציט זיך אויף ביידע שליחות'ן21.\nב) ועיקר: מיט עטלעכע פסוקים ווייטער — נאכן דערציילן אז דער אויבערשטער האט מסכים געווען „הוא יהי' לך לפה\" — דערציילט דער פסוק22 אז דער אויבערשטער האט געזאגט צו משה בפירוש „(בלכתך לשוב מצרימה ראה כל המופתים גו' ועשיתם לפני פרעה גו') ואמרת אל פרעה גו'\", און מ'געפינט ניט אז משה זאל אויף דעם טענה'ן צום אויבערשטן „כבד פה גו'\" וכיו\"ב23:\nמוז מען זאגן, אז ער האט אנגע־נומען, אז (כאטש דא וועט (אויך) ער מוזן ריידן צו פרעה („ואמרת\")24 — ניט ווי ביים דיבור צו די בנ\"י וואו אהרן אליין האט צו זיי גערעדט — פונדעסט־וועגן) קען ער מיטנעמען אהרן25 „לפה\"26.",[["17","17","כמו שהקשה הרמב\"ן (ו, יב), אברבנאל ואלשיך כאן. ועוד."],["18","18","רמב\"ן שם (ושמות ד, טז). אברבנאל שם. ועוד. וראה אלשיך שם באו\"א."],["19","19","שמות ג, טז."],["20","20","שם, י. וראה פרש\"י שם: יועילו דבריך כו'. פרש\"י שם, יא: לדבר עם המלכים."],["21","21","ומש\"נ „ודבר הוא לך אל העם\" — כי עיקר השליחות אז הי' ל„העם\", כמבואר בהמשך הכתובים שם (וגם השליחות לפרעה אז הי' צ\"ל עם זקני ישראל כנ\"ל הערה 15), והשליחות של משה לפרעה הי' על לאח\"ז (ראה פרש\"י שבהערה 23)."],["22","22","שמות ד, כא־כב."],["23","23","ודוחק לומר שמכיון שציווי זה הי' על לאחר זמן (כפרש\"י שם: „מופתים שאני עתיד לשום בידך כו'\", עיי\"ש) לכן לא טען משה כו'."],["24","24","ועד\"ז כאן שנצטווה משה (ו, יא. כט) „דבר אל פרעה מלך מצרים\"."],["25","25","אבל אין להוכיח זה מ„ויאמרו אל פרעה\" (שמות ה, א), שהרי שם הי' הציווי „ואמרתם\", כנ\"ל הערה 15."],["26","26","ועפ\"ז יומתק לשון רש\"י עה\"פ „יהי' לך לפה\" — „למליץ לפי שאתה כבד פה\", דלכאורה: תיבות אלו מיותרות — אלא שבזה מוסיף בפי'"]]],[1300161087,"ד. נוסף על הנ\"ל זיינען דא כמה דיוקים אין לשון רש\"י, ומהם:\nא) ס'איז מובן אז משה האט גערעדט בצמצום ובקיצור (און אהרן האט אין דעם מאריך ומטעים געווען), אבער וואס איז דער הכרח צו זאגן אז משה האט גערעדט דוקא „פעם אחת\" און ניט מער?\nב) וואס איז דער דיוק הלשון „(פעם אחת) כל שליחות ושליחות כו'\" — לכאורה וואלט דא מער מתאים געווען דער לשון „כל ציווי וציווי\" — בהתאם צו לשון הכתוב „את כל אשר אצוך\"?\nג) „(כל שליחות ושליחות) כפי ששמעת מפי\", וואס איז לכאורה א יתור לשון — צי דען וועט משה זאגן פרעה'ן ניט ווי ער האט עס געהערט פון אויב־ערשטן?!\nד) וואס איז דער כפל הלשון „ימליצנו ויטעימנו\"?\nה. דער ביאור אין דעם וועט זיין פארשטאַנדיק בהקדים להסביר וואס משה האט אין זיין טענה דאָ משנה געווען פון זיין פריערדיקער טענה: אין פ' שמות5 האט ער געזאגט „כבד פה וכבד לשון אנכי\", און דא27 „אני ערל שפתים\", ובפרט אז לויט פרש\"י איז עס א שינוי ניט נאר אין לשון, נאר אויך אין תוכן הענין28:\n„כבד פה וכבד לשון אנכי\" איז רש\"י מפרש: „בכבידות אני מדבר\", ד.ה. אז ער קען ריידן, נאר דאס קומט אים אן „בכבידות\"; משא\"כ „ערל שפתים\" טייטשט רש\"י29 „אטום שפתים\": זיינע ליפן זיינען „פארשטאפט\" — ס'איז א שטערונג צום ריידן.\nאון דאס איז דער חידוש אין זיין צווייטער טענה: פריער האט ער גע־מיינט אז ער איז (בלויז) „כבד פה וכבד לשון\" — ער קען ריידן עכ\"פ „בכבידות\", און דעריבער האט דערצו מספיק געווען מיטצונעמען אהרן'ען, וואס וועט מאריך ו„מטעים\" זיין דאס וואס משה וועט זאגן בקיצור צו פרעה;\nאבער איצט איז ער געקומען צו דער הכרה אז „אני ערל שפתים\": זיין ריידן איז ניט נאר ניט „בקלות\" נאר אינ־גאנצן ניט מעגלעך, כאילו ער וואלט געווען „אטום\" — ובמילא האט דאך ניט קיין ארט זיין שליחות צו פרעה [ואדרבה: זיין קומען צו פרעה באופן אז ער וועט דארט שווייגן וועט ניט בלויז ניט ברענגען קיין תועלת, נאר פאר־קערט, גורם זיין א קלקול30: פרעה קען דאך אננעמען זיין שתיקה אלס הסכמה אז עס דארף זיין „תכבד העבודה\"31 וכיו\"ב].\nאויף דעם האט אים דער אויב־ערשטער געענטפערט „אתה תדבר גו'\": דאס איז ניט נאר א ציווי (דו זאלסט ריידן), נאר (צוזאמען דערמיט) א הבטחה — דו וועסט ריידן; אז כאטש ער איז אן „ערל שפתים\" וועט דער אויבערשטער אים געבן די יכולת צו ריידן32.",[["","","הכתוב, שאהרן נתמנה „לך לפה\" בכלל, וגם כאשר משה צריך לדבר, מ\"מ, אהרן „יהי' לך לפה — למליץ כו'\". אבל ראה לקמן הערה 32."],["27","27","ו, יב. ל."],["28","28","ראה ש\"ך עה\"ת עה\"פ ערל שפתים."],["29","29","ו, יב."],["30","30","ראה מדרש שכל טוב כאן. אברבנאל כאן."],["31","31","שמות ה, ט."],["32","32","וצע\"ק דלעיל (ו, יג) נאמר רק (כתשובה על הטענה „ואיך ישמעני פרעה ואני ערל שפתים\") „וידבר ה' אל משה ואל אהרן\" ופרש\"י: „לפי שאמר משה ואני ערל שפתים צירף לו הקב\"ה את אהרן להיות לו לפה ולמליץ\", דמזה משמע שעיקר"]]],[1300161088,"און דעריבער איז רש\"י מדייק „כל שליחות ושליחות וכו'\", צו מדגיש זיין אז דאס וואס משה האט געקענט ריידן איז טאקע געווען ניט מכח עצמו, נאר דערפאר וואס ער איז געגאנגען בשליחותו של הקב\"ה, און דאס האט אים געגעבן כח ויכולת צו ריידן; און דאס קומט בהמשך צו דעם וואס רש\"י איז מפרש מיט עטלעכע פסוקים פריער33: „אני ה', כדאי אני לשלחך ולקיים דברי שליחותי\" — אז ס'איז גענוג דאס „אני\" איז דער משלח בכדי צו קענען מקיים זיין „דברי שליחותי\". — עד\"ז בנוגע צום עצם איבערגעבן (זאגן) דברי השליחות.\nו. עפ\"ז איז אויך פארשטאַנדיק די אריכות אין לשון רש\"י — „פעם אחת כל שליחות ושליחות כפי ששמעת מפי\": די כוונה פון משה'ס גיין ריידן צו פרעה איז ניט געווען צו איינרייד־ן פרעה מיט הסברות וטעמים, נאר צו איבערגעבן די\nשליחות פון אויבערשטן; משה איז געווען דער שליח ה' וואס האט גע־רעדט צו פרעה במקום (ובכח) המשלח — הקב\"ה. ובמילא האט משה גע־דארפט איבערגעבן דעם גענויען לשון פון דעם משלח34 (אן הכפלה והסברה): ער האט עס געדארפט זאגן בלויז „פעם אחת\" (פונקט ווי דער אויבערשטער האט עס געזאגט „פעם אחת\"), און „כפי ששמעת מפי\" — מיט דעם זעלבן לשון בדיוק ווי ער האט עס געהערט פון אויבערשטן35.\nדערביי שטעלט זיך אבער די שאלה: דער דיבור פון אויבערשטן צו משה'ן איז דאך געווען בלשון הקודש36, ובמילא איז אויך דיבורו של משה צו פרעה געווען בלשון הקודש37 („כפי ששמעת מפי\") — איז ניט מובן: רש\"י האט שוין פריער מפרש געווען אין פ' ויחי38 אז פרעה האט ניט „מכיר\" געווען בלשון הקודש39, היינט ווי אזוי האט ער",[["","","התשובה הוא בזה ש„צירף לו הקב\"ה את אהרן\". ודוחק לתרץ דשם נאמר העניין רק בקיצור — כי סוף סוף אין חידוש בזה ש„צירף לו כו' אהרן\" (כנ\"ל בפנים). ואולי י\"ל (בדוחק עכ\"פ), שלכן מוסיף רש\"י „להיות לו לפה ולמליץ\", היינו שלא רק „יטעים\" דברי משה, כ\"א צריך להמליץ אותם• לפרעה (מכיון ש„אתה תדבר גו'\" הוא באופן שפרעה לא יבין, כדלקמן בפנים); ועד\"ז לשון הכתוב בפ' שמות „הוא יהי' לך לפה\" (וברש\"י שם: למליץ כו') שנאמר בדיבור אהרן אל העם, שאז לא דיבר משה אליהם כלל. ולהעיר מפרש\"י כאן ד\"ה יהי' נביאך. תרגום שמות ד, טז. ואכ\"מ."],["33","33","ו, כט. •) אבל קשה לפרש „ולמליץ\" כדלקמן בפנים (תרגום מלשון הקודש ללשון מצרי) — כי בפשטות נקט רש\"י לשון הכתוב דפ' שמות עם פירושו, כדלקמן בפנים ההערה."],["34","34","להעיר מס' בעלי ברית אברם (למהר\"א אזולאי — זקנו של החיד\"א) פרשתנו ו, יא־יב (בפרש\" הכתוב (שם, כט) „דבר אל פרעה מלך מצרים את כל אשר אני דובר אליך\"): „שלא תוסיף כלום מעצמך אבל תאמר הדברים כסדר שאסדר אני לך ובוודאי בסייעתא דשמיא\"."],["35","35","ויש להתאים המבואר בפנים גם עם הגירסא (דלעיל הערה 4) „לפי כו'\" — היינו, שהטעם שמשה צריך לדבר רק „פעם אחת כל שליחות כו'\" הוא „לפי ששמעת מפי\", שהוא השליח ששמע ישר מפי הקב\"ה (ע\"מ למסור דברי ה' לפרעה). וראה גו\"א בא יב, ג."],["36","36","להעיר מפרש\"י בראשית ב, כג."],["37","37","ראה גם לבוש האורה לפרש\"י פרשתנו ו, יב. וראה מכילתא דרשב\"י כאן: „אתה תדבר בלשון הקודש כמלאך ואהרן אחיך ידבר בלשון מצרי כו'\". צפע\"נ (להרגצובי) שמות ד, י."],["38","38","נ, ו. — וצ\"ע במ\"ש בלבוש הנ\"ל „ואם פרעה זה הוא פרעה הראשון כבר ידעת שלמד לשון הקודש מיוסף כמו שפרש\"י בפרשת ויחי\"."],["39","39","וגם להמ\"ד ד„ויקם מלך חדש — חדש ממש\" (פרש\"י שמות א, ח (בפי' הראשון)) — דוחק לומר שהי' מכיר בלשון הקודש, והרי פרעה לא למד"]]],[1300161089,"געקענט פארשטיין וואס משה האט געזאגט בלה\"ק?\nדעריבער איז רש\"י ממשיך: „ואהרן אחיך ימליצנו ויטעימנו וכו'\", וואס „ימליצנו\" האט אין זיך (אויך<sup data-n=\"40\">40</sup> דעם טייטש פון איבערזעצן פון איין שפראך אויף א צווייטער, ווי רש\"י האט שוין פריער מפרש געווען (אין פ' מקץ<sup data-n=\"41\">41</sup> אויפן פסוק „כי המליץ בינותם\": „כשהיו מדברים עמו הי' המליץ ביניהם היודע לשון עברי ולשון מצרי והי' מליץ דבריהם\".\nד.ה. אהרן וועט האבן א צווייענדיקן תפקיד: א) „ימליצנו\" — איבערזעצן פון דער שפראך פון דברי משה, ב) „ויטעימנו כו'\" — מסביר ומטעים זיין דעם תוכן פון זיינע רייד, באופן אז זיי זאלן נתקבל ווערן „באזני פרעה\".\nז. לכאורה איז נאך אלץ ניט גלאַ־טיק: וויבאלד אז פרעה האט סיי ווי ניט פארשטאנען וואס משה האט מיט אים גערעדט, טא וואס איז געווען די תועלת פון משה'ס דיבור? ועד כדי כך, אז אויף דעם איז געווען א ספעציעלע נתינת יכולת, כנ\"ל.\nאיז דער ביאור: דאס קומט בהמשך צו פרש\"י אין פריערדיקן פסוק: „נתתיך אלקים לפרעה — שופט ורודה לרדותו במכות ויסורין\". ד.ה. משה'ס ענין אין\nזיינע רייד צו פרעה, איז ניט געווען אים אויפצוקלערן מיט דברי טעם וכו' (דאס איז געווען אהרן'ס תפקיד — „ואהרן אחיך יהי' נביאך\", כנ\"ל), נאר אים צו „שופט\" זיין — אין אן אופן ווי „ורודה\" וואס דאס איז „לרדותו במכות ויסורין\".\nאון עד\"ז בענינינו: משה רבינו האט געדארפט זאגן צו פרעה „שלח את עמי\" מיט א שטרענגקייט און בייזערן זיך אויף אים, אז פונעם אופן הדיבור (און פונעם אויסדרוק פון משה'ס פנים בשעת מעשה וכו'<sup data-n=\"42\">42</sup> זאל פרעה פאר־שטיין אז דאס איז „קשות\" — בדוגמא פון מכות ויסורין.\nח. פון יינה של תורה אין דעם פרש\"י:\nאין דעם ענין פון „ראה נתתיך אלקים לפרעה\" („שופט ורודה לרדותו במכות ויסורין\"), איז חסידות43 מבאר: בשעת קליפות זיינען בעוצם תקפן (וואס דאס איז דאך מחמת יניקתן וכו'), האט אפילו44 א צדיק קיין כח ניט זיי אראפצוואורפן און צעברעכן (ע\"ד מחז\"ל45: „אם ראית רשע שהשעה משחקת לו אל תתגרה בו\"); דאס איז נאר ב„יכלתו ית' שהוא כל יכול\", אז אפילו א רשע וואס איז „כל גאה\", זאל זיין — „והשפילהו .. הכניעהו והדך רשעים תחתם\"46.\nאון דאס מיינט „ראה (ל' חידוש",[["","","לשון הקודש כל זמן היות יוסף משנה למלך (בערך שמונים שנה!). וראה כנ\"ל פרשתנו ו, יב. ומ\"ש בלבוש שם „ואם הוא פרעה אחר כבר ידעת מאמרם ז\"ל שאין ממנין מלך מצרים עד שיוכל לדבר בכל שבעים לשון\" — צ\"ע, שהרי מפורש ברש\"י ויחי שם „על לשון הקודש שאני מכיר עודף על ע' לשון כו'\". וראה גם רש\"י האזינו לב, ח."],["40","40","אבל אי\"ז פירושו בדוקא בכל מקום — ראה (בעניננו) פרש\"י שמות ד, טז (כנ\"ל הערה 32)."],["41","41","מב, כג."],["42","42","ראה פרש\"י בשלח טו, ח."],["43","43","אוה\"ת פרשתנו ע' רלא. ד\"ה ראה נתתיך תרל\"א, תרע\"ז, תשט\"ו. פלח הרמון פרשתנו ע' סד."],["44","44","באוה\"ת שם „אלא לצדיק\". ואולי צ\"ל „גם לצדיק\" (כבד\"ה ראה נתתיך תרל\"א: גם לצדיקים מופלגים. ועד\"ז בד\"ה זה דתרע\"ז)."],["45","45","ברכות ז, ב. מגילה ו, ב. אבל צ\"ע אם זוהי אותה הדרגא ממש בתוקף. וראה לקמן הערה 55."],["46","46","איוב מ, יא־יב. וראה גם יהל אור ע' שסו."]]],[1300161090,"ופליאה) נתתיך אלקים לפרעה\": הגם אז פרעה איז נאך געווען בתקפו, ביז אפילו „לא הי' עבד יכול לברוח ממצרים\"47, האט דער אויבערשטער געגעבן משה'ן „ממשלה זרוע כא־ל\"48 ממש על פרעה\"49, ביז צו רודה זיין אים „במכות ויסורין\"50.\nאון דער כח איז געגעבן געווארן דוקא צו משה'ן51: וואורום זייענדיק דער נשיא הדור, דער „אנכי עומד בין ה' וביניכם גו' להגיד לכם את דבר ה'\"52 — א ממוצע דורך וועמען עס ווערט נמשך „דבר ה' ממש\"53 — דעריבער ווערט דורך אים נתגלה כוחו ויכלתו ית' „לרדותו במכות ויסורין\". [און דערמיט איז מובן פארוואס ר' שמעון בן יוחי האלט אז „מותר להתגרות ברשעים\"54 (אויך ווען „השעה משחקת להם\"<sup data-n=\"55\">55</sup> —\nוויל רשב\"י איז א ניצוץ פון משה רבינו, כידוע56, וואס האט דעם כח צו „מכניע\" זיין די רשעים — אויך ווען זיי זיינען בתקפם57].\nאון דאס איז דער טעם פנימי פאר־וואס משה רבינו האט געמוזט ריידן צו פרעה'ן (א) און ס'איז ניט געווען גענוג דיבורו של אהרן — (ב) כאטש אז דער דיבור איז געווען אין א שפראך וואס פרעה האט ניט פארשטאנען —\nוויל דא האט זיך געמוזט אויפטאן די שבירה פון פרעה'ן ווען ער איז נאך בתקפו, און דעריבער (א) איז עס נאר בכחו של משה; (ב) עס איז ניט אן ענין פון בירור, נאר שבירה58 (לרדותו כו'), און ס'איז דערפאר ניט נוגע אז פרעה זאל פארשטיין דעם דיבור.\nט. עפ\"י הנ\"ל איז אויך מובן דאס וואס רש\"י זאגט אז משה האט געמוזט איבערגעבן דברי הקב\"ה „כפי ששמעת",[["47","47","פרש\"י יתרו יח, ט. מכילתא שם, יא."],["48","48","איוב שם, ט („זרוע כא־ל\")."],["49","49","ל' אוה\"ת שם. ד\"ה ראה נתתיך תרל\"א."],["50","50","וראה בארוכה תו\"ח פרשתנו בפסוק הוא אהרן ומשה (קיט, ב ואילך) דפרעה הו\"ע קשה עורף דקליפה, תוקף הישות והגסות, והכנעתו היא רק ע\"י משה כו', עיי\"ש. וראה גם אוה\"ת פרשתנו ע' רכט־רל."],["51","51","ראה אוה\"ת שצויין בהערה 43 „לפי שמשה הי' משם מ\"ה דא\"ק .. שהוא למעלה מהתהוו ותיקון כו'\". ובהדרושים ד\"ה ראה נתתיך מקשר זה עם הא שמשה הוא נשמה דאצילות. וראה גם תו\"ח שם (קכ, ב ואילך). אוה\"ת שבהערה הקודמת."],["52","52","ואתחנן ה, ה."],["53","53","ראה בארוכה סד\"ה פנים בפנים תרנ\"ט (ע' קצד־ה). וראה תו\"ח פרשתנו קטז, א ואילך. ועוד."],["54","54","ברכות ומגילה שם."],["55","55","ראה מקומות שצויינו בהערה 43 (שגם „כל גאה והשפילהו גו'\"). וצע\"ק מסוגיית הגמרא שם, דלתירוץ א' (וראה טו\"א מגילה שם. ריי\"ף ועץ יוסף לע\"י ברכות שם) גם רשב\"י מודה דשעה משחקת לו שאני. ובכל אופן צ\"ע מהמבואר בסוגיא שם שאין פלוגתא בין רשב\"י והמ\"ד „אל תתגרה בו\" (כמו שמתרץ בגמרא בכמה אופנים. ולתי' א' דלכר\"ע כל צ\"ג מותר להתגרות כו', לאו דוקא רשב\"י (משה) וכיו\"ב). וראה חדושי גאונים לע\"י ברכות שם (בשם הצל\"ח)•. ואולי הכוונה, דזה שרשב\"י אמר באופן סתמי „מותר להתגרות כו'\" (מבלי לחלק כר), הוא מכיון שמצד דרגתו הוא מותר להתגרות בכל אופן. ועצ\"ע."],["56","56","סידור שער הל\"ג בעומר בסופו (בשם כתבי האריז\"ל וכו')."],["57","57","באוה\"ת (שבהערה 43): „ואפשר רשב\"י דפ\"ק דברכות הי' ג\"כ מבחי' זו כו'\". אבל במאמרים ד\"ה ראה נתתיך הנ\"ל מבואר זה בפשטות, ככפנים."],["58","58","ראה תו\"ח שם (קכא, סע\"א): „אתה תדבר כו' פי' תדבר לשון הכנעה כו' להכניעם ולהשפילם בתכלית כו'\". •) שם מבואר „שאין הכוונה בסוגיות הללו להקשות מרשב\"י ור\"ד על ר\"י דאולי פליגי ומ\"מ שמותר להתגרות ומ\"מ שאסור להתגרות כו' כל הקושיות של הגמ' כו' הוא למידמי קראי אהדדי\". אבל לכאורה אין לתרץ בהמאמרים עפ\"ז, שהרי מסיק שם שהתי' האחרון בגמ' (ברכות) שעה שמשחקת שאני הוא לשיטת רשב\"י."]]],[1300161091,"מפי\" דוקא: אט דעם כח, צו קענען צע־ברעכן קליפות ווען זיי זיינען נאך בתקפן, האט משה רבינו געהאט מצד דעם וואס ער איז געווען דער שליח ה', דורך וועמען עס איז נתגלה געווארן כחו ית' („זרוע כא־ל\"); און דעריבער איז דער דיבור געווען אין אן אופן פון „אתה תדבר .. כפי ששמעת מפי\": ע\"ד „שכינה מדברת מתוך גרונו של משה\"59.\nדערמיט קען מען אויך מבאר זיין וואס דער סדר פון „אתה תדבר, פעם אחת כל שליחות ושליחות כפי ששמעת מפי כו'\" האט זיך אנגעהויבן נאך דעם ווי משה האט גע־טענה'ט „אני ערל שפתים\":\nס'איז מבואר אין חסידות60, אז דאס וואס משה איז געווען „כבד פה וכבד לשון\" האט זיך עס גענומען מצד זיין ביטול צו אלקות — אז צוליב זיין גודל הביטול האט ער ניט געקענט משפיע זיין, ע\"ד ווי „איידי דטריד למבלע לא פליט\"61.\nדערפון איז מובן, אז אויך דער ענין פון „ערל שפתים\" וויזט אויפן גודל הביטול פון משה רבינו: און נאך אויף א גרעסערן ביטול ווי „כבד פה וכבד לשון\" — וואָרום „כבד פה וכבד לשון\" מיינט אז עס איז נאך געבליבן דיבור (השפעה), נאר ס'איז „בכבידות\", נאר ניט ביטול לגמרי; „ערל שפתים\" אבער ווייזט אויף ביטול בתכלית, וואס דער־פאר קען ער אינגאנצן ניט ריידן.\nאון דעריבער איז דוקא אט דער ביטול פון „ערל שפתים\" געווען די אתדל\"ת, הכנה והקדמה צו „ראה נתתיך אלקים לפרעה גו'\" — דורכן ביטול אין אן אופן פון „בלי שום הרגש כלל\"62 קען דערנאך זיין („ע\"ד פון „שכינה מדברת מתוך גרונו של משה\") — „דבר ה' ממש\"63 — וואס פאדערט זיך צו דער שבירה פון פרעה'ן.\nיו\"ד. לכאורה קען מען נאך אלץ פרעגן: ווי קומט עס, וואס דוקא פרעה האט געהערט די שליחות ה' (אויך) פון משה'ן אליין, און בנ\"י האבן עס געהערט בלויז פון אהרן'ען („ודבר הוא לך אל העם\")?\nאמת טאקע, אז בנ\"י האבן ניט געדארפט אנקומען צו דעם, משא\"כ די שבירה פון פרעה (קליפה בתקפה) האט געמוזט זיין נאר דורך כחו של משה64\n[און עד\"ז איז עס אויך אין פשטות הענין: אידן זיינען מאמינים בני מאמינים65, דעריבער איז פאר זיי גענוג אז אהרן גיט זיי איבער, אלס שלוחו של משה, וואס האט געהערט פון אויבערשטן — איז „ויאמן העם גו'\"66; ביי פרעה אבער וואלט דאס ניט מספיק",[["59","59","נסמן בלקו\"ש ח\"ד ע' 1087. וראה ד\"ה פנים בפנים שם. ובכ\"מ."],["60","60","תו\"א כג, סע\"א. לקו\"ת עקב יד, סע\"ב. שם, ד ואילך. סידור קי, ב (ועוד). אוה\"ת פרשתנו ע' רו. ביאוה\"ז להצ\"צ ע' תמז. ועוד."],["61","61","כן הובא בכ\"מ בדא\"ח (ראה בעניננו סידור וביאוה\"ז שם). וראה חולין קח, ב."],["62","62","ד\"ה פנים בפנים שם. וראה תו\"ח שם (קכ, ריש ע\"ב) דלפי שמשה הי' „בחי' הביטול במציאות ממש בהעדר הרגשת עצמו מכל וכל כו'\" הי' יכול „להכניע .. קליפה תקיפה דפרעה וכו'\", עיי\"ש."],["63","63","להעיר ממדרש הגדול כאן: „ובשביל שאמר אני ערל שפתים זכה לבסוף אנכי עומד בין ה' וביניכם\"."],["64","64","כמבואר בארוכה בתו\"ח שם. אוה\"ת שבהערה 50. אבל להעיר מדיבור משה אל בני ריש פרשתנו (ו, ט): פרש\"י בא יב, ג (ושקו\"ט במפרשי רש\"י שם). ואכ\"מ."],["65","65","שבת צז, א."],["66","66","שמות ד, לא."]]],[1300161092,"געווען און דעריבער האט משה אליין געמוזט ריידן];\nפונדעסטוועגן איז עס ניט גאר גלאטיק: פארוואס זאל ביי אידן פעלן אט דער ענין נעלה פון דיבורו של משה?\nדער ביאור אין דעם: ווען אהרן גיט איבער דברי משה צו די אידן איז עס דאן ביי אים נאר בדרך „מעבר\"67, די אידן נעמען דעם דיבור של משה אן קיין שינוי וירידה (במעלתו) מצד דעם ממוצע; ע\"ד ווי „משה קיבל תורה מסיני ומסרה ליהושע ויהושע לזקנים וכו'\"68, וואס הגם אז עס איז דורכגעגאנגען כו\"כ ממוצעים, פונדעסטוועגן איז עס אלץ די „תורה מסיני\", כמחז\"ל69 כל מה שתלמיד ותיק עתיד לחדש ניתן למשה מסיני.\nדאקעגן ביי פרעה, אויב דיבורו של משה וואלט צו אים געקומען (נאר) דורך אהרן'ען, וואלט עס געמוזט זיין אין אן אופן פון התלבשות (ושינויים) וכו', ובמילא וואלט אינעם דיבור געפעלט פון כחו של משה וואס פאדערט זיך לשבירת פרעה כנ\"ל.\nדערמיט איז אויך מובן דער שינוי הלשון אין די פסוקים — ביי בנ\"י שטייט אז אהרן „יהי' לך לפה\", און ביי פרעה — „ואהרן אחיך יהי' נביאך\": ביי אידן איז אהרן געווען פיו של משה („לך לפה\")70, אהרן'ס דיבור איז געווען אין\nדער זעלבער דרגא ווי ווען ער קומט פון פה של משה — בדרך מעבר: משא\"כ ביי פרעה איז אהרן בלויז געווען „נביאך\", וואס דאס מיינט (כפרש\"י) „מתורגמנך\" — און ווען א דבר השפעה ווערט איבערגעגעבן דורך א מתורגמן קומט זי אראפ בדרך ירידה ושינוי לפ\"ע המקבלים, כמבואר בכ\"מ71.\nיא. די הוראה פון דעם אין עבודה פרטית פון כאו\"א:\nס'איז דא אמאל אז די נפש האלקית געפינט זיך אין גלות אין נפש הבהמית, ביז אין אן אופן וואס „השעה משחקת לה\" — די קליפה איז אין א מצב פון „גסות .. שמגבי' עצמה על אור קדושת נפש האלקית כו'\"72.\nאיז די עצה אויף דעם — „נתתיך אלקים .. לרדותו במכות ויסורין\": עס דארף זיין דער „ירגיז אדם יצ\"ט על יצה\"ר כו'\"73, „ירעים עלי' בקול רעש ורגז להשפילה .. לומר לו אתה רע וכו'\"74, און דאס גופא ברעכט די גסות הקליפה פון נפש הבהמית, כמבואר בארוכה אין תניא75.\nוי\"ל בדא\"פ עכ\"פ, אז דעם כח אויף דעם האט מען פון משה רבינו, וואס אים האט דער אויבערשטער געזאגט „ראה נתתיך אלקים לפרעה, שופט ורודה לרדותו במכות ויסורין\": און דעריבער איז אט דער כח פאראן ביי יעדן אידן,",[["67","67","ראה חילוק מעבר והתלבשות — קו\"א ד\"ה להבין מ\"ש בפע\"ח (קנח, א). לקו\"ת מסעי פט, ג. ד\"ה פנים בפנים שם. ובכ\"מ."],["68","68","אבות בתחילתה."],["69","69","נסמן בלקו\"ש ח\"ד ע' 1088. ועוד."],["70","70","בתו\"ח שם (קיט, ב) מוכיח מזה ד„לגבי זקני ישראל יהי' אהרן עיקר המדבר\" (משא\"כ „לגבי פרעה .. יהי' נביאך .. ולא שיהי' לפה ממש\") — אבל מובן שיש בזה גם הפירוש שהוא פיו דמשה. וכמובן מתו\"ח שם קטז, ב ואילך (עיי\"ש)."],["71","71","ד\"ה פנים בפנים שם. המשך תרס\"ו ע' קב. ובכ\"מ."],["72","72","תניא פכ\"ט (לו, א)."],["73","73","ברכות ה, א."],["74","74","ל' התניא שם (לז, א)."],["75","75","שם (לז, א ואילך). וראה ג\"כ תניא פל\"א (לט, ב ואילך)."]]],[1300161093,"וואורום „כל נפש ונפש מבית ישראל יש בה מבחי' משרע\"ה\"76.\nאון על אחת כמה וכמה אז אזוי איז עס ביי אידן אלס כלל און באם נשיא הכלל, וואס הנשיא הוא הכל77: כשם ווי משה רבינו אין זיין צייט האט געהאט דעם כח צו רודה זיין פרעה „במכות ויסורין\" אפילו ווען „השעה משחקת לו\", אזוי איז עס בכל דור ודור, אז דער נשיא הדור, דער „אתפשטותא דמשה בכל דרא ודרא\"78, האט דעם כח דורכצובראכן אלע העלמות והסתרים וואס זיינען דא אויף קדושה, אויך ווען זיי זיינען בתקפם.\nיב. דאס איז אויך דער ענטפער צו די וואס טענה'ן: וויבאלד אז מ'געפינט זיך אין דעם חושך כפול ומכופל פון דרא דעקבתא דמשיחא מיט אזויפיל גרויסע העלמות והסתרים וכו' — היינט ווי קען מען דורכפירן די תביעה פון רבותינו נשיאינו צו מפיץ זיין דעם לימוד תורת החסידות און די הליכה בדרכי החסידות בכל מקום ומקום, ובפרט אין די ערטער וואס זייער מצב איז אזוי נידעריק, אז זיי זיינען גאר מונע ומעכב וכו'?\nדארף מען ווייסן, אז אתפשטותא דמשה בכל דרא ודרא, אויך אין דרא דעקבתא דמשיחא\n— ואדרבה: וויבאלד די נשמות פון היינטיקן דור, דרא דעקבתא דמשיחא, זיינען בבחי' „גלגול\" פון די נשמות פונעם דור המדבר כידוע79, איז זיכער,\nאז די זעלבע ענינים וואס זיינען געווען ביים דור המדבר זיינען פאראן אויך איצט —\nאון דורכדעם וואס מ'פארבינד זיך מיטן נשיא הדור, כ\"ק מו\"ח אדמו\"ר, האט מען ניט וואס צו נתפעל ווערן פון די העלמות והסתרים, וואורום מ'האט דעם כח פון משה רבינו זיי צו צעברעכן — „לרדותו במכות ויסורין\".\n— אוודאי דארף מען גיין בדרכי נועם ובדרכי שלום, אזוי איז דער רצון פון כ\"ק מו\"ח אדמו\"ר, און ווי ער האט געבעטן ביי זיין פאטער כ\"ק אדמו\"ר מוהרש\"ב נ\"ע אז זיין נשיאות זאל זיין בחסד וברחמים80:\nאבער וויסן דארף מען, אז בשעת מען איז צוגעבונדן צום נשיא הדור — וואס די התקשרות איז דורך לימוד תורתו, היטן זיינע תקנות81 והליכה באורחותיו נס\"ו82 — דעמאלט האט מען ניט וואס צו נתפעל ווערן פון קיינע העלמות והסתרים,\nאון אזוי ווי דעמאלט האט משה רבינו צעבראכן קליפת פרעה און ארויס־געפירט אלע אידן פון גלות מצרים „ביד רמה\"83, אזוי וועט זיין אויך איצטער, אז ניט קוקנדיק אויף קושי הגלות, וועט דער משה שבדור84 ארויסנעמען אונז אלעמען פונעם גלות צו דער גאולה האמיתית והשלימה „ביד רמה\" ובקרוב ממש.\n(משיחות ש\"פ וארא תשכ\"ט, תשט\"ו)",[["76","76","תניא רפמ\"ב. וראה ג\"כ ביאור לאגה\"ק סי' זך בסופו."],["77","77","פרש\"י חוקת כא, כא. וראה רמב\"ם הל' מלכים פ\"ג ה\"ו."],["78","78","תקו\"ז תס\"ט (קיד, א). וראה ב\"ר פנ\"ו, ז."],["79","79","לקו\"ת וס' הליקוטים להאריז\"ל שמות ג, ד. שער הגלגולים הקדמה כג."],["80","80","לקו\"ש ח\"ב ע' 502."],["81","81","היום יום ע' סה."],["82","82","ראה אגה\"ק סי' זך וביאורו."],["83","83","בשלח יד, ח."],["84","84","דמשה גואל ראשון הוא גואל אחרון — נסמן ונתבאר בלקו\"ש חי\"א ע' 8 ואילך."]]],[1300161094,"<h3>וארא ד</h3>\nא. פון פסוק<sup data-n=\"1\">1</sup> „ויט אהרן את ידו גו' ותעל הצפרדע ותכס את ארץ מצרים\" איז רש\"י מעתיק די ווערטער „ותעל הצפרדע\", און איז מפרש: „צפרדע אחת היתה והיו מכין אותה והיא מתזת נחילים נחילים וכו'\".\nאין פשטות איז דא רש\"י אויסן צו באַ־וואַרענען, פארוואָס עס שטייט דאָ „ותעל הצפרדע\" — לשון יחיד, בשעת ס'איז געווען אַ ריבוי צפרדעים — דער־פאַר איז רש\"י מפרש, אַז לכתחילה איז טאַקע געווען בלויז איין צפרדע, נאַר דורכדעם וואָס „היו מכין אותה\" האָט זי פון זיך אַרויסגעגעבן „נחילים נחילים\".\nאויך די גמרא<sup data-n=\"2\">2</sup> (און שמו\"ר<sup data-n=\"3\">3</sup> שטעלט זיך אויף דעם וואָס שטייט „ותעל הצפרדע\" בלשון יחיד, און ברענגט דערויף צוויי דיעות: „ר' עקיבא אומר צפרדע אחת היתה (והיא השריצה) ומלאה כל ארץ מצרים. א\"ל ראב\"ע כו' צפרדע אחת היתה שרקה להם והם באו\".\nדאַרף מען פאַרשטיין: פירוש רש\"י איז דאָך, כידוע, מיוסד לפי פשוטו של מקרא, און ווי באַלד אַז קוב\"ה לא עביד ניסא למגנא<sup data-n=\"4\">4</sup> איז אַ כלל וואָס איז מסתבר אויך אין דרך הפשט (ווי גע־רעדט אַמאָל בארוכה<sup data-n=\"5\">5</sup>, איז במילא\nדער שכל מחייב, אַז אויך ביי אַ נס וואָס האָט פּאַסירט, איז אויף וויפל מ'קען זאָגן און מפרש זיין אַז דער נס האָט אַן אַנ־האַלט אין דרכי הטבע, דאַרף מען ניט אננעמען אַז ס'איז אין אַן אופן וואָס דער נס ברעכט לגמרי די חוקי הטבע, ווייל די הוספה איז דאָך „למגנא\"<sup data-n=\"6\">6</sup> —\nהיינט פארוואָס ברענגט רש\"י דעם פירוש (פון מדרש<sup data-n=\"7\">7</sup> אַז „היו מכין אותה והיא מתזת נחילים נחילים\", וואָס אַזאַ נס (אַז דורך הכאה זאָלן פון איר אַרוס־קומען ניי־באַשאַפענע „נחילים נחילים\") האָט לגמרי ניט קיין אנהאַלט אין דרכי הטבע, בעת ער האָט געקענט מפרש זיין לויט (גמ' און שמו\"ר ווי) דעת ראב\"ע אַז די צפרדע „שרקה להם והם באו\" (ווי רש\"י טייטשט עס אַף דאָרט אַז „שמעו קולה כל הצפרדעים שבעולם והם באו\"), וואָס דערין איז ניט געווען דער נס מופלא פון אַ בריאה חדשה<sup data-n=\"8\">8</sup>; אָדער עכ\"פ ווי דעת ר\"ע אַז „השריצה9 ומלאה כל ארץ מצרים\" — וואָס הגם אויך דאָס האָט געמוזט זיין אַ בריאה באופן נסי —",[["1","1","פרשתנו ח, ב."],["2","2","סנהדרין סז, סע\"ב."],["3","3","פרשתנו פ\"י, ד."],["4","4","ראה דרשות הר\"ן דרוש ח — נעתק בלקו\"ש ח\"ג ע' 966, עיי\"ש."],["5","5","ראה לקו\"ש ח\"ה ע' 124 ואילך. ח\"י ע' 49. ועוד."],["6","6","להעיר מפרש\"י בפרשתנו (ט, לב): אפילות . . פלאי פלאות. ושם (ט, כד): נס בתוך נס."],["7","7","ע\"ד ל' רש\"י נמצא בתנחומא כאן (יד). תדבא\"ר פ\"ז. אבל שם: א) שהמצרים היו מכין כו'. וראה לקמן הערה 27. ב) לא נאמר הלשון „נחילים נחילים\" שברש\"י. וראה הלשון במדרש אגדה (באבער) כאן."],["8","8","אף שע\"פ פירש\"י גם בזה הי' נס נוסף ד„שמעו קולה כל הצפרדעים שבעולם והם באו\"."],["9","9","בגמ' לא גריס תיבת „השריצה\" בדברי רעי\"ק (כ\"א בדעת ר\"א לפנ\"ז). אבל מובן שזוהי כוונת רע\"ק, כל' הש\"ס „כתנאי רע\"ק אומר כו'\", וכמפורש בשמו\"ר שם, יל\"ש פרשתנו (רמז קפג) ומדרש הגדול כאן. ובדק\"ס לסנה' הובאה גירסא כזו בגמ'. וראה הערה הבאה."]]],[1300161095,"איז עס אבער פארט געווען געבונדן מיט אַ גדר פון טבע ההולדה — „השרי־צה\"<sup data-n=\"10\">10</sup> (ווי רש\"י טייטשט<sup data-n=\"11\">11</sup>: „ממעי' ויצאו ולדות\")?\nב. דערנאָך איז רש\"י ממשיך „זהו מדרשו. ופשוטו יש לומר שרוץ הצפר־דעים קורא ל' יחידות. וכן ותהי הכנם12 הרחישה (און כדי דער בן חמש למקרא זאָל עס קלערער פארשטיין, פאַר־טייטשט עס רש\"י אויך בלע\"ז<sup data-n=\"13\">13</sup> גדו־ליר\"א14 בלע\"ז ואף ותעל הצפרדע גרינולי'ר\"א בלע\"ז\".\nדאַרף מען פאַרשטיין: לכל לראש איז דאָך רש\"י אויסן צו מפרש זיין פשוטו של מקרא, און נאָר דאַן ווען דער פשט הכתוב איז ניט גלאַטיק ברענגט רש\"י אַן „אגדה המיישבת דברי המקרא\"15 — איז ווי קומט עס וואָס דאָ איז רש\"י מקדים עס פירוש וואָס (ער אַלײן שרײבט אַז עס) איז „מדרשו\" פאַר דעם פירוש וואָס איז (ווי רש\"י שרײבט) „פשוטו\"?\nאויך איז ניט מובן:\nבשלמא דאָס וואָס רש\"י דאַרף אַנ־קומען צו אַ ראי' אַז „הצפרדע\" מיינט „שרוץ הצפרדעים\" (און דערפאַר שטייט עס „בל' יחידות\"), איז מובן בפשטות: ס'איז שווער צו זאָגן אַז דער נאָמען „צפרדע\" זאָל מיינען די זאַך פון שרוץ\n(הצפרדעים) — וואָס שטייט ניט אין פסוק און ער איז אַ באַגריף וואָס לייגט זיך אויף אַלערליי שרצים און ניט דוקא אויפן מין צפרדע: דערפאַר ברענגט רש\"י אַ ראי' פון „ותהי הכנם\", וואָס דער טייטש פון „כנם\" איז „רחישה\" — כאָטש אויך „רחישה\" האָט ניט קיין שייכות דוקא צום מין פון „כנים\",\nאון אַנדערע ווערטער: וואָלט שירוץ הצפרדעים געווען אַנדערש ווי באַ אַנ־דערע שרצים וכו', איז דאַמאָלס גלאַ־טיקער צו זאָגן אַז „צפרדע\" (פונקט ווי עס מיינט דעם שרץ — אויסגעטיילט פון אלע אַנדערע שרצים: אין אויסזען, אויפפירונג א.ז.וו., אזוי) מיינט עס אויך זיין אויסגעטיילקייט — זיין ספעציעלען שירוץ,\nחאַטש אינגאַנצן גלאַטיק איז עס ניט, ווייל עס האָט געדאַרפט זיין אַ שינוי אין וואָרט (אַנדערש מנוקד וכיו\"ב), ע\"ד ווי באַ כינים — שטייט כנם — כדלקמן.\nוויבאַלד אבער אַז דער פסוק זאָגט דעמזעלבן לשון שירוץ סיי באַ צפרדעים סיי ביי אַלע „שרץ נפש חי'\"*15 — איז לכאורה שווער צו זאָגן אַז צפרדע מיינט אַזאַך וואָס איז דאָס זעלבע באַ אַלע שרץ נפש חי' — דערפאַר איז די ראי' — „ותהי הכנם\", כנ\"ל.\nס'איז אבער ניט מובן, פארוואָס איז באַ רש\"י פשוט אַז „ותהי הכנם\" מיינט „הרחישה\" (וואָס דערפאַר באַנוגנט זיך דאַרט רש\"י מיטן טייטש פון „רחישה\" און ברענגט ניט קיין ראי' אויף דעם, און ברענגט ניט קיין צווייטן פירוש) — און בײ „ותעל הצפרדע\" זאָגט ער (און נאָר אַלס צווייטן פירוש) אַז „יש לומר שרוץ הצפרדעים קורא ל' יחידות\"?",[["10","10","בתנחומא ותדבא\"ר שם, שדעת רע\"ק ש„היו כו' מכין אותה ומתזת צפרדעים הרבה\" — אבל בש\"ס (ובמקומות שבהערה הקודמת) הוא כבפנים."],["11","11","וראה זהר פרשתנו (כט, ב): חדא הות ואולידת כו'."],["12","12","שם פסוק יג."],["13","13","בדפוס ראשון ושני דרש\"י (וברש\"י כת\"י) ליתא סיום זה."],["14","14","בכמה דפוסים: פדולירי\"א. וכ\"ה בפרש\"י לקמן פסוק יג."],["15","15","ל' רש\"י בראשית ג, ח. 15•) פרשתנו ז, כח. בראשית א, כ (ובפרש\"י שם)."]]],[1300161096,"ג. מפרשים16 זיינען מסביר, אַז רש\"י\"ס הכרח צו טייטשן „ותהי הכנם — הרחישה\", איז פון דעם וואָס „כנם\" (נו\"ן קמוצה), וואָס איז ניט ל' רבים („כנים\") און ניט ל' יחיד (— „כנה\"). און דעריבער מוז מען זאָגן אַז דאָ מיינט עס ניט דעם שם פון כנים, נאָר — דער באַדייט פון „רחישת הכנים\".\nאון לויט דעם איז מובן, אַז דערפאַר איז דאָס אויך ניט קיין פולע ראי' אַז אויך „צפרדע\" מיינט „שרוץ הצפרד־עים\", ווייבאַלד אַז פון דעם לשון „(ותעל ה)צפרדע\" איז ניטאָ קיין הוכחה אַז דאָס מיינט עפעס אַנדערש ווי דער נאָמען פון צפרדע בלשון יחיד17:\nאון דאָס איז אויך דער דיוק אין רש\"י: וכן ותהי הכנם כו' ואף ותעל הצפרדע — און אויף וואָס ער איז מוסיף „גרינו־לירא בלע\"ז\" — חאָטש ער בריינגט ניט קיין בלע\"ז אויף „צפרדעים\" וואָס שטייט פריער וכמה פעמים — איז דאָך פאַר־שטאַנדיק אַז פי' צפרדעים איז באַ־וואוסט, איז נאָך דעם ווי רש\"י זאָגט „שירוץ הצפרדעים\" (און פי' שירוץ וויים מען פון פריער — ושרץ היאור צפרדעים) — איז וואָס טוט אויף דער בלע\"ז?\nנאָר די באַוואַרעניש אין דעם: „צפרדע\" בלע\"ז איז „גרינולי'\"\nוואָס דאָס וויים דאָך דער בן חמש, ווייל דאָס איז דאָך זיין לע\"ז (פראַנ־צויזיש — אויך בימינו)\nאון „שירוץ הצפרדעים\" בלע\"ז — ווערט א שינוי „גרינולירא\" — וע\"ד ווי דער שינוי „כנם\" אַנשטאַט „כנים\" (ועד\"ז אין זיין בלע\"ז) — פונדעסט־וועגן „ואף ותעל הצפרדע\" — חאָטש עס איז ניטאָ קיין שינוי, איז דער פי' „גרינולירא בלע\"ז\" (ניט גרינולי).\nאבער וויבאַלד אַז די תורה רופט פאַרט אַן די רחישת הכנים מיטן נאָמען „כנם\" — ניט קוקנדיק וואָס רחישה האָט צו טאָן ניט בלויז מיטן מין פון כנים (וואָס דאָס איז דער עיקר שווערקייט אינעם אפטייטש פון „כנם\" (און פון „צפרדע\") אַלס „רחישה\" (און „שרוץ\")) — איז דערפאַר „יש לומר\" אַז אויך „צפרדע\" ביי אונז מיינט „שרוץ הצפרדעים\".\n— לויט דעם וואָלט מען לכאור' אויך געקענט מסביר זיין17, פארוואָס רש\"י איז מקדים דעם פירוש המדרש פאַר דעם פירוש ע\"פ „פשוטו\" — ווייל דער „פשוטו\" בנדו\"ד איז ניט אַזוי גלאַטיק און מוכרח, כנ\"ל.\nד. אבער אין אמת'ן קען מען ניט זאָגן, אַז (נאָר) צוליב דעם איז רש\"י מקדים דעם פירוש המדרש פאַר דעם פירוש „שרוץ הצפרדעים\" — ובהקדים:\nאויף צו מדגיש זיין אַז אַ פירוש איז אויסגעהאַלטן לויטן דרך הפשט (און ניט ע\"פ דרש) באַנוצט זיך רש\"י מיט די ביטויים: א) ווי אין אונזער פאַל — „ופשוטו\": ב) „ופשוטו של מקרא\"18. דער חילוק צווישן זיי איז מובן אין פשטות: דער אויסדרוק „ופשוטו של מקרא\" מיינט, אַז דער פירוש איז לויטן פשט פון דעם „מקרא\" — פון דעם",[["16","16","ס' זכרון (לר\"א בקראט הלוי) כאן (ושם: „והוא שם לשריצת הכנים\". וראה גם מלבי\"ם פסוק יג. אבל בדקדוקי רש\"י (באר רחובות) שם מפרש באו\"א. וראה גם ראב\"ע שם)."],["17","17","ראה גם משכיל לדוד כאן."],["18","18","ראה לדוגמא: בראשית א, כז. ג, ח. ד, ח („ישובו של מקרא\"). נח ז, טז. לך יב, ה. יב, יא."]]],[1300161097,"כלליות'דיקן תוכן הכתוב; דאָקעגן דער לשון „ופשוטו\" (אָן דעם סיום „של מקרא\") מיינט, אַז דאָס איז דער פירוש הפשוט (בלויז) פון דעם וואָרט (אָדער ענין) אויף וועלכן רש\"י שטעלט זיך (הגם עס קען זיין אַז ס'איז ניט מתאים צו פשטות פון כלליות'דיקן אינהאַלט).\nדאַרף לפי זה אויסקומען בנדו\"ד: אויב מ'זאָל אננעמען, אַז דאָס וואָס רש\"י איז מקדים דעם פירוש המדרש פאַרן פירוש ע\"פ „פשוטו\" איז עס דערפאַר ווייל דער טייטש „שרוץ הצפרדעים\" ליגט ניט אין וואָרט „צפרדע\" (משא\"כ לויטן פי' המדרש, וואָס דער טייטש פון „צפרדע\" איז כפשוטו — איין צפרדע) — האָט דאָך רש\"י געדאַרפט זאָגן ניט „ופשוטו\" (סתם — פון וואָרט) . . שרוץ הצפרדעים כו'\", נאָר „ופשוטו של מקרא כו'\": ד.ה. וויבאַלד ס'איז ניטאָ קיין רמז, לכאורה, אין המשך הפסוק אויפן נס ש„היו מכין אותה והיא מתזת נחילים נחילים\", דערפאַר איז אַט דער (ערשטער) פירוש לויט „מדרשו\" (אַ נס וואָס ווערט אַרויסגעלערנט לויטן דרך הדרש שבתורה), און לפי פשוטו של מקרא דאַרף אויסקומען אַז דער פשט פון „ותעל הצפרדע\" איז „שרוץ הצפרדעים\".\nה. נאָך אַ תמי' אין פירש\"י: רש\"י אליין טייטשט אין אנהויב פ' וישלח, אַז „דרך ארץ לומר על שוורים הרבה שור\" — אַז מ'קען רופן אַ סך פון איין מין בל' יחיד, ע\"ש המין: האָט דאָך רש\"י אויך דאָ געקענט טייטשן בפשטות, אַז „ותעל הצפרדע\" מיינט הרבה צפרדעים, און דאָס וואָס שטייט בל' יחיד איז דאָס ע\"ש המין19?\nזיינען מפרשים20 מסביר, אַז ביי רש\"י איז דאָ שווער דער שינוי הלשון אין פסוק: אין המשך פון דער פרשה ווערט די מכה דערמאָנט גאַנצע צען מאָל בלשון רבים — „צפרדעים\" — טאָ פאַר־וואָס איז דער פסוק פונקט דאָ משנה און שרייבט בל' יחיד: „ותעל הצפרדע\"? איז דערפון געדרונגען, אַז (דאָס מיינט ניט ע\"ש המין, נאָר) דער פסוק מיינט דאָ מדגיש זיין דעם ל' יחיד בכדי דערמיט מרמז זיין אויף אַ זאַך וואָס האָט נאָר דאַ21 פאַסירט — און דערפאַר טייטשט רש\"י „צפרדע אחת היתה וכו'\".",[["19","19","וכמו שפי' בפס\"ז (לקח טוב) כאן. — בבאר יצחק (וראה דקדוקי רש\"י שבהערה 16) דכוונת רש\"י ב„שרוץ הצפרדעים קורא ל' יחידות\" הוא ע\"ש המין, וצע\"ג — שהרי מפורש ברש\"י „שרוץ הצפרדעים\", גם מביא הוכחה מ„ותהי הכנם\" ולא מר\"פ וישלח (כבפס\"ז שם)."],["20","20","יפה תואר לשמו\"ר שם. משכיל לדוד כאן. תר\"ת כאן."],["21","21","ראה משכיל לדוד כאן, דהחרטומים „לא יכלו אלא לאסוף ולכנוס הצפרדעים . . ולכך כתיב ויעלו את הצפרדעים\" — וכדעת ר\"פ בסנה' שם (ובשמו\"ר שם, ז — רבנן) דאפי' כגמלא לא מצו מיברו אלא האי מכניף להו והאי לא מכניף. אבל ממש\"כ רש\"י (לקמן פסוק יד) „לבראותם כו'\"•• משמע דמפרש כדעת ר\"א (בסנה' (רשמו\"ר שם) דאין השד יכול לבראות••• ברי' פחותה מכשעורה (וכמ\"ש במשכיל לדוד פסוק יד). ועפ\"ז י\"ל — דאדרבה: גם החרטומים העלו הצפרדעים מצפרדע אחת (ודלא כמ\"ש במשכיל לדוד שם, דגם לדעת ר\"א לא מצו לברוא אלא ברי' כפי הטבע). ומש\"נ באופן העשי' דהחרטומים והעלי' „ויעשו גו' *) ומה שדוקא במכת כנים אמרו „אצבע אלקים היא\" (כמו שהקשה ברמב\"ן פסוק טו. חדא\"ג לסנה' שם) — מתרץ (במשכיל לדוד) שם: הואיל וס\"ס גם הם העלו צפרדעים לא הוכרחו לומר אצבע אלקים היא משא\"כ גבי כנים שלא יכלו לפעול כלל. **) כ\"ה ברוב הגירסאות. ובכמה גירסאות: לבראותם ולהוציאם כו'. וראה מפרשי רש\"י שם. ובארוכה — שם אפרים (להרא\"ז מרגליות) לפרש\"י שם. ***) אבל ממש\"כ רש\"י „שאין השד שולט על כו'\" (ולא „לברוא\") — משמע כדעת ר\"פ דבפחות מכשעורה לא יכלו אפי' מיכניף להו — ראה רמב\"ן ובחיי שם. וראה בארוכה שם אפרים שם. ואכ\"מ."]]],[1300161098,"לויט דעם איז מובן, אַז דער פירוש המדרש — כאָטש ס'איז אַ דרש — האָט עס אבער אַ יתרון אויפן פי' „שרוץ הצפרדעים\" מצד דעם תוכן הכתובים („פשוטו של מקרא\"): דוקא לויטן פי' המדרש איז פארשטאַנדיק פארוואָס דאָ שטייט „ותעל הצפרדע\" בל' יחיד; משא\"כ לויטן פי' „שרוץ הצפרדעים\" — הגם אַז אויך לויט דעם פירוש ווערט פארענטפערט פארוואָס עס שטייט ניט אומעטום אין פרשה בל' יחיד<sup data-n=\"22\">22</sup> (וואָרום דער ל' יחיד פּאַסט נאָר דאָן ווען עס רעדט זיך וועגן „שרוץ הצפרדעים\"<sup data-n=\"23\">23</sup> — איז אבער די שווערקייט פארקערט: עס האָט אומעטום (אויך דאָ) געדאַרפט זיין בל' רבים, דער ל' יחיד דאָ איז ניט גלאַטיק24, ווייבאַלד עס שטייט גלייך נאָכדעם „ויעשו כן החרטומים . . . ויעלו את הצפרדעים\"?\nאון דערפאַר ברענגט עס רש\"י אלס צווייטן פשט, און דער פירוש המדרש איז דער ערשטער און עיקר פירוש לפי פשוטו של מקרא.\nס'איז אבער נאָך אלץ ניט פאַר־ענטפערט: מיט וואָס איז דער צווייטער פירוש מער „פשוטו\", אין טייטש פון די ווערטער „ותעל הצפרדע\", ווי דער פירוש המדרש?\nו. איז דער ביאור אין דעם: דאָס וואָס רש\"י איז אויסן צו באַוואַרענען איז ניט בלויז די שוועריקייט מצד דעם\nשינוי לשון, נאָר נאָכמער — דער לשון „ותעל הצפרדע\" (בל' יחיד) איז אויך אין סתירה צום אַנזאָג פון דעם אויבערשטן צו אהרן (אין פריערדיקן פסוק) „נטה את ידך במטך גו' והעל את הצפרדעים גו'\". וואָרום פון דעם הדגשה „והעל את הצפרדעים גו'\" (ניט ווי ביי מכת ארבה וואו עס שטייט25 „נטה ידך על ארץ מצרים ב(שביל מכת ה)ארבה ויעל גו'\", און עד\"ז ביי די אנדערע מכות<sup data-n=\"26\">26</sup> איז מובן, אַז דער ציווי צו אהרן איז ניט באַ־גרענעצט בלויז צו דער הכנה און התחלה פון „נטה את ידך במטך גו'\", נאָר ער דאַרף עס אויספירן ביז צום אויפברענגען די צפרדעים בפו\"מ און אין אַ ריבוי — „והעל את הצפרדעים\" — טאָ ווי האָט ער עס מקיים געווען בעת לפועל איז עס געווען אין אַן אופן פון „ותעל הצפרדע\" (איין צפרדע)?\nדערפאַר איז רש\"י מפרש „היו מכין אותה והיא מתזת נחילים נחילים\": הגם אַז לכתחילה האָט ער אויפגעבראַכט (דורך „ויט אהרן את ידו גו'\") בלויז איין צפרדע, עס איז אבער געווען אַזאַ צפרדע וואָס מתזת נחילים נחילים — זי שפריצט — ע\"ד ווי אַז מ'קלאַפט „על מימי מצרים\" שפריצט וואַסער (ניט עס ווערט באַשאַפן נאָך וואַסער מאין ליש), אזוי איז געווען מיט דער צפרדע וואָס איז געקומען פון די „מימי מצרים\" — און עס איז קיין נפק\"מ ניט ווער עס קלאַפט — דערפאַר איז רש\"י<sup data-n=\"27\">27</sup> משמיט דעם וואָרט (היו) מצרים.",[["25","25","בא י, יב ובפרש\"י."],["26","26","דם — „נטה ידך גו' ויהיו דם גו'\" (פרשתנו ז, יט): כנים — „והך את עפר הארץ והי' לכנים גו'\" (ח, יב): שחין — „קחו גו' וזרקו גו' והי' לאבק גו' והי' גו' לשחין גו'\" (ט, ח-ט): ברד — „נטה את ידך גו' ויהי ברד גו'\" (ט, כב): חשך — „נטה ידך גו' ויהי חשך גו'\" (בא, י, כא)."],["27","27","דלא כבתנחומא ותדבא\"ר (נסמן בהערה 7) ויעלו את הצפרדעים\" ולא „ויעשו גו' ותעל הצפרדע\" — כי כיון שכותב: ויעשו כן החרטומים — פירושו כאופן עשיית אהרן. ואכ\"מ."],["22","22","דאל\"כ — למה מפרש רש\"י ד„פשוטו\" הוא „שרוץ הצפרדעים\" (שאינו פירוש מוכרח), ולא בכמה מקומות — ע\"ש המין?"],["23","23","היינו — ה„שרוץ\" בפועל (וכמו ב„כנים\")."],["24","24","אבל אינה קשיא חזקה (כבפי' ע\"ש המין) — כי השינוי הוא רק במקום א'."]]],[1300161099,"עפ\"ז איז פארשטאַנדיק פארוואָס רש\"י קען דאָ ניט איינטיטשן, ווי אין גמ' און שמו\"ר, אַז „שרקה להם והם באו\" אָדער „השריצה ומלאה כל ארמ\"צ\", ווייל לויט דעם וועט אויס־קומען אַז אהרן האָט בפועל אויפ־געבראַכט ניט מער ווי איין צפרדע — און דער ריבוי הצפרדעים האָט זיך אויפגעטאָן דורך „שרקה\" אָדער „השריצה\" — ובמילא האָט ער מיט דעם ניט מקיים געווען דעם ציווי „והעל את הצפרדעים\". דערפאַר מוז רש\"י ברענגען דעם פירוש אַז מתזת נחילים.\nז. וויבאַלד דער פסוק זאָגט בפירוש אַז דער ציווי צו אהרן איז געווען „והעל את הצפרדעים\" (ל' רבים), מוז אין פסוק אויך זיין (נרמז עכ\"פ) ווי אזוי ער האָט דעם ציווי מקיים געווען.\nאיז דער ביאור אין דעם: „ותעל הצפרדע\" קען געטייטשט ווערן אויף צוויי אופנים: א) די צפרדע איז אויפ־געגאַנגען; ב) אלס מפעיל — די צפרדע האָט געמאַכט אויפגיין (אַנדערע צפרדעים)28.\nאון די צוויי פרטים אין פי' המדרש — (א) אַז אהרן האָט אויפגעבראַכט איין צפרדע, (ב) אַז די צפרדע האָט מעלה געווען אַנדערע — ווערן אַנגעדייטעט אין די צוויי טייטשן: א) „ותעל הצפרדע\" „צפרדע אחת היתה\"; ב) „ותעל (הצפרדע)\" „מתזת נחילים נחילים\".\nדערמיט ווערט אויך פארשטאַנדיק וואָס רש\"י ברענגט דעם „דרש\" — „והיא מתזת נחילים נחילים\" אויף די\nווערטער „ותעל הצפרדע\" און ניט אויף „ותכס את ארץ מצרים\".\nח. הגם דער פירוש האָט אַן אַנ־האַלט אין ל' הפסוק כנ\"ל, דאָך זאָגט רש\"י אויף דעם אַז „זהו מדרשו\" — ווייל לויט דעם פירוש מוז מען זאָגן אַז די צווי פארשידענע טייטשן — אופנים פון „ותעל הצפרדע\" האָבן ביידע פאַסירט, וואָס דאָס איז ניט אויס־געהאַלטן לויט דרך הפשט פון לערנען מקרא, ס'איז דער דרך פון „מדרשו\"29; לויט „פשוטו\" דאַרף עס געטייטשט ווערן אויף איין אופן: „ותעל\" ווי דער המשך „ותכס\", מוז מען לערנען אַז מיט „צפרדע\" (בל' יחיד) ווערט געמיינט „שרוץ הצפרדעים\".\nפונדעסטוועגן ברענגט עס רש\"י אלס צווייטן פירוש (און דער פירוש העיקרי איז „מדרשו\") — ווייל: א) מצד תוכן הכתובים איז דער פירוש המדרש מער מתאים צו פשוטו של מקרא (כנ\"ל ס\"ה); ב) אויך דער עצם אפטייטש פון וואָרט „צפרדע\" איז מער גלאַטיק לויטן פי' פון מדרש ווי לויטן פי' אַז דאָס מיינט „שרוץ הצפרדעים\"30 (כנ\"ל ס\"ג).\nט. פון „יינה של תורה\" אין פרש\"י:\nעס איז פאַראַן אַ כלל31 אַז המתחיל",[["29","29","להעיר מפרש\"י אסתר (ה, ד): רבותינו אמרו טעמים הרבה (ומביא טעם אחד בלבד — ומסיים) ועוד טעמים רבים — ובגמרא שם (מגילה טו, ב): עבדה כו' ככולהי תנאי וכולהו אמוראי. ואכ\"מ. אבל שם אין זה שייך לפי' תיבות הכתוב, כ\"א טעם ולכללות המאורע. ואכ\"מ."],["30","30","ואעפ\"כ רק הפי' הב' הוא „פשוטו\" — כי הקושי בפירוש „שרוץ הצפרדעים\" הוא רק שאין ע\"ז ראי' מכריחה, אבל פי' המדרש (שצריך לפרש „ותעל הצפרדע\" בב' אופנים (פועל ומפעיל) בחדא מחתא) — הוא היפך פירוש ע\"פ פשוטו."],["31","31","פרש\"י עקב ח, א — מתנחומא שם ו (וסוטה יג, ב). ירושלמי פסחים פ\"י ה\"ה. ר\"ה ספ\"א. מגילה ספ\"ב. ד„היו המצריים מכין אותה\". ובמדרש אגדה (באבער) ליתא תיבת „מצריים\"."],["28","28","ראה מלבי\"ם כאן."]]],[1300161100,"במצוה אומרים לו גמור, און ווי חז\"ל32 וואַרענען וועגן די שטרענגע עונשים ר\"ל וואָס קומען צוליב דעם וואָס מען קען גומר זיין און מ'איז ניט גומר אַ מצוה.\nויתרה מזו ובפרט באַ לערנען תורה מיט אַ צווייטן דאַרף זיין תשים לפניהם כשולחן הערוך ומוכן לאכול לפני האדם33.\nאבער לאידך, אויב אַ איד וויים, אַז צוליב געוויסע אומפאַרמיידלעכע סיבות, וועט ער די אָנגעהויבענע מצוה ניט קענען גומר זיין, טאָר ער זיך אבער ניט אָפהאַלטן ח\"ו פון צו זיין אַ מתחיל במצוה און צו מקיים זיין דעם טייל פון דער מצוה וואָס איז פאַר אים מעגלעך — און ווי מיר געפינען ביי משה רבינו, אַז ער האָט מבדיל געווען די ג' ערי מקלט אין עבר הירדן34, כאָטש אַז „אינן קולטות עד שיבדלו אותן שבארץ כנען\"35, ווייל „מצוה שאפשר לקיימה אקיימנה\"36.\nומובן אַז אַ ספק אין דעם — וואָס איז גמר ושלימות המצוה — איז במצות ע\"ד פון צדקה — איז כל המרבה ה\"ז משובח, אבער במצות ע\"ד פון מלקות איז לא יוסיף37 ביז וואַנעט לדעת כמה איז בצרי רבנן חדא38 — מצד דעם חשש פן יוסיף39.\nעד\"ז איז דער אונטערשייד צווישן די צוויי פירושים אין רש\"י:\nלויטן ערשטן פירוש קומט אויס, אַז אהרן האָט אויפגעטאָן דעם „העל את הצפרדעים\", אבער „ותכס את ארץ מצרים\" איז געקומען שפעטער דורך די וואָס „היו מכין\":\nאבער לויטן צווייטן פירוש קומט אויס, אַז אהרן האָט אויפגעטאָן דעם גאַנצן שרוץ הצפרדעים, וואָס האָט מכסה געווען ארמ\"צ.\n— וואָרעם די צפרדעים זיינען געווען: א) בפשטות — מכה ונגוף למצרים, דערפאַר בפשוטו — האָט אהרן אפגעטאָן אלעס, ב) אַ פעולה כדי פרעה זאָל דערפון דרשנ'ן און לערנען אַז עס דאַרף זיין דערנאָך „ואשלחה את העם\" האָט אהרן אויך געטאָן — לויט מדרשו — באופן אַז עס איז געווען דערנאָך „מכין אותה\" כו'.\nאין אַנדערע ווערטער: לויט'ן מפרש זיין תורה בדרך (המדרש) הדרש, איז דאָס אזוי אויך בנוגע דעם פירוש פון דעם ציווי „והעל את הצפרדעים\" — לאו דוקא הצפרדעים כפשוטו (רבים), ס'קען אויך מיינען צפרדע אחת כו', און ווייבאַלד אַז דאָס איז אַן ענין (ע\"ד) פון מלקות, איז „בצרי\", און אנגענומען אַז דער ציווי האָט געמיינט „אחת כו'\" — איז ניטאָ דער חשש „פן יוסיף\".\nיו\"ד. די הוראה פון די ביידע פירושים איז:\nפון דעם ערשטן פירוש (אַז אהרן האָט אויפגעבראַכט נאָר „צפרדע אחת\") לערנט מען אַפּ, אַז אויב במדת פורעניות (מכה למצרים) כך במדה טובה על אחת",[["32","32","סוטה ותנחומא שם."],["33","33","משפטים (כא, א) ובפרש\"י. וראה הל' ת\"ת לאדה\"ז (פ\"ד סי\"ח)."],["34","34","ואתחנן ד, מא."],["35","35","פרש\"י ואתחנן שם. מסעי לה, יג (מספרי שם)."],["36","36","פרש\"י ואתחנן שם (ממכות י, א)."],["37","37","תצא כה, ג."],["38","38","מכות כב, ב."],["39","39","תיב\"ע תצא שם. פיה\"מ להרמב\"ם מכות פ\"ג מ\"י. רמב\"ם הל' סנהדרין רפי\"ז (וראה נ\"כ שם). חינוך מצוה תקצה. וראה במדב\"ר פי\"ח, כא. וכבר העירו באחרונים שעפ\"ז מצינו ענין סייג מן התורה (וראה לקח טוב כלל ח)."]]],[1300161101,"כו\"כ40, אַז מען מוז באַוואַרענען דעם חשש „פן יגרע\".\nאון פון צווייטן פירוש (פון וועלכן עס קומט אויס, אַז אהרן האָט „גומר\" געווען די מצוה) האָט מען די הוראה, אַז מ'דאַרף זיך משתדל זיין צו טאָן אַ מצוה בשלימותה, מתחילתה ועד סופה וגמרה; און ווען ס'האַנדלט זיך, לדוגמא אין דער מצוה צו מקרב זיין אַ צווייטן אידן צו תומ\"צ ות\"ת כנגד כולם — דאַרף מען זיך ניט באַנוגענען מיט התחלת הקירוב, נאָר מ'דאַרף גומר זיין ביזן סוף: טאָן מיט אים ביז עס זאָל זיין כשולחן הערוך, תכלית העילוי:\nאויב אבער ער איז אין אַ מצב וואָס ער קען נאָר אָנהויבן די מצוה, ער וועט נאָר קענען מאַכן די „התחלה\" אין דעם קירוב הזולת צו תומ\"צ — קען ער דאָך זיך טראַכטן: וואָס איז די פעולה אַז ער וועט אָנהויבן צו „טאָן\" מיט יענעם, בעת ער ווייס ניט צי ער וועט דערמיט אויפ־טאָן — און ווער ווייס מיט וואָס עס וועט זיך ענדיקן שפּעטער?\nאויף דעם קומט די הוראה האמורה, אַז „מצוה שאפשר לקיימה אקיימנה\".\nובכלל: מ'דאַרף זיך ניט אריינלאָזן אין חשבונות — „בהדי כבשא דרחמנא למה לך\"41: דאָס איז ניט זיין „עסק\". ער דאַרף אָנהויבן און טאָן, וויפל נאָר ער קען, אויף צו מקרב זיין אַ צווייטן אידן;\nאון נאָכמער — בשעת ער טוט כל התלוי בו, איז „מחשבה טובה הקב\"ה מצרפה למעשה\"42 — דער אויבערש־טער איז מצרף און ברענגט אראָפּ זיין מחשבה טובה לידי מעשה43:\nאון בשעת דער אויבערשטער איז „גו־מר\" די „מצוה\", ווערט דאָס אפגעטאָן אן קיינע מדידות והגבלות, ביז אין תכלית העילוי והשלימות.\n(משיחת ש\"פ וארא תשכ\"ז)",[["40","40","ראה פרש\"י יתרו כ, ו. תשא לא, ז."],["41","41","ברכות י, סע\"א."],["42","42","קדושין מ, א."],["43","43","ס' המאמרים תש\"ב ע' 87. וראה פי' אדה\"ז — תניא פט\"ז."]]],[1300161102,"<h3>וארא ה</h3>\nא. בנוגע די מכות וואס דער אויבערשטער האט געבראכט אויף די מצרים, איז דא א פלוגתא¹ צווישן רבי אליעזר און רבי עקיבא²: רבי אליעזר אומר .. כל מכה .. היתה של ארבע מכות כו׳ רבי עקיבא אומר .. של חמש מכות כו׳.\nוואס איז דער תוכן פון די צוויי דיעות „של ארבע\" און „של חמש\"? —\nאיז מבואר אין כלבו³ בשם „בעל המלמד\", אז די פלוגתא איז:\nרבי אליעזר האלט, אז די מכות האבן דורכגענומען אלע ד׳ יסודות פון יעדער זאך³* אין וועלכער ס׳זיינען געווען די מכות. דאס הייסט, די מכה איז געווען ניט נאר אין דער זאך ווי זי איז שוין א מורכב פון אלע פיר יסודות, נאר זי האט דערגרייכט נאך טיפער, אויך אין דעם עצם פון יעדן יסוד, וואס איז אין דער זאך — און דעריבער איז יעדער מכה „של ארבע\".\nולדוגמא: מיט דער מכת דם איז גע־שלאגן געווארן ניט נאר די וואסער ווי דאס זעט זיך אלס מציאות פון מים, נאר אויך דער אש רוח ועפר שבמים.\nרבי עקיבא טוט אויף נאכמער, אז די מכה איז אויך געווען אין דעם „חומר היולי\"⁴ פון דער זאך, וואס איז פשוט (אויסגעטאן) פון (דעם ציור פון) די ד׳ יסודות — קומט אויס, אז יעדער מכה איז געווען „של חמש\": אין די ד׳ יסודות און אין „חומר היולי\".\nב. דער מכוון אין די מכות איז גע־ווען, כשמן, צו שלאגן און צעברעכן מצרים. דערפון איז פארשטאנדיק, אז דער ענין הנ״ל, דאס וואס די מכות האבן דורכגעדרונגען די דברים המו־כים, איז\n— (א) לויט ביידע דיעות איז דאס געווען ניט נאר אין דעם „גילוי\" (אין דער זאך ווי זי זעט זיך אן), נאר אויך אין דעם „העלם\" און עצם הדבר; (ב) די צוויי דיעות הנ״ל, צי דאס איז געווען (אויך) אין דעם חומר היולי, אדער נאר אין דעם חומר ווי ער האט שוין א ציור (פון די ד׳ יסודות) —\nאיז דאס תלוי — אויף וויפל טומאת מצרים האט עס דורכגענומען⁵, וואס",[["1","1","הגדה של פסח. ממכילתא בשלח יד, לא. מדרש תהלים מזמור עח. ובשמו״ר (פכ״ג, ט) הובאה רק דעת רבי אליעזר."],["2","2","בנוגע לדעת רבי יוסי הגלילי שהובאה שם לפנ״ז — ראה לקמן בפנים ס״ה ובהערה 21."],["3","3","בפירוש ההגדה. הובא ג״כ בארחות חיים (פירוש ההגדה), אבודרהם (סדר ההגדה ופירושה), ועוד. וכ״ה בריטב״א להגש״פ (והובא בעקידה פ׳ בשלח שער מ׳). רשב״ץ (מאמר חמץ, פירוש ההגדה). ועוד. וראה הערה 4. 3*) ראה רמב״ם הל׳ יסוה״ת רפ״ד. מו״נ ח״א פע״ב ובכ״מ שם."],["4","4","כ״ה בריטב״א שם („מכת ההיולי הוא יסוד הכולל\"). ובא״ח וכלבו (ועד״ז באבודרהם) שם „יסוד הגלגלים שהוא יסוד חמישי\". וברשב״ץ: היסוד החמישי הוא הגלגל השתיית היסודות. [ולהעיר מד״ה החודש הש״ת פ״ב, דבהמכות כו׳ הי׳ שינוי לא רק בהיש כ״א בהכח האלקי, עיי״ש]. בעקידה שם פליג על שיטה זו (כי „ההיולי הוא משותף ושוה אצל כל הצורות כו׳\"), ומפרש שר״ע חושב גם „טבע המורכב וצורתו\" (וראה גם אברבנאל (בזבח פסח)) — משא״כ לשאר הדיעות צ״ע למה לא חשיב מכה בהדבר בגמרו — בהרכבו וצורתו."],["5","5","וע״ד שמסביר הגאון הרגצ׳ובי שיש איסורים שהם רק בצורת (תואר) דבר הנאסר ויש — שהם גם בהחומר שלו (ראה מפצ״פ פ״א) וראה לקמן בפנים."]]],[1300161103,"בהתאם לשיעור זה זיינען געקומען די מכות צו מבטל זיין די טומאה.\nג. דער ענין הנ״ל — אז טומאת מצרים האט דערגרייכט דעם עצם פון מציאות הדברים און די אויבנגעב־ראכטע פלוגתא אין דעם — שפיגלט זיך אפ, ווי אלע עניני אגדה (און פנימיות התורה), אויך אין נגלה דתורה, ביז אין הלכה — אין דעם תוכן ואופן האיסור חמץ (וואס איז א מסובב פון טומאת מצרים):\nדער איסור חמץ איז ניט נאר באכילה ובהנאה, נאר אויך בבל יראה ובבל ימצא (און בריינגט אויך דעם חיוב ומצוה פון ביעור חמץ).\nדער חילוק צווישן די דריי ענינים הנ״ל (איסור אכילה, איסור הנאה און בל יראה ובל ימצא (וביעור)) איז:\nדי שייכות פון אכילה (ואיסורה) מיטן דבר הנאכל איז מיט זיין „צורה\", ווי ער (דער דבר הנאכל) שטייט אין א ציור גמור (ביז צו זיין ראוי לאכילה), און ניט מיט זיין „חומר\" ווי ער איז בפ״ע, מיטן עצם המציאות פון דבר מאכל; די הנאה (ואיסורה) פון א זאך איז פארבונדן (אויך) מיט דעם עצם פון דער זאך.\n[וואס דאס איז איינער פון די ביאורים⁶ ווי קען זיין אז א זאך זאל זיין אסור באכילה און מותר בהנאה — דלכ־אורה: אויב די זאך האט אין זיך רע און איסור, ווי אזוי מעג מען הנאה האבן פון דער אסור׳דיקער זאך?\nנאר דער ביאור אין דעם איז, כנ״ל: איסור אכילה מיינט אז דער רע איז נאר אין צורת וחיצוניות הדבר (דאס וואס מאכט עם ראוי לאכילה), און דעריבער איז עס מותר בהנאה, ווייל אין דעם חומר ועצם הדבר (וואס איז שייך צו הנאה) איז ניטא קיין רע].\nאבער אויך הנאה (ואיסורה), וויבאלד דער פארבונד איז דורך באנוצן זיך מיט דער זאך, וואס דאס איז דוקא ווען עס איז חומר בצורה מסוימת, איז דאס גופא א באווייז, אז דאס איז ווי די זאך האט שוין א ציור.\nביי חמץ אבער קומט צו דער איסור, אז ער טאר זיך ניט געפינען אין רשות פון א אידן, אפילו אן וועלכען ס׳איז שימוש מיטן חמץ — ד.ה. אז דער איסור האט דורכגענומען דעם חומר ועצם הדבר ווי ער איז אויסגעטאן פון איזו צורה שתהי׳, וואס דערפאר, איז דער „ימצא\", די עצם פאראנענקייט פון דעם חמץ אין זיין רשות אסור⁷.\nד. אין דער מצוה פון ביעור חמץ איז דא א פלוגתא⁸ צווישן רבי יהודה און די חכמים: רבי יהודה אומר אין ביעור חמץ אלא שריפה, וחכמים אומרים אף מפרר וזורה לרוח או מטיל לים.\nאיז דער ראגאטשאווער⁹ מסביר דעם טעם הפלוגתא: לויט רבי יהודה דארף",[["6","6","ראה עוד ביאור (באופן אחר) — שיחת ש״פ אחרי תשל״ו. לקו״ש ח״ז ע׳ 299."],["7","7","להעיר מהצד השוה דחמץ וע״ז, דשניהם מצוה לבערם, אסורים במשהו ועוד (ומאן דאכיל חמץ בפסח כמאן דפלח לעכו״ם — זח״ב קפב, א) — ראה תור״ש חי״ט מילואים סימן כ׳, וש״נ. וראה שו״ת הרדב״ז (ח״ג סי׳ תתקעז. הובא בשמחת הרגל להחיד״א „לימוד א׳\"), שהטעם שהחמירה תורה בחמץ יותר משאר כל איסורים (גם ע״ז) הוא מפני שחמץ בפסח רמז ליצה״ר, עיי״ש (ובשמחת הרגל שם), ובטעהמ״צ שלו מצוה קז."],["8","8","משנה פסחים רפ״ב. וש״נ."],["9","9","צפע״נ עה״ת בחקותי כו, ו. מפענח צפונות שם ס״ט, וש״נ. וראה לקו״ש ח״ז ע׳ 189. לקמן ע׳ 134 ואילך."]]],[1300161104,"מען משבית זיין דעם עצם מציאות פונעם חמץ, ובמילא דארף מען אים פארברענען, ווייל ווען מ׳איז נאר „מפרר וזורה לרוח כו׳\", בלייבט איבער דער עצם מציאות פונעם חמץ; משא״כ די חכמים האלטן, אז ס׳איז גענוג ווען מ׳איז מבטל ומשבית דעם „תואר\" פון דעם חמץ — מ׳נעמט צו די אפשריות אז א מענטש זאל קענען עסן אדער הנאה האבן פון דעם חמץ — און דאס ווערט אויפגעטאן אויך ווען מ׳איז „מפרר וזורה לרוח כו׳\".\nומובן, אז דאס גופא, דער „שיעור\" פון השבתה, איז תלוי אויף וויפל דער איסור חמץ נעמט דורך דעם דבר איסור: אויב דער איסור דערגרייכט אויך די עצם מציאות, דארף די השבתה זיין עד כדי כך אז די עצם מציאות פונעם חמץ זאל בטל ווערן; און אויב דער איסור רירט אן נאר דעם תואר וצורה — איז גענוג צו משבית זיין (די צורה —) די אפשריות אויף אכילה והנאה, און ניט דעם עצם, ווייל אין אים איז ניטא קיין איסור¹⁰.\nויש לומר, אז די צוויי דיעות זיינען בהתאם מיט די צוויי שיטות פון רבי אליעזר ורבי עקיבא בענין המכות:\nרבי אליעזר וואס זאגט אז „כל מכה כו׳ של ארבע מכות\" — אז די מכות זיינען נאר געווען אין דער זאך ווי עס האט שוין דעם ציור פון ד׳ יסודות — איז כשיטת חכמים „אף מפרר וזורה לרוח כו׳\", אז מען דארף נאר מבער זיין די מציאות פונעם חמץ ווי עס איז פאר־בונדן מיטן תואר (וצורה) פון חמץ (די אפשריות אויף אכילה והנאה);\nאון דעת רבי עקיבא וועלכער זאגט אז „כל מכה כו׳ של חמש מכות\" — די מכות זיינען אויך געווען אין חומר ההיולי — איז דאס ווייל ער האלט¹¹ (כשיטת רבי יהודה) „אין ביעור חמץ אלא שריפה\".\nה. בדוגמא צו די צוויי אופנים אין ביעור חמץ, בנוגע דעם עצם (מציאות) פון חמץ — צי תורה האט גע׳אסר׳ט די עצם מציאות (ווי ס׳איז אויסגעטאן פון וועלכער־עס־איז צורה), אדער נאר די מציאות ווי עס איז פארבונדן מיטן „תואר\" (דאס וואס די זאך איז ראוי להנאה כו׳) — זיינען אויך דא צוויי אופנים אין דער איסור הנאה גופא (וואס ווייזט אויך, כנ״ל, צי דער רע איז „טיפער\" ווי אין דעם תואר הדבר):\nא) א הנאה וואס איז „מביא לידי שום אכילה\"¹², ווייל „סתם הנאות לידי אכילה הם באות שלוקח בדמים דבר מאכל\"¹² — וואס אין א ברייטערן זין איז דאס כולל יעדע הנאה וואס דער מענטש האט דערביי א פארדינסט¹³ (ובמילא איז עס „מביא לידי שום אכילה .. שלוקח בדמים דבר מאכל\"¹²).\nב) א השתמשות וואס דער מענטש האט ניט דערפון קיין שום פארדינסט",[["10","10","וראה מפצ״פ שם, שזהו ג״כ הביאור בפלוגתת ר״י ור״ש (פסחים כח, סע״א ואילך) בחמץ שעבר עליו הפסח."],["11","11","פסחים ה, ריש ע״ב."],["12","12","לשון רש״י — פסחים כא, ב ד״ה לא יאכל [בדעת חזקי׳ (שיליף איסור הנאה בחמץ מ„לא יאכל חמץ לא יהא בו היתר אכילה\")]. וראה שד״ח (כללים מערכת כ״ף כלל קיט ד״ה ואנא בסופו) שגם לרב אבהו (ד„לא יאכל לא תאכל לא תאכלו אחד איסור אכילה ואחד איסור הנאה במשמע\"), גדר ההנאה שאסרה תורה הוא „שלא יהא בו היתר אכילה\"*. אבל להעיר מסהמ״צ להרמב״ם מל״ת קפז. חינוך מצוה קיג. ואכ״מ."],["13","13","ראה מהר״ם חלואה לפסחים כא, ב. *) שלכן צריך לימוד מיוחד לאסור להאכיל חמץ לכלבי הפקר, כדלקמן בפנים."]]],[1300161105,"— לדוגמא: מאכיל זיין דעם דבר איסור לכלבי הפקר — וואס אין דעם איז ניט שייך צו זאגן אז די הנאה ברענגט לידי אכילה.\nאין ירושלמי¹⁴ איז דא א פלוגתא וועגן מאכיל זיין חמץ לכלבי הפקר: איין מ״ד האלט ס׳איז מותר¹⁵, און א צוויי־טער מ״ד האלט אז דער פסוק¹⁶ „ולא יאכל חמץ\" איז מרבה, אסר׳ט אויך (די השתמשות פון) מאכיל זיין דעם חמץ לכלבי הפקר.\nקען מען זאגן, אז אויך די פלוגתא איז פארבונדן מיט דער שאלה (אויף וויפל איז דער איסור חמץ¹⁷ פארבונדן מיט חומר ועצם הדבר)¹⁸:\nאויב דער איסור איז שורה אויף דעם עצם זאך נאר אויף וויפל עס האט א שייכות צום תואר וציור — דאן איז דער איסור הנאה (וואס איז פארבונדן מיטן עצם הדבר כנ״ל) מוגבל בלויז צו די הנאות וואס האבן א שייכות צו איסור אכילה („מביא לידי שום אכילה\")¹⁹:\nאבער אויב דער איסור איז שורה אויף עצם הדבר (ווי ער האט קיין שייכות ניט צום תואר וציור) — דעמאלט איז דער איסור הנאה אן איסור מצד עצמו וואס איז כולל יעדער אופן פון השתמשות, אויך אזא וואס איז ניט „מביא לידי שום אכילה\".\n[ועפ״ז יש לומר, אז דאס וואס רבי יוסי הגלילי זאגט (וואס זיין דיעה ווערט געבראכט אין מכילתא²⁰ גלייך פאר די צוויי דיעות הנ״ל פון רבי אליעזר און רבי עקיבא): „מנין .. שלקו המצרים במצרים (נאר²¹) עשר מכות ועל הים לקו חמשים מכות וכו׳\", איז ווייל לשיטתו²² איז חמץ מותר בהנאה²³, דאס באווייזט, כנ״ל, אז דער איסור חמץ איז נאר אין תואר הדבר²⁴ — ובנוגע צו",[["14","14","פסחים רפ״ב."],["15","15","וכבר האריכו (נ״כ הירושלמי שם, ועוד) בדעת רש״י (פסחים ה, ריש ע״ב ד״ה ש״מ): יאכילנו לכלבים. ובגליוני הש״ס (להר״י ענגל) פסחים (כא, א) מביא מספר הפרנס סי׳ נב: ואם מצא .. מיני איסורי חמץ .. ואסור בהנאה ולכלב תשליכון אותו. וראה פרמ״ג (אשל אברהם) או״ח סתמ״ח סק״ט."],["16","16","בא יג, ג."],["17","17","ראה מקור חיים או״ח שם סק״י — דאיסור זה הוא רק בחמץ ולא בשאר איסורי הנאה (וראה גם ביאורי הגר״א או״ח שם. פרמ״ג הנ״ל). אבל רוב הפוסקים ס״ל דאיסור זה הוא גם בשאר איסורי הנאה (ראה שד״ח כללים מערכת אל״ף כלל רכג. פאת השדה כללים שם כלל לת. וש״נ. וכ״ה בשו״ע אדה״ז שם סתמ״ז קו״א סק״ב). ולהעיר, שלדעת כמה הטעם הוא רק משום דבעי קבורה (ולא מצד עצם איסור הנאה) — ראה שד״ח שם."],["18","18","אבל מובן שיש לחלק בין פלוגתא זו להפלוגתא בביעור חמץ — כי כללות איסור הנאה אינו בעצם מציאות הדבר כמו ב״י וב״י וביעור, וכנ״ל בפנים. וראה שו״ע או״ח ר״ס תמה (ושו״ע אדה״ז שם סעיף ד, ז) שהלכה כחכמים דמפרר וזורה לרוח כו׳, ובסי׳ תמח ס״ו (ושו״ע אדה״ז סתמ״ג ס״ג. תמה ס״ה. תמח בסופו) נפסקה ההלכה דאסור להאכיל חמצו לבהמות של הפקר."],["19","19","ואף שחמץ אסור בב״י וב״י (שמורה שהאיסור הוא בעצם המציאות כנ״ל) — יש לומר, שלדיעה זו האיסור דב״י וב״י הוא רק סייג (מה״ת*) שלא יבא לאכלו, כמ״ש הר״ן ריש פסחים. פרמ״ג פתיחה להל׳ פסח ח״א פ״א אות ט׳."],["20","20","נסמן לעיל הערה 1. וכ״ה בשאר מקומות שבהערה הנ״ל."],["21","21","ע״פ המבואר בפנים יומתק הלשון „רבי אליעזר אומר כו׳\" (דמשמע שחולק על ריה״ג) — אף שאינו מוכרח (ראה זבח פסח. הגש״פ עם לקוטי טעמים ומנהגים (קה״ת תשל״ג ושלאח״ז) ע׳ כז)."],["22","22","פסחים כג, א. וש״נ."],["23","23","אבל להעיר, שבשמו״ר (צויין לעיל הערה 1) גריס „ר׳ יהושע\", ודעת ר׳ יהושע היא דחמץ אסור בהנאה (ראה מלא הרועים ע׳ חמץ בהנאה אות כא)."],["24","24","ואיסור ב״י כו׳ — ראה לעיל הערה 19. *) כמה דוגמאות לזה — ראה לקח טוב (להר״י ענגל) כלל ח. שד״ח כללים מערכת אל״ף כלל קכא. פאת השדה כללים שם כלל לז."]]],[1300161106,"טומאת מצרים ווייזט עס אז עס האט אנגערירט נאר דעם תואר וחיצוניות הדברים — ובמילא איז יעדע מכה גע־ווען נאר אין דער מציאות הדברים ווי זיי זיינען שוין מורכב פון ד׳ יסודות].\nו. ע״פ האמור לעיל (סעיף ב׳), אז די פלוגתא פון רבי אליעזר און רבי עקיבא איז תלוי אויף וויפל טומאת מצרים האט דורכגענומען ארץ מצרים ואת אשר בה, קען מען מסביר זיין דעם טעם פון די מדרשות חלוקות בנוגע די ד׳ גליות:\nברוב המקומות²⁵ ווערט גלות מצרים ניט גערעכנט צווישן די ד׳ מלכיות וגליות, און ווי עס שטייט דערויף דער טעם²⁶, ווייל זי איז „שקול ככולם ויותר מהם .. ולכן לא הוזכר בכללם כי הוא בחינה גדולה מכולם\"; לאידך אבער זיינען דא ערטער²⁷ וואו מצרים ווערט יע גערעכנט צווישן (און אלס די ערשטע פון) די ד׳ מלכיות וגליות.\nויש לומר, אז אויך די צוויי שיטות זיינען פארבונדן מיט דעם חילוק הנ״ל — אויף וויפל האט טומאת מצרים דורכגענומען ארץ מצרים.\nדער ביאור בזה:\nדער טעם וואס מצרים ווערט (ברוב המקומות) ניט דערמאנט צווישן די ד׳ מלכיות וגליות, איז ווייל די ד׳ מלכיות וגליות זיינען „נגד ד׳ אותיות הוי׳\" און גלות מצרים איז „נגד קוצו של יו״ד\"²⁶; וע״פ הידוע אז די ד׳ יסודות „הם ד׳ אותיות הוי׳\"²⁸ און „קוצו של יו״ד\" (כתר) איז „דוגמת החומר הקדום הנקרא היולי\"²⁹ — קומט אויס, אז די ד׳ גליות זיינען נגד די ד׳ יסודות³⁰, און גלות מצרים האט אנגערירט אויך דעם חומר היולי:\nאון די מרז״ל וואו מצרים ווערט דערמאנט צווישן די (ד׳) מלכיות, איז דאס למ״ד אז מצרים איז נגד בחי׳ חכמה³¹; און אע״פ אז אויך לויט דער דיעה איז מצרים דער שורש פון אלע גליות³² — איז עס אבער א שורש וואס איז כולל די אלע גליות³³; און לויט דער דיעה, האט קליפת מצרים אנגערירט נאר אין דעם חומר וואס האט שוין דעם ציור פון ד׳ יסודות.\nז. דער ענין פון גלות ויציאת מצרים איז אויך דא אין עבודה רוחנית: מצרים איז פון לשון מיצרים וגבולים: גלות מצרים מיינט, אז די עבודה פון א אידן",[["25","25","ראה לדוגמא: ב״ר פ״ב, ד. פט״ז, ד. פמ״ד, טו. שם, יז. ויק״ר ס״פ שמיני."],["26","26","ל״ת להאריז״ל ר״פ תצא. ס׳ הליקוטים שם."],["27","27","מגילה (כט, א — בעין יעקב. וראה דק״ס שם): גלו למצרים כו׳ לעילם כו׳ לבבל כו׳ לאדום. וראה זח״א (פא, ב. קכה, סע״א (במדרש הנעלם). וראה רש״י בראשית ב, יא) דנהר הראשון מד׳ נהרות „פישון\" (בראשית שם) שייך למצרים. וראה לקו״ת ס״פ צו. אוה״ת פרשתנו (כרך ז) ע׳ ב׳תרז („גלו ישראל לשם ד׳ גליות והראשון הי׳ גלות מצרים כו׳\"). ועוד. *) בירוש׳ תענית (פ״א סה״א) מקדים בבל לעילם (ומוסיף יון). וראה דק״ס מגילה שם."],["28","28","ע״ח שער דרושי אבי״ע בתחילתו. מאו״א אות ד׳ סכ״ד. הובאו בלקו״ת במדבר ה, רע״ב."],["29","29","ע״ח שם (בהמשך הפרק)."],["30","30","ראה אוה״ת שם: ובזהר נז׳ שהם ד׳ יסודות ארמ״ע והכל ענין אחד."],["31","31","ראה מדרש הנעלם ולקו״ת שצויינו בהערה 27."],["32","32","שלכן כל המלכיות נק׳ ע״ש מצרים (ב״ר פט״ז, ד). ולהעיר מאוה״ת שם „שר של מצרים ושל בבל\", וכן באוה״ת בראשית (כרך ג׳ — תקס, ב) „ברבות בראשית פט״ז פי׳ ג״כ ענין ד׳ נהרות על מצרים בבל כו׳\". וראה ש׳ המצות להאריז״ל פ׳ ראה. זהר הרקיע לזח״ב רנח, א."],["33","33","להעיר מב׳ הביאורים בד״ה קול דודי תש״ט בענין כל המלכיות נק׳ ע״ש מצרים."]]],[1300161107,"איז מיט א גבול — מדידה והגבלה, און יציאת מצרים איז וואס ער גייט ארויס בעבודתו פון אלע מדידות והגבלות (אויך פון די הגבלות פון נפש האלקית).\nאון אין דעם איז די פלוגתא צווישן רבי אליעזר ורבי עקיבא צי די מכות זיינען געווען נאר אין די ד׳ יסודות אדער אויך אין חומר היולי — וואס אין רוחניות מיינט עס: צי עס פאדערט זיך די עבודה פון יציאת מצרים נאר אין די עשר כחות הנפש, וואס טיילן זיך אין פיר סוגים (כנגד ד׳ אותיות שם הוי׳ *<sup data-n=\"33\">33</sup> —\n— (א) עבודה בפועל במחשבה דיבור ומעשה (מלכות), (ב) במדות (ז״א), (ג) בשכל (בינה), און (ד) מסירת נפש (חכמה) —\nאדער אויך אין יחידה שבנפש (וואס איז בדוגמא צו חומר היולי²⁹):\nרבי אליעזר האלט אז „כל מכה כו׳ של ארבע מכות\" — עס דארף זיין די עבודה פון יציאת מצרים אין אלע פיר סוגים פון כחות הנפש, ארויסגיין פון די הגבלות פון יעדן פון זיי:\nדער נידעריקסטער אופן איז, די מדידה והגבלה אין זיין מלחמת היצר — וואס ברענגט אים צו עובר זיין ר״ל במעשה (ובדיבור ובמחשבה³⁴) בפועל: עכ״פ אויף איסורים וואס פארלאנגען א מלחמה גדולה ועצומה וכו׳³⁵.\nא מער דקות׳דיקער אופן אין „מצרים\" איז, אז כאטש ער איז נזהר בתכלית פון עובר זיין א דבר איסור (אפילו א דקדוק קל של ד״ס), איז אבער זיין הנהגה (אין עניני היתר) אין אן אופן וואס איז צוגעפאסט צו „הנחות העולם\" — אז ביי יעדער זאך וואס ער טוט פארנעמט ביי אים אן ארט „מה יאמרו הבריות\": וואס אזא הנהגה נעמט זיך דערפון וואס ער איז מדוד ומוגבל לויט זיין הרגש פון דער וועלט ארום עם, אין זיינע „מדות\" (וואס פילן און רעכענען זיך מיט דעם „ארום\")³⁶.\nאפילו ווען ער גייט שוין ארויס פון די מדידות והגבלות פון דער וועלט ארום זיך — קען ער אבער נאך אלץ בלייבן צוגעבונדן צו די הגבלות פון זיין אייגע־נער מציאות: זיין עבודה איז נאר ע״פ טעם ודעת, מיט דער קרירות פון זיין שכל.\nדי העכסטע דרגא וואו מען דארף באווארענען די עבודה פון יציאת מצרים, לדעת רבי אליעזר, איז — אין דער עבודה פון מסירת נפש (חכמה שבנפש): ער איז טאקע עובד ה׳ למעלה מטעם ודעת, אבער נאך אלץ מיט א מדידה והגבלה,\nע״ד ווי דער רבי האט דערציילט וועגן איינעם וואס האט ביים לייענען ק״ש מאריך געווען אין „אחד\", זיך מתבונן געווען אין „אחד\" און האט שפעטער געזאגט אז די התבוננות האט זיך געצויגן „באלד איינע מינוטע\": ער האט זיך פארטיפט אין דער התבוננות פון „אחד\", וואס ענינה איז מסירת נפש, און בה בשעה האט ער געקענט קוקן אויף א זייגער און אויסרעכענען די צייט וואס ער איז געשטאנען אין דער תנועה פון מסירת נפש.\nאדער בדקות יותר: ביי אים איז נאך דא דער הרגש אז ער פראווערט מסירת",[["","","*33) אגה״ת פ״ד, ובכ״מ."],["34","34","כי המהרהר ברצון נק׳ רשע באותה שעה כו׳ (תניא ספי״ב)."],["35","35","ראה תניא פ״ל."],["36","36","ראה סה״מ תש״ח (ע׳ 273) ובכ״מ — בההפרש בין מוחין ומדות."]]],[1300161108,"נפש, וואס דאס באווייזט אז ער איז נאך ניט לגמרי ארויס פון די מדידות והגב־לות פון זיין מציאות³⁷.\nח. אויף דעם טוט אויף רבי עקיבא, אז „כל מכה כו׳ של חמש מכות\":\n(רבי) אליעזר איז על שם „אלקי אבי בעזרי\"³⁸, ער איז געווען בן הורקנוס³⁹ און בן אברהם יצחק ויעקב⁴⁰ וואס האט געהאט דעם עזר פון „אלקי אבי\", וואס דערפאר האט זיך ביי אים ניט אפגע־לייגט אז עפעס קען אנרירן דעם עצם פון א אידן, ווארום אפילו בשעת החטא היתה באמנה אתו⁴¹.\nרבי עקיבא אבער האט געשטאמט פון גרים⁴², האט ער גערעדט און באווארנט די וועלכע מ׳דארף ערשט בריינגען תחת כנפי השכינה, בדקות יותר — די עבודה פון מכפירים יחידתי⁴³, די עבודה צו מתקן זיין דעם עצם הנפש⁴⁴.\nאבער מצד דעם גופא קומט ארויס אן עילוי אין צווייטן קצה — אז דוקא דורך דעם ווערט די יציאת מצרים אויך פון דער דרגא, מען גייט ארויס פון די מדידות והגבלות וואס קענען זיין אויך אויף עצם הנפש — דורך דערלאנגען אין דעם עצם פון נפש האלקית⁴⁵ וואס האט ניט קיינע הגבלות⁴⁶,\nאון דאס ברענגט צו יציאת מצרים אין אלע דרגות, ולגמרה — צו יציאת „מצרים\" פון מצרים דגלות זה האחרון בגשמיות, כימי צאתך מארץ מצרים אראנו נפלאות⁴⁷.\n(משיחות ליל ב׳ דפסח תש״ד, אחש״פ תשח״י)",[["37","37","ראה המשך תער״ב פרק ריד."],["38","38","יתרו יח, ד. וראה פסיקתא פ׳ פרה ובמדב״ר פ׳ חוקת (פי״ט, ז)* שאמר הק׳ למשה חייך שיצא מחלציך שנאמר ושם האחד אליעזר. והאריך בזה במבוא הרד״ל לפדר״א."],["39","39","שהוא סתם ר״א — ראה סה״ד בערכו, ובמבוא הרד״ל לפדר״א אם הי׳ כהן, לוי כו׳."],["40","40","ראה בכורים פ״א מ״ד. תשובות הרמב״ם (ירושלים תש״כ) כרך ב׳ סי׳ רצג."],["41","41","תניא ספכ״ד (לא, א)."],["42","42","ראה סה״ד בערכו. *) וכ״ה בפסיקתא דר״כ שם ובתנחומא חוקת ח."],["43","43","נתבאר בלקו״ת ראה כה, א ואילך."],["44","44","להעיר מהידוע בענין מאמר ריב״ז (ברכות כח, ב) איני יודע באיזה דרך מוליכין אותי, שזהו מפני שלא ידע אם עובד ה׳ גם מצד עצם נפשו כו׳."],["45","45","להעיר מהידוע (שע״ת חינוך פמ״ח) במעלת „בכל מאדך\" דבעת״ל לגבי צדיקים."],["46","46","להעיר מד״ה אור לי״ד הש״ת רפ״ו, דבהתקשרות עצמי דנפה״א א״צ בדיקה כו׳, עיי״ש."],["47","47","מיכה ז, טו."]]],[1300161109,"<h3>בא</h3>\nא. אין אנפאנג הלכות קדוש החדש זאגט דער רמב״ם: „חדשי השנה הם חדשי הלבנה שנאמר¹ עולת חודש בחדשו ונאמר² החודש הזה לכם ראש חדשים .. והשנים שאנו מחשבין הם שני החמה שנאמר³ שמור את חודש האביב״.\nדער פירוש דערפון: „חדש הלבנה״ באשטייט פון לערך ניין און צוואנציק מיט א האלב טעג⁴, אזויפיל דויערט דער סיבוב פון דער לבנה; „שנת חמה״ באשטייט לערך פון דריי הונדערט מיט פינף און זעכציק און א פערטל טעג⁵, דאס איז דער זמן פונעם סיבוב (שנתי) פון דער זון.\n— און דער רמב״ם אין דער הלכה הנ״ל זאגט צוויי דינים⁶:\nא) אז די „חדשי השנה״ דארפן גע־רעכנט ווערן לויטן סיבוב הלבנה: דאס הייסט, אז א חודש איז ניט א צוועלפטל פון שנת החמה [ווי עס רעכענען די רוב האומות, וואס צעטיילן דעם יאר (פון מהלך חמה) אויף צוועלף חלקים — חדשים], נאר „חדשי הלבנה״.\nב) אעפ״כ, וויבאלד אז פסח מוז זיין בזמן האביב⁷, און די תקופות השנה זיינען באשטימט דורך (מהלך ה)חמה (וואס א שנת חמה איז מיט לערך עלף טעג לענגער ווי א שנת לבנה⁸) — רעכנט מען די יארן לויטן מהלך החמה. און דערפאר, איז יעדערע צוויי־דריי יאר מאכט ב״ד אן עיבור־יאר, „כדי שיהי׳ הפסח בזמן האביב״⁹.\nאון דער רמב״ם איז ממשיך אין די ווייטערדיקע פרקים, אז אויך דער חשבון וועלכן מיר נוצן היינט [וואס רבי הלל הנשיא האט מסדר געווען¹⁰] איז אויסגעשטעלט אין אזא אופן, אז יעדער מחזור (19 יאר) גלייכן זיך אויס (לערך) די שנות הלבנה מיט די שנות החמה, ביז אז „לא ישאר ממנין ימי החמה בכל תשע עשרה שנה חוץ משעה אחת וארבע מאות ושמונים וחמשה חלק־ים״¹¹.\nפרעגט אויף דעם דער „פירוש״¹², אז „אחר שנים רבות״ (ווען עס וועט זיך צונויפקלייבן א גרויסע צאל פון די יתרונות פון דער שעה מיט תפ״ה חלקים) וועט אויסקומען תקופת ניסן (ניט בחודש האביב, נאר) אין חודש אייר? און ענטפערט: „יבוא מורה צדק ויודיענו״.\n[ולהעיר: ביז צום לעצטן יאר פון שית",[["1","1","פנחס כח, יד."],["2","2","פרשתנו יב, ב."],["3","3","ראה טז, א."],["4","4","במהלכם האמצעי תשעה ועשרים יום י״ב שעות .. תשצ״ג חלקים (רמב״ם שם פ״ו ה״ג)."],["5","5","ראה רמב״ם שם רפ״י. לקמן בפנים השיחה."],["6","6","ראה ב„פירוש״ לרמב״ם הל׳ קדה״ח בתחלתן. וראה ראב״ע פרשתנו שם. ובכ״מ."],["7","7","ר״ה כא, א. סנהדרין יג, ב. רמב״ם שם רפ״ד."],["8","8","רמב״ם שם פ״א ה״ב."],["9","9","לשון הרמב״ם שם פ״ד ה״ב."],["10","10","ראה בעל המאור ר״ה (כ, ב). רמב״ן גיטין לו, א. השגות הרמב״ן לסהמ״צ מ״ע קנג. חי׳ הר״ן סנהדרין יא, א־ב. חינוך מצוה ד׳. ובכ״מ. וצע״ק שברמב״ם בהל׳ קדה״ח אינו. וראה שם פ״ה ה״ג. הי״ג. סהמ״צ שם. וראה סהד״ץ ד״א קי״ח. ועוד. תו״ש בא חי״ג פ״ב ואילך, וש״נ."],["11","11","רמב״ם שם פ״ו ה״י."],["12","12","בפ״ט ה״ג שם."]]],[1300161110,"אלפי שנין דהוה עלמא וועט די תקופה אויספאלן נאך אלץ¹³ בחודש ניסן¹⁴].\nוצריך להבין: דער דין פון „שמור את חודש האביב״ איז (ניט נאר אז ניסן דארף זיין בזמן האביב, נאר) אז פסח זאל זיין בזמן האביב [און ווי דער רמב״ם פסק׳נט, כנ״ל, אז בשעת ב״ד האט אויסגערעכנט אז תקופת ניסן וועט אויספאלן „בששה עשר בניסן״ פלעגט מען מעבר זיין דעם יאר „כדי שיהי׳ הפסח בזמן האביב״] — איז ניט מובן:\nמצד דער פילמאליקער צונויפזאמ־לונג פון שארית המחזור (א שעה מיט תפ״ה חלקים) ביז איצט [און אפילו בזמן הרמב״ם (און נאך פריער)] איז שוין תקופת ניסן פיל מאל¹⁵ אויסגעפאלן א צאל טעג נאך ט״ו ניסן¹⁶ — איז ווי שטימט עס מיטן דין פון „שמור את חודש האביב״, אז פסח דארף זיין בזמן האביב?\nב. לכאורה האט מען געקענט פאר־ענטפערן דערמיט וואס דער רמב״ם זאגט ווייטער¹⁷, אז דער איבערבלייב פון א שעה מיט תפ״ה חלקים נאך יעדן מחזור איז נאר לויטן חשבון (וואס ווערט אנגערופן „תקופת שמואל״) אז שנת החמה איז „שס״ה יום ורביע יום״. אבער לויט דעם חשבון („תקופת רב אדא״) אז שנת החמה איז שס״ה יום ו„פחות מרביע יום״ — איז „לא תמצא תוספת במחזור של י״ט שנה כלל״.\nועפ״ז שטימט דער חשבון השנים וואס מיר רעכענען איצטער מיטן דין פון „שמור את חודש האביב״ — ווייל מיר נעמען אן (ניט דעם חשבון פון תקופת שמואל, נאר) דעם חשבון פון תקופת רב אדא [וואס „חשבון זה הוא האמת יותר מן הראשון״¹⁸] ווי עס שטייט אין כמה ראשונים¹⁹, און לויט „חשבון זה״ פאלט אויס פסח אלעמאל בתקופת האביב.\nס׳איז אבער ניט מובן: דער טעם פאר־וואס מ׳דארף משווה זיין שנות הלבנה מיט שנות החמה איז צוליב „שמור את חודש האביב״, און וויבאלד אז לויטן חשבון פון תקופת שמואל איז נאך יעדער מחזור דא א איבערבלייב — טא ווי זאגט דער רמב״ם²⁰ „ולמה סמכנו על מנין זה .. (וויבאלד אז) לא ישאר ממנין ימי החמה .. חוץ משעה אחת וכו׳״: ווי איז שייך צו סומך זיין אויף דעם „מנין״, וויבאלד אז די השתוות איז ניט (אינ־גאנצן) בהתאם מיטן דין פון „שמור את חודש האביב״?\nג. ויש לומר הביאור בזה: פון לשון הרמב״ם „והשנים שאנו מחשבין הם שני החמה שנאמר שמור את חודש האביב״, איז מובן, אז דער לימוד פון „שמור את",[["13","13","ראה ספר עתים לבינה מאמר יב."],["14","14","ראה בעתים לבינה שם שמפרש שזוהי הכוונה בתירוץ ה„פירוש״ „יבוא מורה צדק ויודיענו״."],["15","15","בהשנים שבאמצע המחזור, כבהערה הבאה."],["16","16","ראה בספר העבור לראב״ח הנשיא (מאמר ג׳ שער ה׳) דבזמנו („אשר חי בשנת ארבעת אלפים ושמונה מאות ושמונים ושלש ליצירה״ — נוסח השער), „מועד הפסח כולו נופל בתקופת טבת כגון שנה חמישית ושנת שלשה עשרה ושנת י״ז שאתה מוצא בכולם תקופת ניסן נופלת אחר כ״ב יום מניסן כו׳״. וראה גם ספר העבור להראב״ע (סוד העבור „העד האחד״ ושם בסופו „העד השביעי״). יד רמ״ה לסנהדרין (יג, ב ד״ה ואיכא דקשיא). יסוד עולם מאמר ד׳ (פ״ב, פי״ד ועוד). ובכמה מפרשים וספרי חשבון העיבור."],["17","17","רפ״ט שם."],["18","18","לשון הרמב״ם שם פ״י ה״ו."],["19","19","שנסמנו בהערה 16. ועוד."],["20","20","בפ״ו ה״י שם."]]],[1300161111,"חודש האביב״ איז ניט נאר אז פסח דארף זיין בזמן האביב, נאר אויך אז אלעמאל דארף אויסקומען פסח אומגע־פער אין זעלבן זמן (פון שנת החמה)²¹.\nאון אין דעם דין פון „שמור את חודש האביב״ בשייכות צו די שנים איז גענוג „שיהי׳ חודש זה (ניסן) בזמן האביב״²² — אז דער חודש ניסן זאל אין זיך האבן דעם זמן האביב²³. ובמילא איז בנוגע דעם דין גענוג אז די תקופת האביב זאל זיין בחודש ניסן אפילו ווען זי איז בסוף החודש.\nוואס עפ״ז קומט אויס, אז אויך לויטן חשבון פון תקופת שמואל, אז אין יעדער מחזור בלייבט א קליינע שארית, איז דורכן אויסשטעלן פון שנות המחזור באווארנט געווארן דער דין פון „שמור את חודש האביב״ בנוגע צו שנה (עכ״פ), היות אז אויך לויט דעם חשבון וועט די תקופה זיך קיין מאל ניט פארציען נאך חודש ניסן.\nאון דערמיט איז אויך פארשטאנדיק וואס דער רמב״ם זאגט דעם טעם פאר־וואס „סמכנו על מנין זה״ (דער מנין פון שנות המחזור) — ווייל לויט דעם חשבון „לא ישאר ממנין ימי החמה חוץ משעה אחת כו׳״: „סמכנו על מנין זה״ (פון שנות המחזור) ווייל דורך „מנין זה״ ווערט באווארנט דער דין אז די שנים דארפן זיין „שני החמה״²⁴; און אין דעם איז אויך דער חשבון אז „לא ישאר כו׳ חוץ משעה אחת כו׳״ א טעם מספיק אויף „סמכנו על מנין זה״, כנ״ל.",[["21","21","ועפ״ז יובן מ״ש הרמב״ם (שם פ״ד סה״א) „מפני מה מוסיפין חדש זה מפני זמן האביב כדי שיהא הפסח באותו זמן .. ולולא הוספת החודש הזה הפסח בא פעמים בימות החמה ופעמים בימות הגשמים״ — ולכאורה א״מ: (א) מה מוסיף הרמב״ם במ״ש „ולולא הוספת החודש הזה כו׳״, על מה שכתב לפנ״ז „מוסיפין חודש זה מפני זמן האביב״? (ב) מהו אומרו „פעמים בימות החמה ופעמים בימות הגשמים״, שמלשון זה משמע שהדיוק הוא לא — בזמן האביב, כ״א — שלא יהי׳ „פעמים בימות החמה פעמים בימות הגשמים״? וי״ל שב׳ לשונות אלו הם ב׳ דינים: „ומפני מה מוסיפין כו׳״ הוא דין בשנה שתקופת ניסן מתאחרת אחרי ט״ו ניסן; ו„ולולא הוספת החדש הזה כו׳״ הוא דין בנוגע כללות השנים, שמזמן לזמן צריך לעבר את השנה בכדי שהפסח שבכל השנים יהי׳ בזמן אחד (ושלא יהי׳ „פעמים בימות החמה ופעמים בימות הגשמים״)."],["22","22","לשון הרמב״ם שם פ״ד ה״א. וראה הערה הבאה."],["23","23","ויש לומר, דמה שמעברין על התקופה, היא „כדי שיהי׳ הפסח בזמן האביב״ (רמב״ם שם פ״ד ה״ב), משא״כ מה שמעברין על האביב ועל פירות האילן הוא „כדי שיהיו השנים שני החמה״ (רמב״ם שם סוף ה״ד •). ועפ״ז יובן גם מ״ש הרמב״ם שם ה״ג „כדי שיהי׳ האביב מצוי להקריב ממנו עומר התנופה בששה עשר בניסן״ — דלכאורה: הרי מה שמעברין על כל ג׳ הסימנים הוא מצד „שמור את חודש האביב״ שנוגע לפסח, ולמה אומר „כדי שיהי׳ .. להקריב ממנו עומר״? וי״ל בזה, כי אלולי טעם זה (כדי שיהי׳ כו׳ להקריב ממנו עומר) הי׳ מספיק גם כשהאביב הוא בסוף חודש ניסן (מכיון שגם אז היא שנת החמה, כבפנים)."],["24","24","להעיר מחמרא וחיי סנהדרין שם בשם הרא״ש. •) ומזה שבהלכה זו (ה״ד) מביא הרמב״ם רק ב׳ הסימנים דאביב ופירות האילן — משמע קצת, שכוונתו ב„ואלו הן הדברים״ היא (בעיקר) לענין ב׳ סימנים אלו. משא״כ מה שמעברין על התקופה הוא לא רק „כדי שיהיו השנים שני החמה״ אלא גם „כדי שיהי׳ הפסח בזמן האביב״. ויש לומר, שב׳ הלשונות שברמב״ם שם ה״א „שיהא הפסח באותו זמן״, „שיהי׳ חודש זה בזמן האביב״ — הם הקדמה לב׳ הענינים שבב׳ הלכות שלאח״ז: עיבור מפני התקופה (שבהלכה ב׳) — הוא „כדי שיהא הפסח באותו זמן״ (אביב); מפני האביב ופירות האילן (שבהלכה ג׳) הוא כדי „שיהי׳ חודש זה בזמן האביב״."]]],[1300161112,"ד. מען דארף אבער פארשטיין: ווי־באלד אז צוליב דעם דין פון „שמור את חודש האביב״ בנוגע פסח מוז מען פארט אנקומען צום אמתי׳ן חשבון (פון תקופת²⁵ רב אדא)²⁶, וואס דוקא דאן איז „לא תמצא תוספת במחזור .. כלל״ — טא צוליב וואס דארף דער רמב״ם זאגן אז בנוגע דעם ענין פון „שנה״ איז דאס אויסגעהאלטן אויך לויטן חשבון פון תקופת שמואל — וואס איז ניט כפי האמת?\nאיז נקודת הביאור אין דעם:\nפון דעם גופא, וואס דער רמב״ם ברענגט אויך תקופת שמואל אין הלכות קדוש החודש, איז מוכח אז אויך די תקופה איז (ניט נאר א דיעה אין תורת אמת, נאר אויך אז זי איז) אויסגעהאלטן אין פסק ההלכה (וואס הלכה איז אן ענין פון „אמת לאמיתו״²⁷).\n[און ווי דער רמב״ם איז מרמז מיטן לשון²⁸ „שחשבון זה הוא האמת יותר מן הראשון״: אויך דער חשבון „הראשון״ (תקופת שמואל) — איז אמת; אבער „חשבון זה״ (תקופת רב אדא) איז „אמת יותר״]²⁹.\nא ראי׳ אויף דעם (אז אויך דער חשבון פון תקופת שמואל איז אנגענומען לפסק הלכה): אין כמה הלכות וואס זיינען פארבונדן מיט תקופת החמה רעכנט מען זיך נאר מיט תקופת שמואל; אזוי ווי ברכת החמה, לדוגמא — די ברכה וואס מען מאכט ווען מ׳זעט די חמה אין טאג פון תקופת ניסן ביים אנהויב פון יעדן מחזור גדול (28 יאר) ווען די תקופה איז „בתחילת ליל רביעי״³⁰ — וואס דאן איז די תקופה לויטן חשבון פון שמואל און ניט לויטן חשבון פון תקופת רב אדא³¹.\n[און דאס זעלבע איז אויך בנוגע צו שאלת גשמים³², און זהירות אין שתיית",[["25","25","ביד רמ״ה (סנהדרין שם ד״ה ואיכא) מקשה שגם לפי תקופת רב אדא נופלת (לפעמים) תקופת ניסן (בשנת ט״ז למחזור) ביום ט״ז. אבל עפמ״ש הרמב״ם שם ספ״י: וחשבון שתי התקופות האלו שביארנו (דשמואל ורב אדא) דרכם הכל בקירוב הוא ובמהלך השמש האמתי לא במקומה האמתי, אבל במקום השמש האמתי תהי׳ תקופת ניסן בזמן אלו בכמו שני ימים קודם שתי התקופות, נמצא לכאורה דחגה״פ הוא לאחר התקופה •• (ראה יסוד עולם שם. הון עשיר לערכין פ״ב מ״ב. ועוד). וראה הערה הבאה."],["26","26","או י״ל, מדלא הזכיר הרמב״ם בפירוש דסמכינן על חשבון תקופת ר״א בנוגע לפסח• (והזכיר רק ש„סמכנו על מנין זה״), דס״ל כהדיעות דעכשיו אין חוששין להדין דפסח יהי׳ אחר התקופה דוקא (ראה פנ״י ר״ה כא, א ד״ה „בתוס׳ בד״ה עברה״. פי׳ ר״ח שם. חמרא וחיי שם בשם הרא״ש). •) ביד רמ״ה שם מתרץ דמש״כ בגמרא (ר״ה כא, א) כד חזיא דמשכא תקופת טבת עד שיתסר בניסן עברה, היינו „עד אורתא דשיתסר נגהי שיבסר״. אבל ברמב״ם מפורש שם (ה״ב) „אם תהי׳ תקופת ניסן בששה עשר״. ••) והאיחור דתקופה תשרי בנוגע לזג, אולי ס״ל להרמב״ם דלא איכפת ולא מעברין בשביל זה. מדלא הביאו ברפ״ד שם. וראה צפע״נ שם ה״ב (וראה שם ה״ג). מנ״ח מצוה ד׳ סק״י. ערוך לנר סנהדרין יג, א ד״ה רבי יוסי. ועוד. •) ולכאורה דוחק לומר דסמיך עמ״ש בפ״י ה״ו. וראה הון עשיר שם."],["27","27","ראה המשך תרס״ו ע׳ תלא ואילך."],["28","28","בפ״י ה״ו."],["29","29","ובפרט להפי׳ ברמב״ם (פ״ה ה״ב, וראה ספר המצות שם) ודבר זה הלכה למשה מסיני הוא כו׳ ובזמן שאין שם סנהדרין קובעין על פי החשבון הזה (המבואר בפ״ו שם) שגם החשבון עצמו הוא הלל״מ — וידוע השקו״ט בזה."],["30","30","ברכות נט, ב. רמב״ם הלכות ברכות פ״י הי״ח. טושו״ע או״ח סי׳ רכט ס״ב."],["31","31","ראה שו״ת משאת בנימין סי׳ קא. שיירי כהנ״ג לטור שם. שו״ת חת״ס או״ח סנ״ו."],["32","32","תענית י, א. טושו״ע או״ח (ואדה״ז) סי׳ קיז ס״א."]]],[1300161113,"מים בשעת התקופה³³, וואס אין די הלכות רעכנט מען זיך נאר מיט תקופת שמואל³⁴].\nה. וועט מען דאס פארשטיין בהקדים נאך אן ענין וואס איז, לכאורה, ניט מובן אין קדוש החודש: „ב״ד³⁵ שקדשו את החדש, בין שוגגין בין מוטעין בין אנוסים [לויט א צווייטער גירסא³⁶: מזידין] הרי זה מקודש וחייבין הכל לתקן המועדות על היום שקדשו בו״.\nולכאורה: דער תוכן וענין פון ראש־חודש (מלשון חידוש) איז פארבונדן מיט חידוש (מולד) הלבנה — טא ווי איז שייך אז דער טאג אין וועלכן ס׳איז ניט געווען דער מולד זאל ווערן ר״ח מצד דעם וואס ב״ד האבן אים מקדש גע־ווען?\nדער רמב״ם³⁷ איז מסביר דעם טעם פון דעם פסק הלכה, אז „חייבין הכל לתקן המועדות על היום כשקדשו בו״, ווייל „מי שצוה לשמור המועדות הוא צוה לסמוך עליהם״. אבער דאס איז לכאורה נאר א טעם מספיק פארוואס מ׳איז מחויב צו פארלאזן זיך אויפן קידוש החודש פון ב״ד, ס׳בלייבט אבער ניט מובן דער עצם הענין: ווי אזוי ווערט דער טאג „ראש חודש״, אויב דער מולד איז אין אן אנדער טאג?\nו. דער ביאור אין דעם (בדרך אפשר):\nחמה ולבנה און עניניהם דא למטה (אזוי ווי אלץ וואס איז דא למטה) ווערן נשתלשל פון בחי׳ חמה ולבנה ועניניהם למעלה. ובמילא, דאס וואס דער טאג פון מולד הלבנה ווערט באשטימט אלס ר״ח, נעמט זיך עס בעיקר מצד דעם מולד הלבנה שלמעלה.\nאבער וויבאלד אז אונזער דערוויסן זיך און אונזער השגה אין די ענינים שלמעלה איז דורך די ענינים ווי זיי ווערן נמשך דא למטה — דערפאר האט אונז די תורה אנגעזאגט אז מיר זאלן קובע זיין ר״ח לויטן מולד הלבנה שלמטה (ע״פ הראי׳, אדער ע״פ חשבון) ווייל פון דעם ווייסן מיר אז דעמאלט איז דער מולד הלבנה שלמעלה.\nאין פאל אבער ווען ב״ד האט באשטימט ר״ח אין אן אנדער טאג און די תורה הייסט אונז „לסמוך עליהם״, איז דאס גופא א הוכחה, אז דוקא אין דעם טאג, וועלכן תורת אמת איז קובע אלס „ראש חודש״, איז דער מולד הלבנה (העיקרי—) שלמעלה.\n[און דאס וואס למטה איז דעמאלט דער מולד אין אן אנדער טאג, איז עס דערפאר וואס דער עולם הזה התחתון איז (צוליב סיבות שונות) דעמאלט³⁸ ניט ראוי³⁹, אז די המשכה פון בחי׳ לבנה שלמעלה זאל אראפקומען אין דער לבנה שלמטה אין זעלבן זמן].",[["33","33","ראה ב״י או״ח סו״ס תנה. רמ״א שם ס״א (שו״ע אדה״ז שם סט״ו־טז. סר״ג סי״ד). יו״ד סקט״ז ס״ה. ובכ״מ."],["34","34","ראה יסוד עולם מאמר ד׳ פי״ב בסופו ועוד. תשובות התוו״ט (בשו״ת הצ״צ (הישן) סי״ד). וראה ספר העבור להראב״ע שם והעד השביעי (הובא בט״ז יו״ד שם). וראה בכל הנ״ל ישועות יעקב או״ח סי׳ קיז בתשובה לנכד המחבר."],["35","35","רמב״ם ספ״ב שם. מתו״כ אמור כג, ד. ר״ה כה, א."],["36","36","ר״ה שם, וראה הגהות מיימוניות שם."],["37","37","ספ״ב שם."],["38","38","להעיר מהשייך לנדו״ד, לכאורה, ונת׳ באופן אחר לגמרי (בנוגע החילוק בזמנים ומועדים שישנו תמיד) — שו״ע אדה״ז מהד״ת ס״א ס״ח. תורת חיים (לאדהאמ״צ) שמות שמט, ב ואילך. — וי״ל."],["39","39","עד״ז מצינו (ויתרה מזה): ויהי הגשם גו׳ הורידן ברחמים כו׳ גשמי ברכה כשלא חזרו היו למבול (ז״ח נח כב, א. רש״י נח ז, יב)."]]],[1300161114,"ועד״ז איז אויך בנוגע צו די אויבנ־דערמאנטע דינים וואס זיינען פאר־בונדן מיט תקופת החמה [ברכת החמה וכו׳]: די דינים פון תורת אמת זיינען (בעיקרם) פארבונדן מיט תקופת החמה שלמעלה. דעריבער איז קיין קשיא ניט וואס ביי די דינים ווערט אנגענומען דער חשבון פון תקופת שמואל — כאטש אז דער חשבון האמיתי פון דער תקופה למטה איז לויט תקופת רב אדא — וארום וויבאלד תורת אמת זאגט, אז נאך יעדע 28 יאר איז די הלכה כך וכך און זי איז פארבונדן מיט דער תקופה, איז דערפון גופא מוכח, אז אין דעם זמן איז די תקופה שלמעלה. ס׳איז נאר וואס צוליב געוויסע סיבות קומט אראפ די תקופה דא למטה אין אן אנדער זמן (תקופת רב אדא)⁴⁰.\nז. לאחרי כהנ״ל פאדערט זיך נאך ביאור:\nאלע ענינים וואס שטייען אין תורה, ובפרט אזעלכע וואס זיינען להלכה במעשה בפועל — איז אין מקרא (דהפס״ד) יוצא מידי פשוטו, און מ׳דארף מקיים זיין די הלכה כפשוטה. כאטש אז יעדער ענין (אין עולם ובפרט אין תורה) איז זיין שורש למעלה ורוחני.\n[און דאס איז ניט נאר בנוגע לקיום המצות, אז דוקא דורך זייער קיום כפשוטן „נעמט מען״ אויך די ענינים הרוחניים פון מצות [אזוי ווי מצות תפילין, לדוגמא, וואס דוקא דורך קיום מצות תפילין כפשוטה איז מען ממשיך דעם ענין פון ד׳ מוחין וכו׳], נאר אויך בנוגע אלע זאכן און ענינים וואס ווערן געבראכט און אנגעזאגט אין תורה, איז, כנ״ל, אין מקרא יוצא מידי פשוטו⁴¹].\nועפ״ז איז שווער צו פארשטיין: דער ענין פון „הרואה חמה בתקופתה״ מיינט דאך די תקופת החמה בגשמיות — איז ווי איז שייך אז מען זאל מאכן א ברכה „עושה מעשה בראשית״⁴² אויף דער תקופה שלמעלה, בשעת אז דא למטה איז (אין דעם זמן) ניטא קיין תקופה (בגשמיות)?⁴³\nח. ואע״פ אז אויך ביי קידוש החודש איז דא א הכרח אזוי צו זאגן (כנ״ל סעיף ו) — אז דער קידוש וקביעות פון ר״ח איז ניט אפהענגיק אין זמן פון מולד הלבנה שלמטה — איז אבער דא א חילוק צווישן דעם ענין פון ר״ח און תקופת החמה:\nכאטש ר״ח איז פארבונדן מיט מולד הלבנה — איז ער אבער בעצם מהותו (ניט קיין מציאות פון וועלט, נאר) א תורה׳דיקע מציאות⁴⁴. דאס וואס עס איז א יום קדוש, קרבנות ר״ח וכו׳, וואס ב״ד האט מקדש געווען⁴⁵ אדער",[["40","40","להעיר מספר הזכרונות (להרה״צ ר׳ צדוק הכהן) קונטרס משיב הטענה על חשבון העבור והתקופה. ספר העבור לראב״ע שם בסופו."],["41","41","ולכן כאשר חכמי האומות אומרים ע״ד מאורע וענין בעולם שהוא שונה ממש״נ בתורה — אא״פ לתרץ שבתורה מדובר רק ברוחניות הענינים. וכמדובר כמ״פ ההכרח לזה מסיפור הש״ס (בכורות ח, ב) שגם כאשר אמרו חכמי אוה״ע שהבחינו שנחש מתעבר לתלת שנה ענה להם ר״י בודאות שאינו, והביא הוכחה מפסוק וק״ו שהוא „לשב שני״ (והמדובר הי׳ בעיבור דנחש כפשוטו)."],["42","42","ב׳ גי׳ בהברכה — הובאו באנצקלופדי׳ תלמודית בערכו. וראה לקו״ש ח״י ע׳ 187."],["43","43","ראה שו״ת חת״ס שם דנשאר בצע״ג דדברי הרמב״ם סתרי אהדדי. (ועיי״ש שכתב „איך נברך וע״פ אמת אין כאן שום תקופה״)."],["44","44","בפרט לביאור הרגצובי בנוגע למולד הלבנה (צפע״נ לרמב״ם ריש הל׳ קדה״ח) שמדגיש הרמב״ם „במראה הנבואה״."],["45","45","ולדעת הרמב״ם אמירת ב״ד מקודש — מעכב — שם פ״ב ה״ח (ושם „שאין הראי׳ קובעת אלא ב״ד שאמרו מקודש הם שקובעין״). וראה ספהמ״צ שם. (וראה השגות הרמב״ן שם. ולהעיר"]]],[1300161115,"„קדשוהו שמים״⁴⁶. דעריבער איז לייכטער צו פארשטיין, ווי די מציאות פון ר״ח איז פארבונדן מיט מולד שלמעלה, אויך ווען דער מולד שלמטה איז אין אן אנדער זמן:\nמשא״כ „חמה בתקופתה״, וואס איר מציאות שאפט זיך (ניט פון די דיני התורה וואס זיינען פארבונדן דערמיט, נאר) פון דעם מהלך החמה — דאס וואס די זון געפינט זיך אין דעם זעלבן זמן אויפן זעלבן ארט ווי זי איז געווען בעת זי איז באשאפן געווארן.\nאיז דאך ניט מובן: וויבאלד אז אין דין תורה גופא איז נוגע די מציאות ווי זי איז דא למטה (כנ״ל ס״ז) — טא ווי איז שייך צו מאכן ברכת החמה אויף דער „חמה בתקופתה״ שלמעלה?\nדי קשיא איז נאך שטארקער: דער דין פון ברכת החמה איז ווען מ׳איז „רואה חמה בתקופתה״, און בשעת מען זעט ניט די חמה בגשמיות טאר מען קיין ברכה ניט מאכן⁴⁷:\nדי ברכה איז פארבונדן מיט זען די גשמיות׳דיקע זון, כאטש זי איז ניט (ווי בתקופתה (און מען מאכט די ברכה צוליב דעם וואס די חמה רוחנית איז בתקופתה)⁴⁸?\nט. וי״ל בזה. ובהקדים, וואס דער חשבון התקופות (סיי לויט תקופת שמואל, סיי לויט תקופת רב אדא) הייבט זיך אן ניט פון דער ערשטער תקופה פון נאך בריאת העולם, נאר פון דער תקופה אין „שנת תוהו״, איידער די וועלט איז באשאפן געווארן⁴⁹.\nאון די הסברה אין דעם איז:\nוועגן דער פלוגתא⁵⁰ צווישן ר״א און ר״י, צי בתשרי נברא העולם אדער בניסן נברא העולם, איז מבואר⁵¹ בכ״מ [וי״ג⁵² אזוי אין תוספות⁵³], אז ביידע דיעות זיינען אמת: בניסן איז עלה במחשבה לברוא את העולם און די בריאה בפועל איז געווען בתשרי.\nאון וויבאלד אז לתקופות קיי״ל ווי ר׳ יהושע, אז בניסן נברא העולם, וואס דעריבער רעכנט מען תקופת ניסן ד„שנת תוהו״ (שלפני תשרי) ווען עלה במחשבה לברוא,\nדעריבער איז בנוגע צו ברכת החמה, רעכנט מען זיך מיט דער תקופה שלמעלה (אע״פ אז די תקופה איז אין אן אנדער זמן). ועד״ז איז מובן בנוגע די אנדערע דינים וועלכע זיינען פאר־",[["","","שגם לדעת הרמב״ן שם שאין קידוש ב״ד מעכב, הרי צריכים ב״ד עכ״פ לחשוב בהן ולהסכים בהן). „וזה שאנו מחשבין בזמן הזה כו׳ אנו מחשבין לידע יום שקבעו בו בני ארץ ישראל איזה יום הוא, וקביעת בני ארץ ישראל אותו הוא שיהי׳ ר״ח או יו״ט לא מפני החשבון שאנו מחשבין״ (שם ספ״ה). ובאריכות יותר בספר המצות שם „אבל מפני שב״ד הגדול שבארץ ישראל כבר קבעוהו זה היום ר״ח או יו״ט ומפני אמרם כו׳ כמו שבא בפירוש אלה מועדי ה׳ .. שיאמרו הם כו׳״."],["46","46","ר״ה כד, א (במשנה). סנהדרין יוד, ב, בחודש שלא נראה בזמנו, וכ״ה דעת הרמב״ם שם פ״ב ה״ח. ראה פירוש שם. וראה צפע״נ הל׳ קדה״ח שם. פ״ב ה״ח. פ״ה ה״א. מכתבי תורה מכ׳ סג."],["47","47","ראה שו״ת חת״ס שם בתחלתו. שע״ת או״ח שם סק״ג. שד״ח אס״ד מערכת ברכות ס״ב אות יח. פאת השדה סל״ג."],["48","48","להעיר מהסברא ד„ת״ח אחד״ בשו״ת חת״ס שם לברך אפילו לא תראה החמה. וראה שד״ח שם. בשו״ת כתב סופר (או״ח סל״ד) פוסק כהפמ״א (הובא בשד״ח שם). וראה קונטרס תקופת החמה וברכתה (להרי״מ טוקצינסקי) פ״ד ס״ד וה׳."],["49","49","ראה תוד״ה לתקופות (ר״ה ח, א ואילך). פירוש להרמב״ם הל׳ קדה״ח פ״ט ה״ג. ופ״י. ועוד."],["50","50","ר״ה י, ב."],["51","51","ראה נהר שלום סדר כוונת ר״ה קרוב לסופו."],["52","52","הובא בשו״ת בני ציון ח״א סי״ד אות טז."],["53","53","ד״ה כמאן (ר״ה כז, א). ולפנינו הגי׳ להיפוך. וראה לקמן ע׳ 4-483 ובהערות שם."]]],[1300161116,"בונדן מיט דער תקופה, וואס איז נאר לויט תקופת שמואל, די תקופה שלמעלה, וויבאלד אז דער אנהייב און יסוד פון גאנצן חשבון התקופות איז אן ענין פון תקופת תוהו⁵⁴, פון עלה במחשבה⁵⁵ לברוא, און דעריבער איז דא ניט נוגע אז אויך די תקופה שבמעשה זאל זיין אין דעם זעלבן זמן.\nאבער פונדעסטוועגן איז מובן, אז די תקופה שלמעלה פועל׳ט אויך (ברוח־ניות ובפנימיות) אויף דער חמה למטה (וואס דערפאר איז ברכת החמה פאר־בונדן מיט ראיית החמה הגשמית).\nיו״ד. עפ״ז דארף מען פארשטיין, לאידך גיסא: וויבאלד אז דער ענין התקופה שלמעלה איז דוקא לויט דעם חשבון פון תקופת שמואל — און ניט פון תקופת רב אדא, וואס זיין חשבון איז נאר בשייכות צו דער תקופה שלמטה,\nאיז ווי איז שייך צו זאגן, אז דער ציווי פון תורה אז פסח מוז זיין דוקא בזמן האביב [וואס דאס קען געמאלט זיין נאר לויט תקופת רב אדא און ניט לויט תקופת שמואל (כנ״ל ס״ד)] איז פאר־בונדן נאר מיט דער תקופה שלמטה?\nאיז דער ביאור אין דעם:\nדער טעם הדבר, וואס די תקופה שלמטה איז אין אן אנדער זמן פון דער תקופה שלמעלה, איז ווייל עולם איז (כנ״ל) דאמאלס ניט ראוי צו אויפ־נעמען די תקופה שלמעלה (וואס איז העכער פון וועלט און איר סדר הזמנים).\nבמה דברים אמורים, ווען דאס איז א מציאות פון וועלט, אבער דער ענין פון פסח („שיהי׳ הפסח בזמן האביב״) — וויבאלד אז פסח איז א תורה׳דיקע מציאות, ווערט נמשך די תקופה למטה אין זעלבן זמן ווי זי איז למעלה, ד.ה. אז דאס וואס פסח איז בזמן האביב אלעמאל, איז עס (אויך) לויט דער תקופה שלמעלה.\nמשא״כ בנוגע עניני העולם, איז די המשכת בחי׳ התקופה שלמעלה אין אן אנדער זמן, לויטן חשבון פון תקופת שמואל.\nיא. עפ״ז ווועט מען פארשטיין וואס דער רמב״ם זאגט אז דאס וואס „סמכנו על מנין זה״ (בנוגע צום דין פון שנה, אז די שנה דארף זיין אזא יאר וואס איר חודש איז בזמן האביב) איז אויסגע־האלטן אויך לויטן חשבון פון תקופת שמואל — אע״פ אז בנוגע צום דין פון פסח (אז פסח דארף זיין בזמן האביב) מוז מען (סיי־ווי) אנקומען צום חשבון פון תקופת רב אדא:\nהיות אז בנוגע עניני העולם איז די המשכת התקופה שלמעלה לויטן חשבון פון תקופת שמואל (כנ״ל), דעריבער איז דער דין בנוגע „שנה״ (וואס איז א מציאות פון עולם), אז עס דארף זיין אויסגעהאלטן (אויך) לויט תקופת שמואל.\n(משיחת אחש״פ תשי״ג)",[["54","54","משא״כ חשבון המולדות והשנים אף שג״ז מונין ממולד תהו — בהר״ד (רמב״ם שם פ״ו ה״ח. תוס׳ שם. ובכ״מ), הרי זהו בעיקר כיון שיום אחד בשנה חשוב שנה, כ״ש חמשה ימים (ראה תוס׳ שם. פירוש לרמב״ם שם. ובכ״מ. נסמנו באנציקלופדי׳ תלמודית ערך בהר״ד), היינו מצד מציאות הבריאה והמולד בפועל. ועוד ועיקר: הרי בזה אין נפק״מ בפועל לחשבון המולדות, משא״כ בנוגע חשבון התקופות. עיי׳ תוס׳ שם. וראה בפירוש שם (פ״ט ה״ג. פ״י ה״א). יסוד עולם שם (פי״ד). ועוד."],["55","55","וכו״כ מצוות דינים ופס״ד תלוים במחשבה דוקא."]]],[1300161117,"<h3>בא ב</h3>\nא. אין דער היינטיקער סדרה, ביים ציווי אויפן קרבן פסח וואס דער אוי־בערשטער האט אנגעזאגט צו משה רבינו, זאגט דער פסוק: „בעשור לחודש הזה ויקחו להם איש שה לבית אבות שה לבית\"¹, און אין די ווייטער־דיקע פסוקים²: „והי' לכם למשמרת עד ארבעה עשר יום לחודש הזה ושחטו אותו כל קהל עדת ישראל בין הערביים . . ואכלו את הבשר בלילה הזה צלי אש ומצות על מרורים יאכלוהו\".\nדער רמב\"ם אין ספר המצות רע־כנט די מצוה פון קרבן פסח פאר צוויי מצוות³: איין מצוה — „לשחוט שה הפסח ביום ארבעה עשר בניסן בין הערביים והוא אמרו יתעלה ושחטו אותו כל קהל עדת ישראל בין הערביים\"⁴, און די צווייטע — „לאכול כבש הפסח בליל חמשה עשר מניסן בתנאיו הנזכרים . . והוא אמרו ואכלו את הבשר בלילה הזה גו'\".\nפרעגט מען דערויף די קשיא⁵: דער רמב\"ם האט אליין געגעבן דעם כלל⁶ אז „כל מה שבא לחכמים בו מאמר כי הענין פלוני ופלוני מעכבין זא\"ז הדבר ברור כי הוא מצוה אחת . . וכן כל אשר יתבאר לך כי התכלית המבוקש לא יגיע בחלק אחד מאלו החלקים אז ג\"כ הדבר ברור כי קבוצם הוא הענין אשר ימנה\"⁷. היינט ווי באלד אז בא קרבן פסח פסק'נט דער רמב\"ם אז אן אכילת הפסח איז ניט שייך די מצוה פון ק\"פ [— „נמנו עליו (אויפן קרבן פסח וואס „אינו נאכל אלא למנויו\"⁸) וחזרו אחרים ונמנו עליו ראשונים שיש להם כזית אוכלים ופטורים מעשות פסח שני ואחרונים שרבו עד שלא נמצא בו כזית לכל אחד אינן אוכלין וחייבים לעשות פסח שני\"⁹ —] — דארף דאך אויסקומען אז שחיטת און אכילת הפסח זיינען „מצוה אחת\" — היינט פארוואס טיילט ער זיי אין צוויי באזונדערע מצות?\nנאכמער: אפי' לויט די דיעות¹⁰ אז אכילת הפסח איז ניט מעכב די הקרבה איז דאך אבער דער תוכן, דער תכלית פון מצות הקרבת הפסח פארבונדן מיט",[["1","1","יב, ג."],["2","2","שם, ו. ח."],["3","3","מ\"ע נה-נו. וכ\"ה בחינוך מצוה ה-ו. וכן מנו כל מוני המצות (מלבד הרס\"ג — לדעת הרי\"פ פערלא מ\"ע מז). — בהבא לקמן עייג\"כ צל\"ח לפסחים (על אתר כמסומן לקמן) וכן בשיטה מקובצת (להרר\"י גרשוני)."],["4","4","בסהמ\"צ שלפנינו ליתא התיבות „והוא אמרו . . ושחטו כו'\"*, אבל כ\"ה בהוצאת העליר וקאפאח (וכן הובא בהמקור בל' ערבי). וכן מסתבר שהרי בכל המצות הביא הרמב\"ם המקור מהכתוב. וכן הביאו במנין המצות שבראש ספר היד."],["5","5","ר\"ד הבבלי בס' מעשה נסים סי' ה. ועד\"ז הקשה במעין החכמה — ראה לקמן הערה 23."],["6","6","סהמ\"צ שורש יא."],["7","7","כן הובא בס' מעשה נסים שם. ובסהמ\"צ שלפנינו הוא בשינוי ל' קצת."],["8","8","משנה זבחים נו, ב."],["9","9","רמב\"ם הל' ק\"פ פ\"ב הי\"ד. כדעת חכמים פסחים עח, ב. ר\"ד הבבלי הביא שם דין הנ\"ל, וגם מה שפסק הרמב\"ם (שם פ\"ד ה\"ב) דבנטמא בשר וזרק את הדם לא הורצה (וחייב בפסח שני כדעת חכמים שם). וראה לקמן הערה 16."],["10","10","ר\"נ ור\"י בפסחים שם ואילך. *) ואולי נגרמה ההשמטה (בטעות?) עי\"ז שבריש הל' ק\"פ לא הביא הכ' „ושחטו\". וראה בברית משה לסמ\"ג (מ\"ע רכג סוסק\"א) שהניח זה בצ\"ע."]]],[1300161118,"אכילת הפסח, ווארום פסח „לא בא מתחילתו אלא לאכילה\"¹¹ — און דער־פאר איז „הפסח שבא בטומאה נאכל בטומאה\"¹¹, ווארום „כשנצטווה עיקר פסח לאכילה נצטווה\"¹² — איז פאר־וואס זאלן זיי ניט נצטרף ווערן אלס איין מצוה?\nפארענטפערט אויף דעם ר\"א בן הרמב\"ם¹³, אז דער איינטיילן אין צוויי מצות איז צוליב דעם וואס די שחיטה איז „אפהענגיק\" אין איין זמן און די אכילה — אין אן אנדער זמן: מצות השחיטה איז ביום ארבעה עשר, און מצות האכילה איז בליל חמשה עשר¹⁴; און נאך וואס טיילט זיי פאנאנדער: שחיטת הפסח איז א „מצוה שיש בה כרת\", דאקעגן איז אכילתו גלייך צו אן־דערע מצות עשה, וואס זיינען ניט געבונדן מיטן עונש פון כרת: אויב ער האט מקריב געווען דעם קרבן פסח בזמנו און ער האט אים ניט געגעסן בליל ט\"ו, האט ער מקיים געווען די מצוה פון שחיטת הפסח און ער איז פטור פון כרת¹⁵, און דארף אויך ניט ברענגען קיין קרבן פסח שני¹⁶.\nב. עס איז אבער נאך אלץ ניט גלאטיק: לפי הר\"א בן הרמב\"ם איז מבואר (בעיקר) אז לויט דעת הרמב\"ם איז אכילת הפסח בפועל — ניט מעכב, וויבאלד אבער די אכילה איז דאך פארט דער תכלית פון שחיטת הפסח (און דעריבער דארף ער זיין ראוי לאכילה בשעת הקרבתו), האבן זיי געדארפט פאררעכנט ווערן ווי איין מצוה, ווי דער רמב\"ם אליין שרייבט אין שרשי המצות¹⁷ „שאפי' החלקים שאינן מעכבין זא\"ז פעמים יהיו מצוה אחת כשהי' הענין אחד\".\nאויך דעם טעם אז שחיטת הפסח ואכילתו זיינען באזונדערע מצות — ווייל יעדער פון זיי האט איר באזונדער זמן, פאדערט הסברא, ווארום מ'געפינט",[["11","11","משנה פסחים עו, ב."],["12","12","פרש\"י שם. ובפרש\"י שם (עח, ב. במשנה): דעיקר פסח לאכילת אדם קאתי. ול' הרמב\"ם שם: שאין הפסח בא אלא לאכילה."],["13","13","בספר מעשה נסים שם."],["14","14","ועיין ביראים סי' תה (בהשלם — סי' תטו) שמדגיש שזמנם אינם שווין. וכ' המפרשים (ברית משה לסמ\"ג שם. ועוד) שכוון לתרץ קושיא זו (וראה תועפות ראם שם. ועוד)."],["15","15","וכן מבואר מלשון הרמב\"ם שבמ\"ע נה, ובהל' ק\"פ פ\"א ה\"ב כ' דין כרת בפסח, ומי שעובר על ציווי זה ולא יקריבוהו בזמנו כו'. משא\"כ במ\"ע נו, וברפ\"ח שם. וכן מוכח מכ\"מ בדברי הרמב\"ם."],["16","16","ולפי\"ז צ\"ל שס\"ל שהדין שנמנו עליו וחזרו אחרים ונמנו — זה שאחרונים שלא נמצא בו כזית לכ\"א אינן אוכלים כו' הוא דין בשחיטתו, היינו דאם בעת שחיטתו אינם ראויים לאכול בו כזית• לא חל מתחילה המינוי שלהם (דאין שוחטין אלא למנויו — רמב\"ם שם רפ\"ב). וגם הדין שבפ\"ד ה\"ב שם, בנטמא בשר הפסח דאם זרק לא הורצה הוא לפי שנוסף על דעת ר' נתן (אליבא דרב) שם דבעינן שיהי' גברי דחזי לאכילה בשעת שחיטה וזריקה, ס\"ל להרמב\"ם (אליבא דרבנן שם) דבעינן שגם הבשר יהי' חזי לאכילה, אבל האכילה בפועל לא מעכבא. וכ\"כ גם בלחם משנה שם פ\"ג ה\"ד. וראה צפע\"נ הל' מתנות עניים פ\"ב הי\"א (לז, ב). ולפי\"ז צ\"ל, או שר\"ד הבבלי לא ס\"ל כן בפירוש דברי (רבנן ו)הרמב\"ם, וכמו שהאריך בזה בביאור הרי\"פ פערלא בסהמ\"צ לרס\"ג מ\"ע מז (שלדעתו הר\"ד הבבלי ורש\"י והרי\"ף, ס\"ל דאכילת פסח מעכבא, ואם לא הי' אנוס בזה גם חייב כרת), או שס\"ל דגם עיכוב כזה (שהבפועל אין מעכב) מורה שהיא מצוה אחת (כדלקמן בפנים)."],["17","17","סהמ\"צ שורש יא. וכמ\"ש ר\"ד הבבלי שם, שגם לדעת ר\"נ כו' שאכילתו אינו מעכב מוכח שהיא מצוה א'. •) וכידוע דעת הרמב\"ם (שם פ\"ב ה\"ג) דאם אין כ\"א יכול לאכול כזית אין שוחטין ולא כדעת רש\"י פסחים צא, א (במשנה): לאכול כזית בין כולם. כהובא בכ\"מ שם."]]],[1300161119,"דאך כמה מצוות¹⁸ וואס די פרטי המצוות האבן באזונדערע צייטן פון חיוב (און זיי זיינען ניט מעכב איינער דעם צווייטן)¹⁹, און פונדעסטוועגן רעכנט זיי דער רמב\"ם אלס איין מצוה²⁰.\nג. וועט מען דאס פארשטיין בהק־דים נאך א שאלה וואס מ'קען פרעגן אין דעם: בא קרבן חטאת שטייט אין פסוק²¹ „תשחט החטאת גו' הכהן המחטא אותה יאכלנה\", פונדעסטוועגן רעכנט ניט דער רמב\"ם אכילת החטאת אלס א מ\"ע בחטאת בפ\"ע, נאר ער איז דאס כולל צוזאמען מיט אכילת שאר קדשים²² [— „שצוה הכהנים לאכול בשר קדשים כלומר החטאת והאשם שהם קדשי קדשים כו' ושאר קדשים כלומר קדשים קלים . . אכילתם גם כן נגררת אחר המצוה\"²³] — איז ניט פארשטאנדיק\nפארוואס רעכנט דער רמב\"ם אכילת פסח אלס מ\"ע בפ\"ע און ניט אלס א פרט פון דער כללות'דיקער מצוה פון אכילת קדשים²⁴ [וואס פסח איז אויך קדשים (קלים)]²⁵?",[["18","18","כמו בק\"ש שחרית וערבית, תמידים בבוקר ובין ערביים, קטורת כו'."],["19","19","ל' הרמב\"ן בסוף סהמ\"צ: „. . שהן מצות אינן מעכבות זו את זו וזמנה של זו לא זמנה של זו\". ולכן מנאן לשתי מצות."],["20","20","בסהמ\"צ: ק\"ש* — מ\"ע יוד. קטורת — מ\"ע כח. תמידין — מ\"ע לט."],["21","21","צו ו, יח-יט. כתובים אלה הביא המעיה\"ח (בהערה 23)."],["22","22","מ\"ע פט."],["23","23","לכאו' כן צריך לפרש גם בדברי מעין החכמה „ובחטאת נמי כתיב תשחט החטאת וכתיב הכהן המחטא אותה יאכלנה וכן באשם ובשלמים ואפי' לא נחשבו השחיטה והאכילה לשני מצוות\". ותמוה: דהרי הרמב\"ם מנה במ\"ע בפ\"ע (מ\"ע סד) שיהי' מעשה קרבן חטאת על התואר הנזכר כו' (ובחינוך מצוה קלח). וכן באשם ובשלמים (מ\"ע סה-סו. ובחינוך מצוה קמ, קמא), ומנה במ\"ע בפ\"ע *) ראה שאג\"א סי' יב. ושם: דאפי' אה\"ל דק\"ש של יום זמנה כל היום וק\"ש של לילה זמנה כל הלילה, מ\"מ כיון דשל יום אין זמנה בלילה ושל לילה אין זמנה ביום ה\"ל מ\"ע שהזי\"ג. (מצוה פט. ובחינוך קב) אכילתם•, ועכצ\"ל כוונתו שלא מנה אכילת כ\"א מצוה בפ\"ע, או שבזה לא קאי לדעת הרמב\"ם (והחינוך). אמנם קושייתו היא (לא שגם אכילת פסח תוכלל במ\"ע דאכילת קדשים בהקושיא בפנים, כ\"א ע\"ד קושיית הר\"ד הבבלי): „וצריך טעם לפי דעתי למה יש למנות שחיטת הפסח ואכילתו לשני מצות אחרי שאנו מצווים על אכילתו א\"א לכזית בשר בלא שחיטה ובחטאת נמי כו' (כנ\"ל)\". ומל' זה (א\"א לכזית בשר כו') משמע שקושייתו היא בנוגע לשחיטתו, משא\"כ בחטאת כו' נמנה מעשה החטאת ולא שחיטתו (ראה מהר\"ם שיק רמ\"ץ ה')."],["24","24","ואף שדעת הרמב\"ם בזה צ\"ע: אם מצות אכילת קדשים היא רק זה שנאכלת לכהנים, וכדמוכח מלשונו בהל' מעה\"ק רפ\"י („הקדשים שאוכלים אותן הכהנים\") או גם זה שנאכלת לבעלים (כדעת רש\"י פסחים נט, א ד\"ה בשאר. וברמב\"ן בהשלמות לסהמ\"צ מ\"ע א) — ראה בזה מנ\"ח מצוה קב. בית האוצר מ\"ע א כלל קנח. קסב. צפע\"נ נדרים ט, ב. (ולהעיר מל' שם: ועי' מש\"כ רבינו בסהמ\"צ דאכילת זרים בקדשים קלים כו'). חמדי\"י מ\"ע פט. ועוד — הרי בכל אופן מובן שאכילת פסח היא מצוה ומכיון שהיא קק\"ל למה לא נכלל במ\"ע הכללית דאכילת קדשים (דאף שיש ע\"ז ציווי בפ\"ע הרי גם בחטאת ואשם יש בכ\"א ציווי בפ\"ע)."],["25","25","קושיא זו יש להקשות בין אם נאמר דמצות אכילת ק\"פ היא פרט בהקרבתו (כסברת ר\"ד הבבלי), דהרי גם בחטאת וכו' אף דאכילת כהנים •) ועפ\"ז צ\"ע במש\"כ (בדעת הרמב\"ם (והחינוך) עכ\"פ) בית הלוי (ח\"א ס\"ב) שתפס בקושיית מעיה\"ח שבחטאת מנה הכל (עשייתו ואכילתו) במצוה אחת (וכן בברית משה שם שכ': כיון דשחיטה ואכילה בזמן א' ע\"כ נמנה לאחת) ועי\"ז תירץ דבכל הקרבנות לא הוי מצוה רק שיהי' הקרבן נאכל ולא על האדם ומש\"ה הוי אכילתו פרט א' ממצות שבאותו קרבן וכמו הקטרת אימורין (אבל בפסח הוי החיוב על האדם) — שהרי להרמב\"ם (והחינוך) מצות אכילתו לכהנים אינו פרט ממעשה הקרבן, אלא מ\"ע כללית בפ\"ע."]]],[1300161120,"איז דער ביאור אין דעם: דער רמב\"ם אליין איז דאס מסביר בדיוק לשונו „שצונו לאכול בשר הפסח בליל חמשה עשר מניסן בתנאים הנזכרים והוא שיהי' צלי ושיאכל בבית אחד ועל מצות ומרורים והוא אמרו ואכלו את הבשר בלילה הזה צלי אש ומצות על מרורים יאכלוהו\"²⁶. ד.ה. דערמיט וואס די תורה זאגט אן א צאל תנאים און גדרים אין דער מצוה פון אכילת הפסח (ניט ווי בא קרבן חטאת וואו ס'שטייט סתם „הכהן המחטא אותה יאכלנה\", וכיו\"ב בא אנדערע קרבנות), מיט דעם טיילט די תורה אויס דעם חיוב פון אכילת פסח אלס א באזונדערע מצוה. און אזוי איז עס אויך בנוגע דער שחיטה²⁷ פון ק\"פ²⁸.\nבסגנון אחר קצת (ובהתאם צום תוכן פון דברי הר\"א בן הרמב\"ם): וויבאלד די מצות השחיטה איז אנגעזאגט געווארן צוזאמען (און אין פארבינדונג) מיט איר באשטימטן זמן, און די מצות האכילה איז אפהענגיק און אנגעזאגט געווארן צוזאמען מיט אן אנדער פאר איר באשטימטן זמן און מיט נאך אופני האכילה²⁹, איז מובן אז אט דער אונטער־שייד אין זמן צווישן שחיטת הפסח ואכילת הפסח איז ניט קיין כללות'דיקער ענין פון אכילת קדשים וואס במילא איז דאס אויך דא אין דער מצוה (ע\"ד ווי מ'געפינט בא קרבנות וואס זייער הקרבה דארף זיין דוקא ביום³⁰ וכיו\"ב), נאר דאס קומט אלס א גדר אין דער מצוה — מצות שחיטת הפסח בא־שטייט אין דעם וואס מ'דארף עס",[["","","נשלמה הכפרה (כמ\"ש בסהמ\"צ שם) נכלל במ\"ע דאכילת קדשים ולא כחלק ממעשה הקרבה כו' כנ\"ל הערה 23. וגם לפי דעת ר\"א בן הרמב\"ם שאינו חלק ממצות הקרבת הפסח, מכיון שהיא אכילת בשר קדשים אפשר שתוכלל במ\"ע דאכילת קדשים (לא רק כנגרר אחר המצוה כקכ\"ל)."],["26","26","וכן ברפ\"ח מהל' ק\"פ „אכילת בשר הפסח בליל חמשה עשר מצות עשה\" הביא כל המשך הכתוב שנאמר „ואכלו את הבשר . . . יאכלוהו\". וכן כשמנאן לפני הל' ק\"פ (שג\"ז מהרמב\"ם) כ': „לאכול בשר הפסח על מצה ומרור בליל חמשה עשר\". וגם במנין המצות שבראש ס' היד (אף שנכתב בקיצור הכי נמרץ, דייק וכ'): „לאכול בשר הפסח צלי בליל חמשה עשר שנאמר ואכלו את הבשר וגו'\". ופשוט שכוונתו גם לסיום הכתוב „ומצות על מרורים יאכלוהו\". וצע\"ק מה שלפני הל' ק\"פ השמיט „צלי\" ובמנין המצות שם לא כ' מצות ומרורים בפירוש."],["27","27","וכן בריש הל' ק\"פ „מ\"ע לשחוט את הפסח בארבעה עשר לחודש ניסן אחר חצות\". ובמנין המצות שלפני\"ז „לשחוט את הפסח בזמנו\". אבל במנין המצות שלפני ס' היד כ': „לשחוט הפסח שנאמר ושחטו אותו כל קהל גו'\". ולא כ' זמנו. וכנראה סמך על סיום הכ'."],["28","28","ראה עד\"ז בביאור הרי\"פ פערלא שם בתחילתו."],["29","29","והיינו שזמן כ\"א נאמר ביחד עם עצם המצוה — משא\"כ בהמצוות שהובאו לעיל (הערה 18, 20) מכיון שתוכן א' להם בב' הזמנים (ראה חמד\"י במ\"ע נו) נאמר הציווי שלהם בציווי א' ואח\"כ מפרט הזמנים, ראה בסהמ\"צ במקומן (בק\"ש: ודברת בם, ואח\"כ בשכבך ובקומך; קטורת: והקטיר עליו אהרן קטורת (ואח\"כ) בבקר גו'; בתמידין: את קרבני לחמי . . תשמרו להקריב (ואח\"כ) את הכבש אחד תעשה בבוקר גו'. וגם לפי סהמ\"צ שם שהביאו מהכ' „שנים ליום\", הרי מתחילה נאמר שהמצוה היא שנים ליום ואח\"כ מפרש זמנם „את הכבש אחד גו'\"). ראה לב שמח בסהמ\"צ שורש יא. קנאת סופרים סוף שורש ט' ובמ\"ע לט. ביאור הרי\"פ מ\"ע ג-ד בסופו."],["30","30","רמב\"ם רפ\"ד מהל' מעה\"ק. ומה שפרש\"י בנוגע לק\"פ (רפ\"ו דפסחים — סה, ב) ד\"ה שחיטתו וזריקת דמו — „אי אפשר אלא ביום דכתיב כו'\", הוצרך לזה בשביל זריקת דמו שלכן העתיק בהתחלת פירושו, כי הזמן די\"ד בין הערבים נאמר רק ב„ושחטו אותו\". וגם מש\"כ (בהעלותך ט, ג) „בארבעה עשר יום בחודש הזה בין הערבים תעשו אותו\", הרי קאי על הנאמר בתורה לפני\"ז. ובתורה מפורש בפרשתנו רק השחיטה. וראה רמב\"ן כאן דהכ' בזמן הקרבת קרבן פסח מדובר בזמן שחיטה. ראה בארוכה שאג\"א סי' יז ד\"ה ועתה אבאר."]]],[1300161121,"שחט'ן³¹ „ביום ארבעה עשר בניסן בין הערביים\"³², און במצות אכילת פסח בא־\nשטייט איר „ציווי\" (איר תוכן וגדר) אז מ'דארף עס עסן בליל חמשה עשר בניסן און די אנדערע תנאים הנ\"ל; און מצד דערויף³³ רעכענען זיי זיך אלס באזונ־דערע מצות.\nד. אויך ביים חיוב פון ק\"פ אין פסח שני (וואס לדעת הרמב\"ם איז דאס א",[["31","31","ועפ\"ז מובן בפשטות מה שהרמב\"ם הביא דוקא הכ' דפרשתנו „ושחטו אותו גו'\" כמ\"ע על שחיטתו, ולא הכ' דבהעלותך (ט, ב) ויעשו בנ\"י את הפסח במועדו, כהיראים (שם), כמו שהקשה בברית משה שם, כי דוקא מכתוב דילן — דביחד עם השחיטה נאמר זמנו ולאח\"ז נאמר הציווי על אכילתו — ידעינן דמצוה בפ\"ע היא וגדרה, משא\"כ בפ' בהעלותך שלא מפורש שחיטתו וגם לא נזכר שם בכלל (בנוגע לפ\"ר) הציווי על אכילתו (כ\"א ציווי כללי „ויעשו בנ\"י . . תעשו אותו\"). אלא שלדעת היראים (והבה\"ג) מצות ק\"פ של ישראל היא כל מעשה הפסח — שחיטתו זריקת דמו והקטרת אימוריו — כמ\"ש שם, ולכן לא הביא הכ' ושחטו כ\"א „ויעשו\". ולדעת הרמב\"ם המצוה על כ\"א מישראל היא שחיטתו, ולכן הביא דוקא הכ' „ושחטו\" (אלא שאם לא גמרו להקריבו לא נתקיים מצות „ושחטו\" של ישראל, ולא נפטר מחיוב כרת) — וראה הערה שלפנ\"ז ובהערה הבאה. ומה שהקשה ד„ושחטו\" לא נאמר בפסח דורות אלא בפסח מצרים — הרי כו\"כ מצות בפסח למדין רק מהנאמר בפרשה זו בנוגע לפסח מצרים. וראה פרשתנו יב, יד (ובמכילתא ופרש\"י). שם, יז (ובפרש\"י). שם, כד-כה. מכילתא ופרש\"י עה\"פ יב, מז. רמב\"ן שם יב, ט. ראב\"ע שם יב, מג."],["32","32","ועפ\"ז מובן גם מה שבפסח מנה מ\"ע דשחיטת הפסח, ולא כבחטאת כו' שמנה המצוה ד(כל) מעשה החטאת כו' (ראה לעיל הערה 23) — כי [נוסף על הפשוט, שרק השחיטה מפורשת בתורה בק\"פ ולא פרטי מעשי הקרבתו כבחטאת כו' שמפורשים פרטי מעשיהם, ועפ\"י מ\"ש הרמב\"ם (סהמ\"צ שורש ב') דהנלמד בי\"ג מדות לא מנה במנין המצות, הרי] בפסח מצות שחיטתו היא על כ\"א מישראל (חובת גברא), כל' הכתוב „ושחטו אותו כל קהל עדת ישראל\" (ראה מכילתא (הובא ברש\"י) עה\"פ. קדושין מא, ב. וש\"נ. ולהעיר ממשנה פסחים סד, א: שחט ישראל וקבל הכהן כו'. ובפרש\"י ושפ\"א שם). משא\"כ בחטאת כו' שמצוה על הבעלים היא הבאת הקרבן כו' „שצונו שיקריב כו'\" (סהמ\"צ מ\"ע סט ואילך), והשחיטה כו' ושאר הפרטים נאמרו כפרטים במעשה הקרבתו ולכן נחשב הכל ביחד כמצות מעשה הקרבן (סהמ\"צ מ\"ע סד ואילך). אבל ראה רש\"י פסחים ז, ב ד\"ה פסח וקדשים (וראה מנ\"ח מצוה ה' בסופו (ובהמובא שם)). או אפ\"ל (ויתאים לפרש\"י הנ\"ל) דהשחיטה בשאר הקרבנות נכללת במצות הקרבתו שעל הבעלים (מ\"ע סט ואילך). ומצות מעשה הקרבן עצמו שייכת למצות כהונה שהיא מקבלה ואילך, משא\"כ שחיטה — כשרה בזר (רמב\"ם הל' ביאת מקדש פ\"ט ה\"ז. רפ\"א מהל' פסולי המוקדשין)*, וראה מפרשי סהמ\"צ (לב שמח, מרגניתא טבא, קנאת סופרים) בשורש יב. אבל לא משמע כן מלשונו בהל' מעה\"ק (רפ\"ו. רפ\"ט) שבכל הקרבנות מנה שחיטתו במעשה הקרבן עצמו. וגם מלשונו בסהמ\"צ שם (מ\"ע סד ואילך) משמע שהיא ממצות מעשה הקרבן (שצונו שיהי' מעשה קרבן כו') ולא שייך למצות כהונה (משא\"כ בחינוך מצוה קלח. קמ. קמא). ולהעיר מדברי הרמב\"ם (לאחר שמנה מעשה קרבן עולה חטאת אשם ושלמים כ' במ\"ע סו): „אלו הארבעה . . הם מעשה הקרבנות כולם כי כל קרבנות בהמה יקריבו יחיד או צבור\". ואולי נכלל בזה גם מעשה הפסח."],["33","33","ומלבד זה יש באכילת פסח גם מצות אכילת קדשים כמ\"ש בכמה אחרונים — בית הלוי ח\"ג סנ\"א. שו\"ת צפע\"נ ח\"ב סכ\"ד (הובא בכללי התורה\"מ ח\"ב ע' ר). אר\"ש הל' חור\"מ פ\"ו ה\"א. ובכ\"מ. וראה צפע\"נ הל' ערכין פ\"ג הי\"ג (לד, סע\"ג ואילך). *) לכאו' ה\"ז אפ\"ל דבפסח להיות שהציווי הי' קודם מ\"ת שאז לא הי' מצוות במצות שחיטה, נחשבת השחיטה למצוה בפ\"ע, משא\"כ בשאר קרבנות שנצטוו אחר שניתנה תורה וגם חולין צריכין שחיטה ונמנה למצוה בפ\"ע (מ\"ע קמו) אין שחיטת קדשים נחשבת למצוה בפ\"ע (וראה תוד\"ה שחיטה זבחים יד, ב (ועוד) בשם הר\"י מאורליניש) — אבל הרי הרמב\"ם ס\"ל (הל' שחיטה פ\"ד הי\"ז) דבמדבר (בכלל) לא נצטוו בשחיטת חולין. וראה לשונו בסהמ\"צ שם מספרי: מה מוקדשין בשחיטה אף חולין כו'. ואכ\"מ."]]],[1300161122,"רגל בפני עצמו (פון ראשון)³⁴ טיילט דער רמב\"ם פאנאנדער זיין שחיטה און זיין אכילה און ציילט זיי אלס צוויי באזונדערע מצות³⁵.\nדאס איז אויך מובן לויטן זעלבן טעם ווי געזאגט ביים קרבן פון פסח ראשון: די אכילה דארף זיין „על מצות ומרו־רים\"³⁶ און דערין באשטייט דער „ציווינו\" און תוכן פון מצות אכילת פ\"ש³⁷.\nס'איז אבער ניט מובן, פארוואס ווערט מצות אכילת פסח שני ניט נכלל אין דער מצוה פון אכילת פסח בליל חמשה עשר בניסן?\nאון כאטש זיי זיינען איינגעטיילט אין באזונדערע זמנים, זיינען זיי דאך אבער אין זייער תוכן די זעלבע מצוה: א חיוב צו עסן דעם קרבן פסח „על מצות ומרורים\" אין דער נאכט נאך דער הקרבה³⁸ (ובמילא קומט די זעלבע מצוה אין צוויי זמנים): אויב די הקרבה איז געווען בי\"ד בניסן דארף זיין די אכילה בליל ט\"ו בניסן, און אויב די הקרבה איז געווען בי\"ד באייר, דארף זיין די אכילה בליל ט\"ו באייר³⁹.\nנאר דער ביאור אין דעם:\nהגם ווי מ'האט פריער גערעדט זיינען שחיטת הפסח און אכילתו ביידע גע־בונדן מיט זייער זמן, באופן אז דאס מאכט זיי צוויי באזונדערע מצות — איז דא אן אונטערשייד צווישן זיי אין דעם אופן ווי די געבונדנקייט מיטן זמן ווירקט און דריקט זיך אויס⁴⁰:\nדער יום י\"ד בניסן איז א יום־טוב טאג נאר צוליב דעם וואס דעמאלט איז שחיטת הפסח⁴¹, אבער מצד עצמו האט ער ניט קיין מציאות מיוחדת: דאקעגן דער ליל חמשה עשר בניסן איז אויס־געטיילט אויך (ואדרבה — בעיקר) אלס יום־טוב מצד עצמו, דאס איז דער זמן פון יצי\"מ — און ווי דאס איז געווען צום ערשטן מאל⁴²: „ועברתי בארמ\"צ בלילה הזה והכיתי כל בכור . . ופסחתי עליכם\"⁴³, און „ליל שמורים הוא לה' להוציאם מארמ\"צ\"⁴⁴ (און דער פסוק זאגט⁴⁵ „הוציאך ה\"א ממצרים לילה\")⁴⁶ — און צוליב דעם, צוליב דער חשיבות הזמן⁴⁷, איז דא דעמאלט די מצוה פון",[["34","34","שלכן נמנה למ\"ע בפ\"ע — רפ\"ה מהל' ק\"פ. סהמ\"צ מ\"ע נז."],["35","35","מ\"ע נז-נח. חינוך מצוה שפ-שפא."],["36","36","בהעלותך שם, יא."],["37","37","בסהמ\"צ שם „שצונו לאכול בשר פסח שני בליל חמשה עשר מאייר על מצה ומרור והוא אמרו כו'\". ועי' לשונו במנין המצות בראש ס' היד; לפני הל' ק\"פ; ובהל' ק\"פ פ\"ח ה\"ג."],["38","38","ובפרט שבמצות אכילתו אין מפורש זמן ורק „על מצות ומרורים יאכלוהו\". וזמנו נאמר בתחילת הכתוב בנוגע לעשייתו „בחודש השני בארבעה עשר יום בין הערביים יעשו אותו כו'\". ובמנין המצוות שם: „לאכול את בשר פסח שני על מצה ומרור שנא' גו'\". ולא כ' זמנו כמו בפס\"ר. וכ\"ה בחינוך מצוה שפא."],["39","39","עד\"ז הקשה גם ברי\"פ פערלא מ\"ע נז (קרוב לסופו)."],["40","40","להעיר משינוי ל' הרמב\"ם במנין המצות שלפני הל' ק\"פ (בנוגע לפ\"ר) שבשחיטה כ': „לשחוט את הפסח בזמנו\", ובאכילה: „לאכול בשר הפסח . . בליל חמשה עשר\"."],["41","41","ראה תוד\"ה שמונה — ערכין י, א. ירושלמי רפ\"ד דפסחים (הובא בתוס' שם ג, א). רמב\"ם הל' יו\"ט פ\"ח הי\"ז-יח. ובצל\"ח שם: דיו\"ט של תורה היא בעת הקרבת הקרבן . . שקבעה התורה יו\"ט ביום ההוא לרוב ישראל העושים הפסח."],["42","42","ראה שהש\"ר פ\"א, יב (ג)."],["43","43","פרשתנו יב, יב. יג."],["44","44","שם, מב. וראה רש\"י שם ד\"ה הוא הלילה."],["45","45","ראה טז, א ובפרש\"י שם. וראה ברכות ט, א."],["46","46","להעיר שלכמה דיעות גם בליל ט\"ו במצרים היו אסורים במלאכה (ראה ר\"ן לפסחים קטז, ב. פרש\"י פרשתנו יב, יז. ועוד. וראה שו\"ת תורת חסד או\"ח סכ\"ה אות ז). וראה לקו\"ש חי\"ז ע' 126 ואילך."],["47","47","וכמו שאומרים בהגדה „פסח שהיו אבותינו אוכלים . . על שום שפסח המקום כו' שנאמר . . ואת בתינו הציל גו'\"."]]],[1300161123,"אכילת פסח⁴⁸ (ועי\"ז — שחיטת הפסח בי\"ד בניסן).\nאנדערש איז אבער ביי פסח שני: אכילתו בליל ט\"ו באייר איז ניט פאר־בונדן דערמיט וואס ס'איז ט\"ו באייר — א זמן פון יום־טוב⁴⁹ וכיו\"ב, נאר בלויז דערפאר ווייל דאס איז די נאכט וואס נאך (דער הקרבה פון) י\"ד אייר⁵⁰. און דעריבער קען אט די אכילה ניט גע־רעכנט ווערן אלס די זעלבע מצוה ווי די אכילה פון פסח ראשון: ביי פסח\nראשון איז דער זמן אליין א פרט און חלק אין דער מצוה, אבער ביי פסח שני האט דער זמן אליין קיין שייכות ניט צום תוכן פון דער אכילה⁵¹.\nה. מיט דעם וועט מען אויך פאר־שטיין דעם דין הלל בא פסח ראשון, און דער חילוק בזה צווישן פסח ראשון ופסח שני:\nפון די חילוקים צווישן פסח ראשון און פסח שני, רעכנט די משנה⁵²: „הראשון טעון הלל באכילתו והשני אינו טעון הלל באכילתו (און פירט אויס) זה וזה טעונין הלל בעשייתן\". אויף דער הלכה „הראשון טעון הלל באכילתו וכו'\" שטעלט זיך די גמרא⁵³: „מנה\"מ, א\"ר יוחנן . . השיר יהי' לכם כליל התקדש חג⁵⁴, לילה המקודש לחג טעון הלל, לילה שאין מקודש לחג אין טעון הלל\". דערנאך זאגט די גמרא אויף „זה וזה טעונין הלל בעשייתן כו': מאי טעמא, איבעית אימא לילה קא ממעט יום לא קא ממעט ואיבעית אימא אפשר ישראל שוחטין את פסחיהן ונוטלין את לולביהן ואין אומרים הלל\".\nפון דעם וואס אויף „טעונין הלל בעשייתן\" פרעגט די גמרא מיטן לשון „מאי טעמא\" (און ניט בלשון „מנה\"מ\" ווי זי פרעגט אויף „הראשון טעון הלל באכילתו וכו'\") און דערפון וואס די גמרא ענטפערט אויף דעם (אין ערשטן תירוץ) „לילה קא ממעט יום לא קא ממעט\" — איז מוכח אז מיט דער שקלא וטריא זוכט די גמרא צו מסביר זיין (ניט",[["48","48","ועד מתי אתה אוכל והולך עד מועד צאתך ממצרים (ברכות שם). וכ\"פ הרמב\"ם (הל' ק\"פ פ\"ח הט\"ו) שמדאורייתא אוכלים כל הלילה. וגם לדעת ראב\"ע שאוכלים רק עד חצות מדאורייתא — זמן שריפה הוא רק בבוקר שאז נעשה נותר — ראה פרש\"י שם ד\"ה תזבח. וראה בהמובא בצפע\"נ עה\"ת פרשתנו ע' לז. הל' ערכין שם. אר\"ש שם."],["49","49","ראה פרש\"י בהעלותך ט, י. פסחים צה, ב ד\"ה שאין."],["50","50","ועפ\"ז יומתק ל' החינוך (מצוה שפא): „שכל המחוייב בפסח שני שיאכל בשר הפסח על מצות ומרורים שנא' על מצות ומרורים יאכלוהו\", שלא כתב זמנו ולא פירש להדיא מצוה דעצם אכילתו כמו בפס\"ר (עי' רי\"פ פערלא (שם בסופו) שהקשה עליו•) — כי בתורה לא נאמר מפורש לא זמן אכילתו ולא ציווי על עצם אכילתו בל' „ואכלו את הבשר גו'\" (כבפס\"ר), כ\"א „על מצות ומרורים יאכלוהו\", ולכן מפרט רק „שיאכל כו' על מצות ומרורים יאכלוהו\" כו'\" שעפ\"ז מבואר מה שלא נמנה ביחד עם שחיטתו. וצ\"ע בל' הרמב\"ם במנין המצות לפני הל' ק\"פ שבשחיטה כ': לשחוט פסח שני (ולא כ' זמנו), ובאכילה: „לאכול פ\"ש כו' בליל חמשה עשר לחודש השני\" (ולא כבמנין המצות לפני ספר היד, כנ\"ל הערה 38)."],["51","51","וחילוק זה עושה אותם מצות בגדרים שונים, אבל זה שבפס\"ר גם נשים חייבות ובשני אינן חייבות, אי\"ז שינוי בעצם גדר ותוכן המצוה."],["52","52","פסחים צה, א."],["53","53","שם, ב."],["54","54","ישעי' ל, כט. •) ומה שהקשה דממש\"כ החינוך „ועובר ע\"ז ואכל פסח שני מבלי מצה ומרור בטל עשה\", מבואר דלא מנה עשה אלא לענין מצה ומרור, ונטה מדברי הרמב\"ם — ראה מנ\"ח שם שאי\"ז פירוש דברי החינוך וכן מה שכ' דבפס\"ר לא הזכיר אלא מצות אכילת הפסח בלבד, הרי כתב שם בפירוש „לאכול בשר הפסח בליל טו עפ\"י תנאים שבכתוב\"."]]],[1300161124,"דעם מקור וטעם פארוואס „זה וזה טעונין הלל בעשייתן\" פאר זיך⁵⁵, נאר) אין וואס עס באשטייט דער חילוק צווישן שחיטת פסח שני וואס דארף האבן הלל, און אכילתו וואס דארף ניט האבן קיין הלל.\nדארף מען פארשטיין: א) פארוואס פרעגט טאקע ניט די גמרא „מנה\"מ\" (וכיו\"ב) אויף דער עצם הלכה פון „טעונין הלל בעשייתן\", פונקט ווי אויף דער הלכה פון „הראשון טעון הלל באכילתו וכו'\"⁵⁶? ב) וויבאלד די גאנצע שאלה פון דער גמרא איז נאר בנוגע דעם טעם פונעם אונטערשייד צווישן אכילתו ושחיטתו, איז וואס ענטפערט די גמרא אין צווייטן תירוץ „אפשר ישראל שוחטין את פסחיהן . . ואין אומרים הלל\" — אין דעם הסבר געפינט מען ניט קיין חילוק צווישן שחיטת הפסח ואכילתו, די זעלבע סברא קען מען זאגן (לולי דעם מיעוט) אויך בנוגע אכילתו (אפשר ישראל אוכלין⁵⁷ וכו')⁵⁸?\nו. איז דער ביאור אין דעם: פון פסוק „השיר יהי' לכם כליל התקדש חג\" לערנט מען אריס ניט בלויז דעם מיעוט\nפון „לילה שאין מקודש לחג אין טעון הלל\", נאר דעם עצם גדר החיוב פון הלל בשעת אכילת פסח — אז דאס איז ניט, בעיקר, צוליב עצם אכילת הפסח, נאר צוליב דעם וואס די אכילה איז אין „ליל התקדש חג\" — דער זמן הגאולה און די נסים פון יצי\"מ, און דערפאר דארף מען זאגן הלל⁵⁹:\nד.ה. וויבאלד אכילת פסח בליל ט\"ו בניסן איז דאך בפועל (געווען) פאר־בונדן מיט דער גאולה און נסים פון אט דער נאכט, ווארום מהאי טעמא איז דאס דער באשטימטער זמן פאר דער מצוה פון אכילת הפסח, כנ\"ל, איז דערפאר מחובר דער זמן מיט דער מצוה מיוחדת שבו און אמירת הלל איז בשעת אכילת הפסח⁶⁰.\nדערפון*⁶⁰ איז פארשטאנדיק בנוגע צו פסח שני, וויבאלד אז „אין מקודש לחג\" — ליל ט\"ו אייר איז דאך ניט געווען",[["55","55","ועפ\"ז צ\"ע מה שהוצרך רש\"י לפרש בד\"ה לילה „ולקמן אמרינן נביאים שביניהן תקנו כו'\" — דלכאורה: א) למה צריך לפרש טעם הלל בשחיטתו כאן, ב) מנין שלטעם הא' „יום לא קא ממעט\" טעם ההלל שונה מלטעם הב'."],["56","56","כדמוכח מפרש\"י שם שהגמ' בא לפרש (גם) הטעם שהראשון טעון הלל באכילתו."],["57","57","אף שי\"ל שאין צריך לאומרו עוה\"פ באכילתו מטעם זה, כיון שכבר אמרו בשחיטתו. וכמ\"ש בשפ\"א כאן."],["58","58","גם צלה\"ב בעצם הענין: מהי הסברת ההכרח, בל' הברייתא „אפשר ישראל שוחטין כו' שיחייב אמירת הלל. ומה שפרש\"י „כיון שדבר מצוה הוא טעון הלל\" — הרי אינו מרומז בגמ', ולכאר' י\"ל שרמזו בזה שהביא גם „נוטלין את לולביהן\" אבל לא משמע כן מפרש\"י ד\"ה „נוטלין את לולביהן\"."],["59","59","והרי פי' הכתוב „השיר יהי' לכם\" הוא „ביום שתגאלו מן הגלות\" (פרש\"י פסחים שם). וראה טו\"א מגילה יד, א ד\"ה יצי\"מ. וכ\"מ ממדרש תהלים (קיג) שאמרו הלל בשעת הנסים כו' דיצי\"מ. וראה ירושלמי פסחים פ\"ה ה\"ה. פרקי דר\"א ספמ\"ח וברד\"ל שם."],["60","60","וכ\"מ בירושלמי שם פ\"ט ה\"ג, שבפסוק זה למדין ליל פסח ממפלת סנחריב (וראה קה\"ע ופ\"מ שם). ועד\"ז בפרש\"י ישעי' שם. וברמב\"ן לסהמ\"צ שורש א' ד\"ה והפליאה (דס\"ל דהלל הוא מה\"ת) כ' כי ישירו לא\"ל המושיע אותם מיד סנחרב כאשר הם משוררים בליל התקדש חג והוא ליל אכילת חג הפסח שהיו משוררים בקול גדול כמו שאמרו (פסחים פה, סע\"ב). וברמב\"ן פסחים (קיז, א ד\"ה ותמה): שאין לך הלל חובה כאכילת פסחים שהיא שעת גאולה וכן שנינו זה וזה טעונין הלל באכילתם (? — כנראה הוא ט\"ס) וסמכוהו על המקרא דכתיב השיר יהי' לכם כו' (וראה שו\"ת ח\"ס שבהערה 46). אבל מרמב\"ן (שם ד\"ה עוד) לפנ\"ז וברי\"ן (פסחים שם קיח, א) משמע, שהלל בלילה הוא הלל שעל עשיית מצוה (אכילת הפסח עצמה). *60) ועפ\"ז מתורץ דיוק השפ\"א כאן."]]],[1300161125,"קיין זמן פון נסים און דערפאר פאר־מאגט ער ניט קיין חג⁴⁹ תוכן — דערי־בער איז די אכילה פון פ\"ש „אינו טעון הלל\", וויבאלד די אכילה כשלעצמה איז ניט גענוג סיבה צו אמירת הלל, כנ\"ל.\nז. נאכן תירוץ פון דער גמרא (בהמשך צום ביאור הנ\"ל) שטעלט זיך די גמרא אויף „זה וזה טעונין הלל בעשייתן כו'\" און פרעגט „מאי טעמא\": וואס איז דער טעם החילוק צווישן שחיטת הפסח (מיט הלל) און אכילתו (אן הלל — פארוואס זאל שחיטתו פון פ\"ש זיין אנדערש פון אכילתו); די גמרא פרעגט דא ניט דעם טעם פארוואס שחיטה בכלל איז „טעון הלל\", ווארום דער ארט אויף אזא שאלה איז ניט ביי דער משנה, נאר ביים ערשטן מאל זאגן דעם דין פון הלל ביי שחיטה — אין א פריערדיקער משנה⁶¹; אין דער משנה ווערן אויסגערעכנט נאר די פרטי דינים אין וועלכע פסח ראשון און פסח שני טיילן זיך פאנאנדער און בדרך ממילא אויך אין וואס זיי גלייכן זיך — אין הלל ביי שחיטה (א.א.וו.) — וואס אויף דעם קומט די שאלה „מאי טעמא\".\nאון די גמרא איז מבאר אז דער גדר פון אמירת הלל בשחיטתו איז אן אנ־דערער ווי אמירת הלל באכילתו (בלילה):\nדער ערשטער תירוץ „לילה קא ממעט יום לא קא ממעט\" אמירת הלל בלילה איז פארבונדן מיטן טעם פון „התקדש חג\", און דערפאר איז מען ממעט „לילה\" פון פסח שני; אבער אמירת הלל ביום איז ניט פארבונדן מיטן זמן מצ\"ע, און דערפאר איז לא אימעיט. ד.ה. דער ערשטער תירוץ איז\nבעיקר מדגיש דעם שינוי פון אמירת הלל ביום לגבי אמירתו בלילה דורכן טעם לאמירתו בלילה און במילא איז מובן (בדרך שלילה) אז אמירתו ביום איז ניט מטעם „התקדש חג\" און דערפאר איז ניטא קיין חילוק צווישן יום פון י\"ד ניסן (פ\"ר) און יום י\"ד אייר (פ\"ש).\nדער צווייטער תירוץ, „אפשר ישראל שוחטין את פסחיהן . . ואין אומרים הלל\", איז מדגיש דעם טעם פון אמירתו ביום (אז אמירת הלל ביום איז פאר־בונדן מיט שחיטת הפסח („אפשר ישראל שוחטין . . ואין אומרים וכו'\")), און דערפאר איז פארשטאנדיק אז מען דארף זאגן הלל ביי שחיטת פסח שני פונקט ווי ביי שחיטת פסח ראשון.\nאנדערש איז אבער אמירת הלל ביי אכילת הפסח (ראשון) וואס (די אכילה גופא איז ניט מספיק דערצו כנ\"ל, נאר) דאס איז מטעם „התקדש חג\" כנ\"ל, און דערפאר איז ביי אכילת הפסח בליל ט\"ו אייר ניט שייך קיין אמירת הלל.\nויש לומר, אז דער חילוק צווישן ביידע תירוצים איז: לויטן ערשטן תירוץ איז אויך אמירת הלל בעת שחיטה פאר־בונדן מיטן זמן, מיט „יום\", על דרך ווי דאס איז אין אכילתו — מיטן אונטער־שייד, וואס ביי אכילתו איז דער זמן גופא א סיבה; דאקעגן ביי שחיטתו מאכט די מצות השחיטה דעם זמן: דורך דעם מצוה פון שחיטת הפסח אין דעם „יום\" ווערט דער זמן גופא⁶² אזא וואס",[["61","61","פסחים סד, א."],["62","62","ראה תוס' ערכין שבהערה 41. ולהעיר מירוש' ורמב\"ם וצל\"ח שבהערה שם. וראה מכתבי תורה (מכ' ג') דלפי פי' התוס' ברכות (יד, א ד\"ה ימים) צ\"ל דכוונת התוס' בערכין — ד„אז הוו להו יו\"ט\" — הוא ל„פסח שני\"."]]],[1300161126,"איז טעון הלל⁶³; און לויטן צווייטן תירוץ איז אמירת הלל נאר מצד שחיטת הפסח — „אפשר ישראל שוחטין את פסחיהם כו' וא\"א הלל\"⁶⁴.\nעכ\"פ איז פארשטאנדיק לויט ביידע תירוצים, היות אז דער טעם וואס פסח ראשון בעשייתו איז טעון הלל איז ניט דערפאר וואס דער זמן מצ\"ע איז אזא וואס מאכט דעם חיוב האמירה, נאר מצד שחיטת הפסח (שבו), איז מובן, אז אין דעם גלייכן זיך פסח ראשון ופסח שני און ביידע זיינען טעונים הלל בעשייתן.\nח. דער ביאור בכל הנ\"ל בפנימיות הענינים:",[["63","63","ועפ\"ז יש לבאר מה שפרש\"י בתי' הא' „ולקמן אמרינן נביאים שביניהן תקנו\" (ראה לעיל הערה 55) — כי מהגמ' מוכח שהלל שייך ליום — להזמן, ועפ\"ז מתאים יותר מה ש„נביאים שביניהן תקנו כו' על כל פרק ופרק כו'\" שהם עניינים השייכים להזמן (מצד איזה דבר שאירע בו וכיו\"ב) לא מצד הפעולה עצמה כו'."],["64","64","ולכן פירש\"י „דדבר מצוה הוא טעון הלל\", היינו מצד מצות שחיטת הפסח עצמה. ועד\"ז מובן מרמב\"ן ור\"ן לפסחים קיז, א. וגם עפ\"ז יש לבאר מה שלדעת רש\"י (לעיל סד, א. ד\"ה אם גמרו וד\"ה ואם שנו) היו קוראים את ההלל רק בשעת שחיטה, כי [נוסף להמבואר בתוס' שם, דכשאין נסכין אין הלוים אומרים שירה בשעת הקרבה כ\"א בשעת שחיטה — והרי גם לדעת רש\"י הלוים היו אומרים את ההלל כמשנ\"ת פעם בארוכה (ראה המכתבים שנדפסו בהגש\"פ עם לקוטי טעמים מנהגים וביאורים (קה\"ת תשמ\"ו-ז) ע' סג ואילך)* — הרי] המצוה בק\"פ שעל ישראל היא השחיטה, וכנ\"ל בהערה 31, 32. *) וראה שקו\"ט בזה בס' האחרונים — במכתבי תורה (מכתב ב\"ה). בהמובא בצפע\"נ עה\"ת פרשתנו ע' מג ואילך. תו\"ש מילואים לחלק יב ס\"ב. ובכ\"מ. ועפ\"י המבואר בהמכתבים שנסמנו בפנים ההערה אי\"צ לכל הנ\"ל. יצי\"מ איז פון די עיקר'דיקע און כללות'דיקע געשעענישן אין דעם לעבן פון אידן; ס'איז דעמאלט געווען דער אנהויב, דער „געבורט\"⁶⁵ פון עם ישראל, ווען זיי זיינען פון עבדי פרעה געווארן „עבדי ה'\"⁶⁶ — ווי דער פסוק זאגט⁶⁷ „כי לי בני ישראל עבדים עבדי הם אשר הוצאתי אותם מארץ מצרים\". און וויבאלד אז דער אינהאלט פון קרבן פסח איז דאס צוגרייטן און צו־ברענגען צום כללות'דיקן ענין פון יצי\"מ⁶⁸, צו ווערן עבדי ה' — איז פאר־שטאנדיק, אז אויך אלע איינצלנע ענינים וואס די תורה זאגט אן דערביי, זיינען ניט סתם פרטים, נאר יעדער ענין איז א כלל פאר זיך. [און דאס גופא איז דער טעם וואס דוקא ביים ציווי אויפן קרבן פסח געפינט מען אין תורה אזוי פיל פרטים און פרטי פרטים — ווי מען דארף אים צוגרייטן און ווי ער דארף געגעסן ווערן וכו' (וואס מען געפינט ניט אזוינס בא אנדערע קרבנות), דערמיט איז מודגש די באזונדערע חשיבות פון די פרטים ביי קרבן פסח]. וי\"ל אז דאס איז דער טעם, בפנימיות הענינים, וואס די הקרבה און אכילה פון קרבן פסח ווערן גערעכנט יעדערער אלס ---"],["65","65","ראה יחזקאל טז ובמפרשים שם."],["66","66","ראה מגילה (יד, א. וש\"נ): בשלמא התם כו'. ובירוש' ומדרש תהלים שבהערה 59, שהיינו עבדים לפרעה ונעשו עבדים לך . . עבדיו של הקב\"ה שנאמר הללו עבדי ה' ולא עבדי פרעה."],["67","67","בהר כה, נה. ראב\"ע שם, מב."],["68","68","ראה גם מכילתא פרשתנו (הובא בפרש\"י) יב, ו. שם, כז. שמו\"ר פט\"ז, ב (בסופו). ועד שכל היו\"ט דיצי\"מ נק' בל' חכמים ע\"ש קרבן פסח, ולפי פי' הת\"י שמות (לד, כה) בהעלותך (ט, יב) כ\"ה גם בלשון התורה."]]],[1300161127,"א מצוה פאר זיך — ווארום יעדערע פון זיי פאר זיך איז א כלל און עיקר אין דער צוגרייטונג צום כללות'דיקן ענין פון יציאת מצרים (וכדלקמן ס\"י).\nט. לויט דעם וועט מען אויך פאר־שטיין וואס דוקא בא קרבן פסח געפינט מען אז די טמאים לנפש אדם זיינען גע־קומען מיט דער טענה „למה נגרע\": הגם ס'איז דא דער כלל פון „עבר זמנו בטל קרבנו\"⁶⁹ — איז אבער דער ענין פון קרבן פסח אנדערש: אויב מ'האט פארפעלט מקריב זיין א קרבן פון אנדערע קרבנות, פעלט דורך דעם אן ענין פרטי, אבער קרבן פסח, היות אז דורך אים ווערט אויפגעטאן דער אריבערגאנג פון „עבדי פרעה\" צו דער דרגא פון עבדי ה' — אזא כללות'־דיקער ענין קען ניט געמאלט זיין ער זאל פעלן בא א אידן.\nאון דערפאר האט מען די „טמאים לנפש אדם\" געגעבן א געלעגנהייט דאס צו מתקן און משלים זיין בפסח שני. נאכמער: אט דער ענין איז אויף אזוי־פיל נוגע, אז דאס ווערט באוארענט (בעיקר) בשייכות צו יחידים וכמרז\"ל⁷⁰: איש נדחה לפסח שני ואין צבור נדחין לפסח שני — ווארום (וואס זיינען טמאי מת) דארף דאך ניט אנ־קומען, זיי זיינען מקריב דעם קרבן פסח בראשון; בכדי דער ענין זאל ניט פעלן אויך ביי א יחיד, אז אויך אן איינציקער איד זאל צוקומען צו ווערן אן עבד ה', האט מען געגעבן שפעטער א טאג אויף מקריב זיין דעם\nקרבן פסח — מיטן גאנצן סדר העבודה פון כהנים לויים וכו' וואס איז דערמיט פארבונדן; ביז צום נעמען דערפון די כללות'דיקע הוראה פאר אידן לדורות, אז „עס איז ניטא קיין „פארפאלן\" מען קען אלעמאל פארריכטן\"⁷¹.\nיוד. עפ\"ז קען מען אויך מסביר זיין (בפנימיות הענינים) דאס וואס פסח שני קען נאר משלים זיין הקרבת (שחיטת) הפסח און אכילתו, און ניט די אמירת הלל וואס מ'זאגט ביי אכילת ק\"פ אין ט\"ו ניסן — ווייל נאר די הקרבה און אכילה פון קרבן פסח זיינען ענינים כלליים אין דער צוגרייטונג צו ווערן עבדי ה', אבער ניט אמירת הלל (בשעת'ן אכילה).\nדער ביאור אין דעם:\nאין דער הכנה פון אידן צו ווערן עבדי ה' האט זיך געפאדערט צוויי זאכן: א) שחט'ן, אפווארפן די עבודה זרה פון מצרים⁷², און די עבודות צו פרעה, וואס דאס האט געקענט קומען נאר דורך מסירת־נפש'דיקער איבערגעגעבנקייט צום אויבערשטן (ווארום דאס נעמען דעם „שה\" (די עבודה זרה פון מצרים) אפענערהייט פאר די אויגן פון די מצריים איז געווען פארבונדן מיט מס\"נ⁷³); ב) אט דעם קרבן פסח האבן אידן געדארפט עסן, ד.ה. אט די מסירת נפש אויף זיין אן עבד ה' דארף ווערן דם ובשר כבשרו⁷⁴, עס דארף דורך־דרינגען, דורכנעמען דעם גאנצן מהות",[["69","69","ראה ברכות כו, סע\"א (גי' התוס' ד\"ה טעה). ספרי (ופרש\"י) פינחס כח, י. יד. ועוד."],["70","70","פסחים סו, סע\"ב ואילך. וראה משנה פסחים עט, א. רמב\"ם רפ\"ז דהל' ק\"פ."],["71","71","היום יום ע' נג."],["72","72","מכילתא יב, כא. ת\"י שם. שמו\"ר שם. וראה מו\"נ ח\"ג פמ\"ו, ובהנסמן בהערה הבאה."],["73","73","ראה שמו\"ר פט\"ז, ג. מאו\"ת ר\"ס תל. וראה מכתבים כלליים לחגה\"פ שנדפסו בהגש\"פ (קה\"ת, תשמ\"ו) ע' תרי ואילך. תרכט. תרלח-ט. ועוד."],["74","74","תניא פ\"ה."]]],[1300161128,"פון א אידן, און אויך אלע זיינע ענינים, ביז צו די עניני אכילה — די גשמיות'־דיקע זאכן פון דעם אידן⁷⁵.\nאון וויבאלד שחיטת והקרבת הפסח און אכילתו (מיט אלע זייערע תנאים) זיינען ענינים כלליים, דערפאר איז פאראן — און מוז זיין — א געלעגנ־הייט זיי צו מתקן זיין.\nמשא\"כ דאס זאגן הלל בשעת אכילת קרבן פסח — וואס דאס איז (ווי דער־קלערט פריער בארוכה) ניט א זאך וואס איז נוגע און געבונדן מיט עצם האכילה,\nנאר מיט קדושת היום פון ט\"ו ניסן, וואס פועל'ט אין אכילת הפסח מ'זאל זאגן דערביי הלל — איז דאס ניט קיין ענין כללי אין דער צוגרייטונג צו עבדי ה', און דערפאר איז אין דעם ניטא דער הכרח צו משלים זיין.\nדאקעגן דער הלל וואס מ'זאגט בשעת שחיטת הפסח, וואס דאס איז מצד דער שחיטה אליין, דאס איז א חלק פון דער עבודה פון שחיטה — דערפאר איז דאס אויך א חלק פון דער כללות'דיקער עבודה פון פסח וואס מ'מוז (מ'קען) אלעמאל פארריכטן.\n(משיחת אחש\"פ תשכ\"ו)",[["75","75","ראה גם לקו\"ש ח\"ג ע' 870."]]],[1300161129,"<h3>בא ג</h3>\nא. איינע פון די זאכן אין וועלכע פסח מצרים איז אנדערש פון פסח דורות איז, וואס ביי פסח מצרים איז „הקדים לקיחתו לשחיטתו ד' ימים\"1, „בעשור לחודש\"2 — „מה שלא ציווה כן בפסח דורות\"3 (כאטש אויך ער דארף האבן „ביקור (ממום) ארבעה ימים קודם שחיטה\"4, דארף די לקיחת השה ניט זיין „בעשור לחודש\"<sup data-n=\"5\">5</sup>.\nפארוואס האט די לקיחה פון פסח מצרים געדארפט זיין קודם „לשחיטתו ארבעה ימים\"1 — ניט ווי פסח דורות — ברענגט רש\"י6 (פון\nמכילתא<sup data-n=\"7\">7</sup>: „הי' ר' מתיא בן חרש אומר הרי הוא אומר8 ואעבור עליך . . הגיעה שבועה שנשבעתי לאברהם שאגאל את בניו ולא היו בידם מצות להתעסק בהם כדי שיגאלו שנאמר9 ואת ערום וערי' ונתן להם שתי מצות דם פסח ודם מילה שמלו10 באותו הלילה כו'\".\nדארף מען פארשטיין:\nא) ר' מתיא בן חרש איז נאר מסביר פארוואס דער אויבערשטער האט זיי געגעבן די מצוה פון קרבן פסח (אז דאס איז כדי זיי זאלן האבן „מצות להתעסק בהם כדי שיגאלו\") — אבער די שאלה: „מפני מה הקדים לקיחתו לשחיטתו\" און „ארבעה ימים\" דוקא, ניט מער און ניט ווינציקער? — איז במקומה עומדת11.\nב) נאך מערער: ר' מתיא בן חרש רעדט בכלל ניט וועגן לקיחת השה, נאר וועגן „דם פסח\" — וואס בפשטות מיינט",[["1","1","פרש\"י פרשתנו יב, ו. ממכילתא עה\"פ."],["2","2","פרשתנו שם, ג."],["3","3","לשון רש\"י שם. וראה הערה 6."],["4","4","פסחים צו, א. מכילתא ופרש\"י פרשתנו שם (ומסתימת לשון רש\"י משמע, שהוא דין גם בפסח דורות). וראה אנציקלופדי' תלמודית ע' בקור מומים (ע' קסג), וש\"נ. תורה שלמה פרשתנו מילואים לכרך י\"א סי' יב."],["5","5","פרש\"י שם, ג ד\"ה הזה. ממכילתא ותיב\"ע עה\"פ. פסחים שם."],["6","6","שם, ו — לאחרי שמפרש „והי' לכם למשמרת, זה לשון בקור כו'\". וראה מפרשי רש\"י (גו\"א, דברי דוד, משכיל לדוד ועוד) ביאור המשך ב' הענינים שבפרש\"י [ובפרט שהשאלה „מפני מה הקדים לקיחתו כו'\" הי' לכאורה צ\"ל מקומה לעיל בפסוק ג (כקושיית הרא\"ם ועוד)] — דמכיון שהענין דבקור ממום ד' ימים הוא גם בפסח דורות (כנ\"ל הערה 4), א\"כ עכצ\"ל דזה שהלקיחה היא בעשור לחודש אינה בשביל בקור ממום*, שהרי בפסח דורות אין צ\"ל הלקיחה בעשור לחודש; וא\"כ קשה „מפני מה הקדים לקיחתו לשחיטתו ארבעה ימים מה שלא צוה כן בפסח דורות\", [ומתורצת עפ\"ז גם הוספת רש\"י (על לשון המכילתא) „מה שלא צוה כן בפסח דורות\" — כי זהו יסוד השאלה „מפני מה הקדים כו'\", כנ\"ל (ראה דברי דוד שם)]."],["7","7","עה\"פ."],["8","8","יחזקאל טז, ח."],["9","9","שם, ז."],["10","10","תיבות אלו ליתא במכילתא שלפנינו. וראה משכיל לדוד כאן. לקמן בפנים סעיף ב' והערה 15, 18."],["11","11","בגו\"א כאן מפרש דמכיון שפסח טעון התעסקות דבקור מום ד' ימים לכן הקדים גם לקיחתו ד' ימים כדי שיעסקו בו ד' ימים — אבל ביאור זה לא נרמז כלל בדברי רמב\"ח (כי רמב\"ח מבאר רק הצורך שיהיו עסוקים במצות בכלל). *) בתי' הא', תירוצו הב' (וכן התי' שבצידה לדרך כאן) אינו ע\"ד הפשט, ע\"ש. *) במכילתא שם מסיים „והי' לכם למשמרת להוציא פסח דורות .. מקחו כל זמן\". וראה מפרשי המכילתא. תו\"ש שם. *) וצ\"ע ברבינו בחיי (לעיל פסוק ג): „הי' נלקח בעשור ונשחט בי\"ד, למדך הכתוב שהוא טעון בקור ארבעה ימים ולכך הקדים לקיחתו לשחיטתו ארבעה ימים\". וראה תו\"ש שם."]]],[1300161130,"דאס דעם ציווי12 „ולקחו מן הדם ונתנו על שתי המזוזות גו'\" — און די התעסקות מיט „דם פסח\" איז גאר געווען לאחרי שחיטה, בי\"ד ניסן בין הערביים.\nג) אפילו מ'זאל זאגן (בדוחק עכ\"פ), אז אין דער התעסקות בדם פסח ווערט נכלל אויך לקיחת השה (ווייל דאס איז א הקדמה צו שחיטת הפסח וכו') — איז אבער נאך אלס ניט גלאטיק וואס רמב\"ח דערמאנט דא — אין דעם ענין פון „מפני מה הקדים לקיחתו כו'\" — (אויך) „דם מילה\", אז דער אויבערשטער האט דעמאלט אנגעזאגט די אידן אויך אויף „דם מילה\"?\nד) יתרה מזה — „דם מילה\" איז אויך „ציווה בפסח דורות\". און דער וואס איז געווען גע'מלט פון פריער איז אויך בא פסח מצרים ניט נצטווה געווארן.\nב. מפרשים13 זיינען מסביר, אז דורך דברי רמב\"ח אז „נתן להם שתי מצות\" — דם פסח צוזאמען מיט דם מילה — ווערט פארשטאנדיק פארוואס לקיחת השה האט געמוזט זיין „ארבעה ימים\" פאר דער שחיטה:\nנאכן ברית מילה דארף מען איבער־וארטן דריי טעג איידער מ'גייט ארויס\nלדרך (מפני הסכנה) — ווי רש\"י האט שוין געבראכט אין פ' שמות14 — און דעריבער איז מילת בנ\"י געווען בעשור לחודש, כדי זיי זאלן זיין גרייט ארויס־צוגיין פון מצרים (און „מלו באותו הלילה\" מיינט רש\"י — לילה של לקיחת הפסח);\nאון דערפאר האט מען אויך מקדים געווען לקיחת הפסח צו „בעשור לחודש\", כדי אז אידן זאלן האבן ביידע מצות — דם פסח ודם מילה — צו־זאמען.\nאבער דער פירוש (אז „מלו באותו הלילה\" מיינט רש\"י דעם לילה פון לקיחת הפסח<sup data-n=\"15\">15</sup> איז צע\"ג — ווייל רש\"י זאגט דאך דא בפירוש16, אז דער דם מילה איז געווען צוזאמען מיט דם פסח, „מתבוססת בדמיך17, בשני דמים\", וואס דאס איז געווען אור לט\"ו ניסן18.",[["12","12","פרשתנו שם, ז. שם, כב."],["13","13","רבותינו בעה\"ת (דעת זקנים פסוק ג. הדר זקנים פסוק ו). ועד\"ז בריב\"א ורע\"ב כאן (בפי' האחרון). וראה גם אלשיך ומשכיל לדוד כאן באו\"א קצת (וראה לקמן הערה 15). בריב\"א ורע\"ב שם לפנ\"ז מפרשים שטעמו של רש\"י למה הקדים ד' ימים קודם שחיטה הוא „כדי להיות הלקיחה בשעת משיכת ידם (הפרשתן) מע\"ז שהיא בעשור .. משכו וקחו\" — אבל (נוסף לזה שלא ביארו למה הביא רש\"י בפירושו מאמרו של רמב\"ח) עדיין חסר ביאור, מהו הענין בזה שהלקיחה תהי' בשעת משיכת ידם מע\"ז (ולאידך — הדיבור הי' בר\"ח והציווי דמשכו כו' מע\"ז בפועל דחו ל„בעשור לחודש\"?)."],["14","14","ד, כד."],["15","15","במשכיל לדוד מפרש, דהקב\"ה ציום שימולו בעשור לחודש אלא שקצתם לא מלו אז ומלו א\"ע בליל טו („ואליהם כוונת רש\"י ב„מלו באותו הלילה\"\"), ע\"ש — אבל (נוסף על מה שיש להקשות בגוף פירושו, כדלקמן הערה 18, הרי) ענין זה לא נמצא בפרש\"י, אפילו לא ברמז. ומסתימת לשונו „מלו באותו הלילה .. מתבוססת בדמיך\" משמע, שמדבר רק ע\"ד מילת בנ\"י בליל טו."],["16","16","בהמשך לשונו — ובמכילתא הובא רק לשון הכתוב „מתבוססת בדמיך\"."],["17","17","יחזקאל שם, ו."],["18","18","וכן מפורש בשמו\"ר פי\"ט, ה. שהש\"ר פ\"א, יב (ג). וכן מוכח לפי דחז\"ל (פדר\"א פכ\"ט. תיב\"ע פרשתנו שם, יג. ועוד) דגם מדם מילה נתנו לאות על הבתים. ולהעיר, שלפרש\"י (לקמן פסוק מג) האזהרה ד„כל ערל לא יאכל בו\" (שם, מח) נאמרה בי\"ד בניסן [ועפ\"ז צ\"ע במ\"ש במשכיל לדוד כאן, דמה שהקדים לקיחתו לעשור בחודש הוא „כדי שיתרצו למול א\"ל ויקחו .. להזכירם שהם צריכים לעשות הפסח וכל בן נכר לא יאכל בו כו'\" — שהרי אזהרה זו נאמרה לאחרי זה בי\"ד]."]]],[1300161131,"ג. ווייטער איז רש\"י ממשיך: „ושהיו שטופים באלילים אמר להם משכו וקחו לכם19, משכו ידיכם מאלילים וקחו לכם צאן של מצוה\".\nדער ענין איז ניט דער סיום המאמר פון רמב\"ח. דאס איז גאר די דיעה פון רבי אליעזר הקפר20 (אין מכילתא דארט), בר פלוגתי' דרמב\"ח (וואס ר\"א האלט אז אידן האבן יע געהאט מצות, ואדרבא „ארבעה מצות שאין כל העולם כדאי בהם\").\nאיז תמוה: וויבאלד אז דאס זיינען דיעות מחולקות, האט דאך רש\"י גע־דארפט זאגן „דבר אחר\", אדער „ויש אומרים\" (וכיו\"ב) — פארוואס זאגט ער „ושהיו שטופים כו'\", מיט א וא\"ו המוסיף, אז דאס איז גאר א המשך צום מאמר פון רמב\"ח?\nד. פון דעם פירוש רש\"י האט מען אויך א דוגמא בולטת צום כלל (וועלכן מ'האט שוין מדגיש געווען כמה פעמים), אז בשעת רש\"י ברענגט בפירושו א מאמר חז\"ל בשם אומרו, איז עס מצד א טעם מיוחד, דערפאר וואס דורך דער ידיעה ווער ס'איז דער בעל המאמר, קומט צו א תוספת ביאור אין דעם מאמר, וועלכער איז נוגע לפירוש רש\"י.\nבנדו\"ד ברענגט רש\"י פון מכילתא צוויי פירושים, איינער גלייך נאכן צווייטן: איז ביים ערשטן איז ער מעתיק דעם שם פון בעל המאמר — ר' מתיא בן חרש — אבער ביים צווייטן איז ער משמיט שם אומרו21!\nמוז מען זאגן, אז מיטן מעתיק זיין\nדעם שם פון ר' מתיא בן חרש איז רש\"י (ניט אויסן סתם צו זאגן דבר בשם אומרו, נאר ער איז) דערמיט מוסיף אין הבנת הפירוש (משא\"כ בנוגע דעם טעם פון „ושהיו שטופים כו'\").\nאויך דארף מען פארשטיין: רש\"י באנוגנט זיך ניט מיט סתם ברענגען דעם נאמען ר' מתיא בן חרש, נאר ער איז מעתיק דעם לשון המכילתא — „הי' ר' מתיא בן חרש אומר\" (אז ער פלעגט (כסדר) אזוי זאגן) — וואס גיט צו אט דער פרט אין דער הבנה פון דעם פירוש22?\nה. דער ביאור בכל זה:\nדאס וואס רש\"י זאגט „ושהיו שטופים כו'\" (ניט „ד\"א\" וכיו\"ב) — איז עס ווייל ע\"ד הפשט — וואס דאס איז דרך פרש\"י — איז אין די ווערטער פון ר' מתיא בן חרש ניטא קיין תירוץ וביאור אויף דער שאלה „מפני מה הקדים לקיחתו לשחיטתו ארבעה ימים\" (וכנ\"ל, אז אין זיין מאמר דערמאנט ער בכלל ניט וועגן לקיחת השה)23;\nדער תירוץ (ע\"ד הפשט) אויף דער שאלה איז אין דעם סיום פון רש\"י „שהיו שטופים באלילים א\"ל משכו וקחו לכם כו'\",\nוואס דאס מיינט (ניט נאר אז בכדי זיי זאלן זיין ראוי צו „קחו לכם צאן של מצוה\", דארפן זיי פריער דורכגיין דעם „משכו ידיכם מאלילים\", ווייל אנדערש",[["19","19","פרשתנו שם, כא."],["20","20","ראה רא\"ם (ועוד) כאן."],["21","21","ובפרט שנותן מקום לטעות שזהו המשך דברי רמב\"ח."],["22","22","להעיר שבדפוס שני דרש\"י לא העתיק תיבת „הי'\"."],["23","23","ראה גם ש\"ך עה\"ת כאן (ושם, שזהו הדיוק „הי' רמב\"ח אומר כו'\", כי רמב\"ח לא בא לתרץ למה קדמה לקיחתו כו' אלא שבעל המכילתא מביא ש„הי' רמב\"ח אומר כו'\" כי ע\"פ דרשתו מתורצת גם שאלה זו, ע\"ש. וראה גם אלשיך כאן)."]]],[1300161132,"טאר מען ניט עסן פון קרבן פסח24, נאר\nאז דערמיט גופא וואס זיי וועלן נעמען דעם „צאן של מצוה\", וועלן זיי מבטל זיין דאס וואס „היו שטופים באלילים\" (כדלקמן סעיף ז'), און דערצו פאדערט זיך אז דער שה זאל זיין אין זייער רשות במשך פון פיר טעג פאר דער שחיטה (כדלקמן שם).\nנאר עס פאדערט זיך (לויט רש\"י) א הקדמה צו דעם: דער עיקר מטרה פון קרבן פסח (מצרים), לויט פשטות הכתובים, איז כשמו — „פסח על שם הדלוג והפסיחה\"25, אז דער דם הפסח איז געווען א סימן וואו וועט „הקב\"ה מדלג כו' וקופץ כו'\"25 זיין.\nוואס פאר א שייכות האט דאס מיטן מבטל זיין דעם „היו שטופים באלילים\"?\nאיז רש\"י מקדים דעם מאמר פון רמב\"ח, אז דער עיקר מטרה פון די מצות וואס דער אויבערשטער האט גע־געבן אידן פאר דער גאולה, איז געווען צו מבטל זיין דעם מצב פון „ואת ערום וערי'\", זיי זאלן האבן „מצות להתעסק בהם (און דאס איז) כדי שיגאלו\";\nאון וויבאלד אז „נתן להם שתי מצות דם פסח ודם מילה\", איז פארשטאנדיק, אז עיקר מטרת הפסח (בנוגע דעם אראפנעמען דעם „ערום וערי'\") איז (ניט דער ענין חיובי שבו — זיין שחיטה ואכילה וכו', נאר) אן ענין שלילי, צו אראפנעמען אן ענין בלתי רצוי, כדלקמן.\nו. לערנענדיק דעם מאמר פון רמב\"ח, אז „נתן להם שתי מצות כו'\" — ווייל אידן זיינען געווען אין א מצב פון „ואת ערום וערי'\" — ווערט שווער:\nוואס איז דער חשבון פון „שתי מצות\" — ממה נפשך: צו אראפנעמען דעם חסרון פון „ערום\" (מן המצות) איז גענוג איין מצוה; און אויב — לויט דער הנהגה פון כי תראה ערום וכסיתו26 — האט דער אויבערשטער געוואלט זיי געבן מער „לבושים\", זכיות — מצות — איז פארוואס גענוג27 צוויי מצות28?\nדער ביאור אין דעם: יעדע פון די צוויי מצות האט אראפגענומען אן אנ־דער פרט פון דעם מצב פון „ערום וערי'\" (ממצות). ביי אידן איז דאן גע־ווען א צווייענדיקער חסרון29:\nא) זיי האט געפעלט דער עשה טוב, קיום פון מצות, ובמילא האבן זיי ניט געהאט מיט וואס צו גיין צום „תעבדון את האלקים על ההר הזה\"30 (וואס אין דעם זכות איז געווען דער „הוציאך את העם ממצרים\"<sup data-n=\"30\">30</sup>:\nב) זיי האט געפעלט אין סור מרע, צו זיי האט זיך צוגעקלעפט פון דעם רע של ארץ מצרים, „ערות הארץ\" — ובמילא, אפילו ווען זיי האבן שוין „מצות להתעסק בהם\", איז אויב מ'זאל פון זיך ניט אראפנעמען דעם רע פון מצרים, קען ניט זיין „שיגאלו\" — אינגאנצן ארויס פון ארץ מצרים — מ'גייט ארויס פון ארץ מצרים און דער רע של מצרים איז אין זיי31!",[["24","24","פרשתנו שם, מג ובפרש\"י."],["25","25","פרש\"י שם, יא."],["26","26","ישעי' נח, ז. וראה לקמן סעיף יוד ובהערה 61, 62."],["27","27","להעיר ממרז\"ל (מכות כג, ב במשנה) רצה הקב\"ה לזכות את ישראל לפיכך הרבה להם תומ\"צ."],["28","28","ראה — ע\"ד הדרוש — גו\"א כאן. גבורות ה' פל\"ה."],["29","29","וכב' הלשונות „ערום וערי'\". וראה ריטב\"א להגש\"פ, שמפרש „ערום\" — ערומים מן המצות, „ומהו ערי' . . שלא קיימו מצות מילה\"."],["30","30","שמות ג, יב וברש\"י."],["31","31","ע\"פ המבואר בפנים יש לבאר זה שהעתיק"]]],[1300161133,"האט מען זיי דעריבער געגעבן צוויי מצות32: איין מצוה וואס טוט אויף „עשה טוב\" — און דאס איז דם מילה33, וואס ברענגט אריין די אידן בברית מיטן אויבערשטן34; און איין מצוה וואס טוט אויף זיי „סור מרע\" (אראפנעמען דעם רע פון מצרים) — און דאס איז דם פסח33 (כדלקמן סעיף ז).\n[דערמיט ווערט בעסער פארשטאנ־דיק וואס מ'איז מדגיש אז מען האט זיי געגעבן דם פסח אלס א מצוה להתעסק בה כדי שיגאלו — דלכאורה: דער עיקר\nרש\"י (בראי' הב' — מזכרי' ט, יא) גם סיום הכתוב „גם את בדם בריתך שלחתי אסיריך\" מבור אין מים בו\" — דלכאורה אין זה מוסיף כלום בהראי' —\nכי בתיבות אלו מרמז רש\"י לפירושו בפ' וישב עה\"פ (לז, כד) „והבור רק אין בו מים\" — „מים אין בו אבל נחשים ועקרבים יש בו\", היינו דכאשר „מים אין בו\" באים בו במילא נחשים ועקרבים (ראה לקו\"ש חט\"ו ע' 324 ואילך); ועד\"ז בענינינו, דמכיון ש„לא היו בידם מצות\" בדרך ממילא נעשו „שטופים באלילים\" (נתדבק בהם הרע של מצרים).\n32) ראה גם גבורות ה' שם (אלא ששם מפרש, דמילה היא הסרת הערלה והפסח הוא עבודתו לו ית'. וראה הערה הבאה).<sup data-n=\"33\">33</sup> ראה עד\"ז אלשיך כאן. וראה אוה\"ת יתרו (כרך ז' ע' ב'תרצו): פסח הוא מל'. . ובה מל\"ח . . ז\"א שבו מ\"ה והיינו ע\"י מילה* יסוד ז\"א (וראה שם ע' ב'תרחצ). ובאוה\"ת שה\"ש (ע' תפז): במצרים בשתי מצות בדם הפסח ובדם המילה . . דם פסח ה' גבורות שבמלכות ודם מילה ה' חסדים שביסוד.\nועפ\"ז מתורץ מה שהקדים (רמב\"ח ו)רש\"י דם פסח לדם מילה — מתאים להסדר (בקרא) סור מרע (ואח\"כ) ועשה טוב (ראה אלשיך שם); וכן הי' גם אצל בנ\"י במצרים (גם לרש\"י), שהרי פסח הי' בין הערביים, ומילה — „באותו הלילה\".\n34) וגם: מכיון שהי' צ\"ל תיקון ע\"י שלא קיימו מצות, הי' צ\"ל ע\"י מצוה שהיו מחוייבים בה מכבר, ולא מצוה שנתחדשה רק עתה.\n*) להעיר דמצות מילה היא (לא רק שלא יהא ערל, כ\"א גם) שיהא מהול (ראה צפע\"נ לרמב\"ם ריש הל' מילה, ובכ\"מ. לקו\"ש ח\"ג ע' 759 ואילך. וראה ע\"ד החסידות סהמ\"צ להצ\"צ מצות מילה. אוה\"ת בראשית כרך ד' ס\"פ לך).\nמצוה פון קרבן פסח (אויך אין פשוטו של מקרא), איז — די אכילת הפסח35\n(ווי מ'זעט עס גלייך ביי לקיחת השה, אז עס דארף זיין „שה לבית\" אין אן אופן פון „מכסת נפשות איש לפי אכלו גו'\"36, דוקא איינער וואס איז „ראוי לאכילה, פרט לחולה כו'\"<sup data-n=\"37\">37</sup>?\nוע\"פ הנ\"ל איז עס פארשטאנדיק. ווייל דם הפסח איז מדגיש די שלילה37* — מבטל זיין דעם רע פון מצרים].\nז. ווי אזוי איז דם הפסח פארבונדן מיט „סור מרע\"?\nאויך: וויבאלד אז „לא היו בידם מצות\", איז פארשטאנדיק, אז די מצות וואס „נתן להם\" זיינען מצות כלליות38; וע\"ד מצות מילה וואס איז (ניט נאר א מצוה פרטית, נאר) א מצוה כללית, ס'איז דער „אות ברית ביני וביניכם\"*38 — דארף מען זאגן, אז אויך דם פסח טוט אויף אן ענין עיקרי וכללי (אין „סור מרע\"). וואו זעט מען דעם ענין כללי בזה?\nאיז רש\"י ממשיך „ושהיו שטופים באלילים א\"ל משכו וקחו לכם, משכו ידיכם מאלילים וקחו לכם צאן של מצוה\" — דער פסח האט מבטל געווען דאס וואס אידן זיינען געווען „שטופים",[["35","35","בלשון המשנה (פסחים עו, ב) — הפסח „לא בא מתחילתו אלא לאכילה\"."],["36","36","פרשתנו שם, ג־ד."],["37","37","רש\"י שם. *37) עפ\"ז יש לתרץ ג\"כ מ\"ש במשכיל לדוד ש„מצות הפסח (לחוד) אין בה כדאי שהיא מצוה שאין בה שום צערא דגופא אדרבה הנאה וטעמא\" — כי העיקר במצות הפסח כאן הוא „דם פסח\", שלילת הרע, כבפנים."],["38","38","להעיר ממחז\"ל (כריתות בתחלתה): ל\"ו כריתות בתורה כו' הפסח והמילה במצות עשה. וראה אוה\"ת יתרו שם. *38) לך יז, יא. וראה גו\"א כאן."]]]]});
